"""Interchange reference, not a complete application or semantic entailment oracle.

These validators enforce structural/provenance boundaries. They do not prove that
an observation is true, that a citation semantically entails a claim, or that an
intervention causally identified a fault. Those require the specified evaluation.
"""
from __future__ import annotations
import math
from typing import Literal
from pydantic import BaseModel, ConfigDict, Field, model_validator

class StrictModel(BaseModel):
    model_config = ConfigDict(extra="forbid", allow_inf_nan=False)

class Span(StrictModel):
    start_ms: int = Field(ge=0, strict=True)
    end_ms: int = Field(gt=0, strict=True)

    @model_validator(mode="after")
    def ordered(self):
        if self.end_ms <= self.start_ms:
            raise ValueError("Media spans are nonempty half-open intervals")
        return self

class Confidence(StrictModel):
    kind: Literal["uncalibrated_score", "calibrated_probability", "not_applicable"]
    value: float | None = None
    calibration_artifact: str | None = None

    @model_validator(mode="after")
    def calibrated(self):
        if self.kind == "calibrated_probability":
            if self.value is None or not 0 <= self.value <= 1 or not self.calibration_artifact:
                raise ValueError("Probability needs value in [0,1] and a calibration artifact")
        if self.kind == "not_applicable" and self.value is not None:
            raise ValueError("Not-applicable confidence cannot carry a numeric value")
        if self.kind == "uncalibrated_score" and self.value is None:
            raise ValueError("An uncalibrated score requires a recorded value")
        return self

class Component(StrictModel):
    id: str = Field(min_length=1)
    label: str = Field(min_length=1)
    role: Literal["ground", "crank", "coupler", "rocker", "slider", "other"]
    length_mm: float | None = Field(default=None, gt=0)

class Joint(StrictModel):
    id: str
    a: str
    b: str
    kind: Literal["fixed", "revolute", "prismatic"]

    @model_validator(mode="after")
    def distinct(self):
        if self.a == self.b:
            raise ValueError("A joint must connect distinct components")
        return self

class BoardReference(StrictModel):
    width_mm: float = Field(gt=0)
    height_mm: float = Field(gt=0)

class SliderCrankGeometry(StrictModel):
    kind: Literal["slider_crank"]
    ground_pivot_mm: tuple[float, float]
    track_angle_rad: float = 0.0
    crank_radius_mm: float = Field(gt=0)
    rod_length_mm: float = Field(gt=0)
    track_offset_mm: float = 0.0
    initial_crank_angle_rad: float = 0.0
    branch: Literal[-1, 1] = 1

class FourBarGeometry(StrictModel):
    kind: Literal["four_bar"]
    ground_pivot_mm: tuple[float, float]
    ground_axis_angle_rad: float = 0.0
    ground_length_mm: float = Field(gt=0)
    crank_length_mm: float = Field(gt=0)
    coupler_length_mm: float = Field(gt=0)
    rocker_length_mm: float = Field(gt=0)
    initial_crank_angle_rad: float = 0.0
    branch: Literal[-1, 1] = 1

class DesignVersion(StrictModel):
    schema_version: Literal["0.1"] = "0.1"
    project_id: str
    version_id: str
    parent_version_id: str | None = None
    source_format: Literal["mv-design-0.1", "manual-design-0.1"]
    units: Literal["mm"] = "mm"
    mechanism_kind: Literal["slider_crank", "four_bar"]
    geometry: SliderCrankGeometry | FourBarGeometry = Field(discriminator="kind")
    board: BoardReference
    components: list[Component] = Field(min_length=3, max_length=16)
    joints: list[Joint] = Field(min_length=2)
    actuator_component_id: str
    source_sha256: str = Field(pattern=r"^[0-9a-f]{64}$")

    @model_validator(mode="after")
    def graph(self):
        ids = [c.id for c in self.components]
        if len(set(ids)) != len(ids):
            raise ValueError("Duplicate component ID")
        if not any(c.role == "ground" for c in self.components):
            raise ValueError("A grounded reference is required")
        if self.actuator_component_id not in ids:
            raise ValueError("Actuator is not a component")
        if len({j.id for j in self.joints}) != len(self.joints):
            raise ValueError("Duplicate joint ID")
        if any(j.a not in ids or j.b not in ids for j in self.joints):
            raise ValueError("Joint references unknown component")
        if self.geometry.kind != self.mechanism_kind:
            raise ValueError("Mechanism kind differs from geometry")
        required_roles = {"ground", "crank", "coupler", "slider" if self.mechanism_kind == "slider_crank" else "rocker"}
        if len(self.components) != 4 or {c.role for c in self.components} != required_roles:
            raise ValueError("v0.1 supported mechanisms require exactly one component per canonical role")
        by_role = {c.role: c for c in self.components}
        if self.actuator_component_id != by_role["crank"].id:
            raise ValueError("v0.1 actuator must be the crank")
        expected_lengths = ({"crank": self.geometry.crank_radius_mm, "coupler": self.geometry.rod_length_mm}
                            if isinstance(self.geometry, SliderCrankGeometry)
                            else {"ground": self.geometry.ground_length_mm, "crank": self.geometry.crank_length_mm,
                                  "coupler": self.geometry.coupler_length_mm, "rocker": self.geometry.rocker_length_mm})
        for role, length in expected_lengths.items():
            if by_role[role].length_mm is None or not math.isclose(by_role[role].length_mm, length, rel_tol=1e-6, abs_tol=1e-6):
                raise ValueError("Component length differs from canonical geometry")
        ids_to_roles = {c.id: c.role for c in self.components}
        actual_joints = {(frozenset((ids_to_roles[j.a], ids_to_roles[j.b])), j.kind) for j in self.joints}
        tail = "slider" if self.mechanism_kind == "slider_crank" else "rocker"
        expected_joints = {(frozenset(("ground", "crank")), "revolute"),
                           (frozenset(("crank", "coupler")), "revolute"),
                           (frozenset(("coupler", tail)), "revolute"),
                           (frozenset((tail, "ground")), "prismatic" if tail == "slider" else "revolute")}
        if len(self.joints) != 4 or actual_joints != expected_joints:
            raise ValueError("Joint topology is not a supported canonical mechanism")
        if self.parent_version_id == self.version_id:
            raise ValueError("A version cannot be its own parent")
        return self

class AssemblyComponent(StrictModel):
    """One placed instance in an assembly design (mv-design-0.2, ADR 005 D32).

    ``design_ref`` is the source identity of the placed item (e.g. an LDraw
    part design number or sub-model name); ``color_code`` is the source
    colour code when recorded. Geometry itself stays in the source document;
    this record is structural, not a mesh.
    """
    id: str = Field(min_length=1)
    kind: Literal["part", "sub_assembly"]
    design_ref: str | None = Field(default=None, min_length=1)
    label: str = Field(min_length=1)
    color_code: int | None = None

class BuildStep(StrictModel):
    index: int = Field(ge=1, strict=True)
    component_ids: list[str] = Field(min_length=1)
    transform_note: str | None = None
    source_ref: str | None = Field(default=None, min_length=1)

class DesignLicense(StrictModel):
    """Per-model license record (ADR 005 invariant: verified before repo entry)."""
    statement: str = Field(min_length=1)  # verbatim license line content
    license_ids: list[Literal["CC-BY-4.0", "CC-BY-2.0", "other"]] = Field(min_length=1)
    source_url: str | None = None
    verified_by: str = Field(min_length=1)
    verified_on: str | None = None  # ISO-8601 date recommended

class AssemblyDesignVersion(StrictModel):
    """Assembly design (mv-design-0.2): structural build record, no kinematic claims.

    Unlike the v0.1 mechanism contract, components are unbounded placed
    instances and build steps carry construction order. Mechanism analysis
    (expected motion, phase alignment) is typed-absent for assembly designs
    until separately implemented (docs/23 C2).
    """
    schema_version: Literal["0.2"] = "0.2"
    project_id: str
    version_id: str
    parent_version_id: str | None = None
    source_format: Literal["mv-design-0.2", "manual-design-0.2", "ldraw-import-0.2"]
    units: Literal["mm"] = "mm"
    design_kind: Literal["assembly"] = "assembly"
    components: list[AssemblyComponent] = Field(min_length=1)
    build_steps: list[BuildStep] = Field(default_factory=list)
    joints: list[Joint] = Field(default_factory=list)
    license: DesignLicense | None = None
    source_sha256: str = Field(pattern=r"^[0-9a-f]{64}$")

    @model_validator(mode="after")
    def assembly_graph(self):
        if self.parent_version_id == self.version_id:
            raise ValueError("A version cannot be its own parent")
        ids = [c.id for c in self.components]
        if len(set(ids)) != len(ids):
            raise ValueError("Duplicate component ID")
        if self.source_format == "ldraw-import-0.2" and self.license is None:
            raise ValueError("An LDraw-sourced assembly must record its verified license")
        placed: set[str] = set()
        for i, step in enumerate(self.build_steps, start=1):
            if step.index != i:
                raise ValueError("Build steps are contiguous 1-based placements")
            for cid in step.component_ids:
                if cid not in ids:
                    raise ValueError("Build step references unknown component")
                if cid in placed:
                    raise ValueError("A component instance is placed in more than one step")
                placed.add(cid)
        for j in self.joints:
            if j.a not in ids or j.b not in ids:
                raise ValueError("Joint references unknown component")
        return self

class Asset(StrictModel):
    id: str
    project_id: str
    design_version_id: str
    kind: Literal["video", "image", "audio", "text", "design", "inspection"]
    duration_ms: int | None = Field(default=None, gt=0, strict=True)
    audio_status: Literal["present", "missing", "not_applicable"] = "not_applicable"
    status: Literal["active", "deleted"] = "active"
    origin: Literal["synthetic_contract_fixture", "synthetic_media", "approved_real"]
    # docs/04 line 13: privacy class + consent-use flags (ADR 001). Defaults
    # keep v0.1 records valid; the consent policy gate enforces actual use.
    privacy_class: Literal["synthetic_public", "approved_restricted"] = "synthetic_public"
    consent_use_flags: list[Literal["analysis", "teaching_review", "research_export"]] = Field(
        default_factory=list
    )
    sha256: str = Field(pattern=r"^[0-9a-f]{64}$")

    @model_validator(mode="after")
    def media(self):
        if self.kind in ("video", "audio") and self.duration_ms is None:
            raise ValueError("Temporal media needs a duration")
        if self.kind not in ("video", "audio") and self.audio_status != "not_applicable":
            raise ValueError("Nontemporal assets cannot claim an audio track")
        if self.kind not in ("video", "audio") and self.duration_ms is not None:
            raise ValueError("Nontemporal assets cannot carry media duration")
        if self.kind == "audio" and self.audio_status != "present":
            raise ValueError("An audio asset must contain audio")
        real = self.origin == "approved_real"
        if real and self.privacy_class != "approved_restricted":
            raise ValueError("Approved real media must declare privacy_class=approved_restricted")
        if not real and self.privacy_class != "synthetic_public":
            raise ValueError("Synthetic-origin media cannot claim approved_restricted class")
        return self

class Verification(StrictModel):
    method: Literal["independent_inspection", "controlled_intervention"]
    verified_by: str = Field(min_length=1)
    record_id: str = Field(min_length=1)
    remaining_alternatives: list[str] = Field(default_factory=list)

class EvidenceItem(StrictModel):
    id: str
    project_id: str
    design_version_id: str
    asset_id: str
    modality: Literal["visual", "acoustic", "text", "design", "inspection"]
    record_kind: Literal["observation", "reported_explanation", "design_fact", "hypothesis", "inspection"]
    statement: str = Field(min_length=1)
    component_ids: list[str] = Field(default_factory=list)
    span: Span | None = None
    status: Literal["active", "superseded", "retracted"] = "active"
    analyzer: str
    analyzer_version: str
    confidence: Confidence
    verification: Verification | None = None

class Citation(StrictModel):
    evidence_id: str
    temporal_role: Literal["current", "historical"] = "current"
    historical_note: str | None = None

    @model_validator(mode="after")
    def history(self):
        if self.temporal_role == "historical" and not self.historical_note:
            raise ValueError("Historical evidence must be identified as history")
        return self

class Claim(StrictModel):
    id: str
    kind: Literal["observation", "reported_explanation", "hypothesis", "verified_cause"]
    text: str = Field(min_length=1)
    citations: list[Citation] = Field(min_length=1)
    uncertainty: str | None = None

    @model_validator(mode="after")
    def qualify(self):
        if self.kind == "hypothesis" and not self.uncertainty:
            raise ValueError("A hypothesis must retain an uncertainty statement")
        return self

class TeacherContext(StrictModel):
    goal: Literal["diagnose", "predict", "compare", "reflect"]
    grade_band: str | None = None
    prior_concepts: list[str] = Field(default_factory=list)
    remaining_minutes: int = Field(ge=0, le=180)
    preferred_intervention: Literal["observe", "ask", "investigate", "explain"]
    disclosure_ceiling: Literal["question", "hint", "explanation"]

class NextStep(StrictModel):
    kind: Literal["observe", "ask", "investigate", "explain"]
    disclosure: Literal["question", "hint", "explanation"]
    text: str = Field(min_length=1)
    estimated_seconds: int = Field(ge=0, le=1800)
    teacher_approval_required: Literal[True] = True
    rationale: str | None = None
    student_question: str | None = None

class GuidanceAnswer(StrictModel):
    schema_version: Literal["0.1"] = "0.1"
    id: str
    project_id: str
    selected_version_id: str
    snapshot_id: str
    claims: list[Claim]
    next_steps: list[NextStep] = Field(max_length=2)
    missing_evidence: list[str] = Field(default_factory=list)
    cautions: list[str] = Field(default_factory=list)
    context: TeacherContext
    mode: Literal["template", "local_model", "fixture"]
    status: Literal["draft", "validated", "stale", "retracted"]

    @model_validator(mode="after")
    def disclosure(self):
        levels = {"question": 0, "hint": 1, "explanation": 2}
        if any(levels[s.disclosure] > levels[self.context.disclosure_ceiling] for s in self.next_steps):
            raise ValueError("Teacher disclosure ceiling exceeded")
        return self

class EvidenceBundle(StrictModel):
    schema_version: Literal["0.1"] = "0.1"
    project_id: str
    snapshot_id: str
    assets: list[Asset]
    evidence: list[EvidenceItem]
    answer: GuidanceAnswer

    @model_validator(mode="after")
    def integrity(self):
        assets = {x.id: x for x in self.assets}
        evidence = {x.id: x for x in self.evidence}
        if len(assets) != len(self.assets) or len(evidence) != len(self.evidence):
            raise ValueError("Duplicate asset or evidence IDs")
        if self.answer.project_id != self.project_id or self.answer.snapshot_id != self.snapshot_id:
            raise ValueError("Answer scope/snapshot does not match bundle")
        for a in self.assets:
            if a.project_id != self.project_id:
                raise ValueError("Cross-project asset")
        for e in self.evidence:
            if e.project_id != self.project_id or e.asset_id not in assets:
                raise ValueError("Evidence scope or source is invalid")
            a = assets[e.asset_id]
            if e.design_version_id != a.design_version_id:
                raise ValueError("Evidence version differs from source asset")
            if e.span is not None:
                if a.duration_ms is None or e.span.end_ms > a.duration_ms:
                    raise ValueError("Evidence interval outside temporal source")
            allowed_sources = {"visual": {"image", "video"}, "acoustic": {"audio", "video"},
                               "text": {"text", "audio", "video"}, "design": {"design"}, "inspection": {"inspection"}}
            if a.kind not in allowed_sources[e.modality]:
                raise ValueError("Evidence modality is incompatible with source kind")
            if e.modality == "visual" and a.kind == "video" and e.span is None:
                raise ValueError("Visual video evidence needs a source interval")
            if e.modality == "text" and a.kind in ("video", "audio") and (a.audio_status != "present" or e.span is None):
                raise ValueError("A media transcript needs present audio and a source interval")
            if e.record_kind == "design_fact" and e.modality != "design":
                raise ValueError("A design fact requires design evidence")
            if e.record_kind == "inspection" and e.modality != "inspection":
                raise ValueError("An inspection record requires inspection evidence")
            if e.modality == "acoustic":
                if a.kind not in ("audio", "video") or a.audio_status != "present" or e.span is None:
                    raise ValueError("Acoustic evidence needs present audio and a valid interval")
            if e.modality == "inspection" and a.kind != "inspection":
                raise ValueError("Inspection evidence needs an inspection source")
            if e.verification is not None and e.record_kind != "inspection":
                raise ValueError("Verification provenance belongs to an inspection record")
        for claim in self.answer.claims:
            resolved = []
            for c in claim.citations:
                if c.evidence_id not in evidence:
                    raise ValueError("Unresolvable evidence citation")
                e = evidence[c.evidence_id]
                a = assets[e.asset_id]
                if self.answer.status in ("draft", "validated") and (e.status != "active" or a.status != "active"):
                    raise ValueError("Inactive evidence cannot support a newly validated answer")
                if c.temporal_role == "current" and e.design_version_id != self.answer.selected_version_id:
                    raise ValueError("Stale version passed as current evidence")
                resolved.append(e)
            if claim.kind == "observation" and any(e.record_kind in ("hypothesis", "reported_explanation") for e in resolved):
                raise ValueError("A hypothesis/report cannot be promoted to an observed fact")
            if claim.kind == "reported_explanation" and not any(e.record_kind == "reported_explanation" for e in resolved):
                raise ValueError("Reported explanation needs an attributed report")
            if claim.kind == "verified_cause" and not any(e.record_kind == "inspection" and e.verification is not None for e in resolved):
                raise ValueError("Verified cause needs independent verification provenance")
        return self

