"""A deterministic guidance policy reference, not a pedagogical efficacy model."""
from .models import TeacherContext, NextStep


def choose_next_step(context: TeacherContext, *, input_observed: bool,
                     ambiguous_overlap: bool, side_view_available: bool) -> NextStep:
    if not input_observed:
        return NextStep(kind="ask", disclosure="question", text="What is the crank doing during the pause? A view showing input and output together would help.", estimated_seconds=30)
    if ambiguous_overlap and not side_view_available and context.remaining_minutes >= 2:
        return NextStep(kind="investigate", disclosure="question", text="Would a side-view recording distinguish projected overlap from possible contact?", estimated_seconds=60)
    if context.goal == "compare":
        text = "What is moving before the pause, and what is still moving during it?"
    elif context.goal == "predict":
        text = "What observation would you predict if the two parts are not actually touching?"
    elif context.goal == "reflect":
        text = "Which observation changed your explanation, and what is still uncertain?"
    else:
        text = "What evidence would help distinguish the remaining explanations?"
    return NextStep(kind="ask", disclosure="question", text=text, estimated_seconds=30)

