"""HTTP Range header parsing for authenticated media responses (RFC 9110).

Only single byte ranges are served; multipart ranges are rejected so a
partial media response can never be assembled by a client that lacks scope
for the rest of the asset.
"""
from __future__ import annotations

from dataclasses import dataclass


class InvalidRange(ValueError):
    """Unsatisfiable or malformed Range header (maps to 416/400)."""

    def __init__(self, message: str, *, satisfiable: bool = False) -> None:
        super().__init__(message)
        self.message = message
        # satisfiable=False means the header was syntactically valid but the
        # range lies outside the representation (416); True-side parsing
        # errors keep satisfiable True so callers can pick 400 vs 416.
        self.satisfiable = satisfiable


@dataclass(frozen=True)
class ByteRange:
    start: int
    end: int  # inclusive, per RFC 9110 Range semantics

    @property
    def length(self) -> int:
        return self.end - self.start + 1


def parse_range(header: str | None, size: int) -> ByteRange | None:
    """Parse a single-range ``Range`` header against a representation ``size``.

    Returns ``None`` when the header is absent (full body). Raises
    ``InvalidRange`` for malformed headers or ranges that start beyond the
    representation.
    """
    if header is None or header == "":
        return None
    if size <= 0:
        raise InvalidRange("Representation is empty", satisfiable=True)
    value = header.strip()
    if not value.lower().startswith("bytes="):
        raise InvalidRange("Only byte ranges are supported")
    spec = value[len("bytes="):].strip()
    if "," in spec:
        raise InvalidRange("Multipart ranges are not supported")
    if "-" not in spec:
        raise InvalidRange("Malformed byte range")
    first, _, last = spec.partition("-")
    first, last = first.strip(), last.strip()
    if first == "":
        # suffix form: bytes=-N requests the final N bytes
        if not last.isdigit():
            raise InvalidRange("Malformed suffix range")
        suffix = int(last)
        if suffix == 0:
            raise InvalidRange("Unsatisfiable suffix range", satisfiable=True)
        start = max(0, size - suffix)
        return ByteRange(start=start, end=size - 1)
    if not first.isdigit():
        raise InvalidRange("Malformed byte range")
    start = int(first)
    if start >= size:
        raise InvalidRange("Range start beyond representation", satisfiable=True)
    if last == "":
        return ByteRange(start=start, end=size - 1)
    if not last.isdigit():
        raise InvalidRange("Malformed byte range end")
    end = int(last)
    if end < start:
        raise InvalidRange("Range end precedes start")
    return ByteRange(start=start, end=min(end, size - 1))

