"""Processing-job state machine and idempotency keys (docs/03 DAG).

Job identity is ``(asset_sha256, analyzer_name, analyzer_version,
config_hash, parent_snapshot_hash)``. A repeated key must not create a second
analysis of the same provenance; a worker crash cannot produce two
observations with one provenance key.
"""
from __future__ import annotations

import enum
from dataclasses import dataclass

from .hashing import canonical_json_sha256


class JobState(str, enum.Enum):
    QUEUED = "queued"
    RUNNING = "running"
    SUCCEEDED = "succeeded"
    PARTIAL = "partial"
    FAILED = "failed"
    CANCELED = "canceled"


QUEUED = JobState.QUEUED.value
RUNNING = JobState.RUNNING.value
SUCCEEDED = JobState.SUCCEEDED.value
PARTIAL = JobState.PARTIAL.value
FAILED = JobState.FAILED.value
CANCELED = JobState.CANCELED.value

TERMINAL_STATES = frozenset(
    {JobState.SUCCEEDED, JobState.PARTIAL, JobState.FAILED, JobState.CANCELED}
)

# Allowed transitions. canceled is reachable from queued/running only.
TRANSITIONS: dict[JobState, frozenset[JobState]] = {
    JobState.QUEUED: frozenset({JobState.RUNNING, JobState.CANCELED}),
    JobState.RUNNING: frozenset(
        {JobState.SUCCEEDED, JobState.PARTIAL, JobState.FAILED, JobState.CANCELED}
    ),
    JobState.SUCCEEDED: frozenset(),
    JobState.PARTIAL: frozenset(),
    JobState.FAILED: frozenset(),
    JobState.CANCELED: frozenset(),
}

# Transient I/O is retried twice with exponential backoff; deterministic
# invalid media is never retried (docs/03).
MAX_TRANSIENT_RETRIES = 2


def is_terminal(state: str | JobState) -> bool:
    return JobState(state) in TERMINAL_STATES


def assert_transition(current: str | JobState, target: str | JobState) -> None:
    """Raise ``ValueError`` on an illegal state transition."""
    try:
        current_state = JobState(current)
        target_state = JobState(target)
        allowed = TRANSITIONS[current_state]
    except (KeyError, ValueError) as exc:
        raise ValueError(f"Unknown job state: {current!r}") from exc
    if target_state not in allowed:
        raise ValueError(f"Illegal job transition {current_state.value} -> {target_state.value}")


def assert_recovery_requeue(current: str | JobState) -> None:
    """Heartbeat-recovery requeue of an orphaned ``running`` job (docs/03).

    This is the only path back to ``queued`` and it exists solely for orphan
    recovery after a worker crash; normal execution may never use it.
    """
    if JobState(current) is not JobState.RUNNING:
        raise ValueError("Only running jobs can be requeued by recovery")


@dataclass(frozen=True)
class IdempotencyKey:
    asset_sha256: str
    analyzer_name: str
    analyzer_version: str
    config_hash: str
    parent_snapshot_hash: str

    @property
    def tuple(self) -> tuple[str, str, str, str, str]:
        return (
            self.asset_sha256,
            self.analyzer_name,
            self.analyzer_version,
            self.config_hash,
            self.parent_snapshot_hash,
        )

    @property
    def text(self) -> str:
        """Readable single-string form, used as the persisted unique column."""
        return "|".join(self.tuple)


def compute_config_hash(config: dict) -> str:
    """Hash analyzer configuration so changed settings produce a new job key."""
    return canonical_json_sha256(config)

