"""Template (rule-mode) audio observer: DSP facts only, labeled as template.

docs/08: "A CPU fixture/template mode must remain available. It is not
advertised as AI inference." This observer produces deterministic DSP
summaries and change candidates. It performs NO speech detection and NO
semantic sound labeling: those require ASR/CLAP and stay ineligible here.
"""
from __future__ import annotations

import math

from contracts.models import Confidence, Span

from ..media.derivatives import DerivativeError, decode_pcm
from ..media.probe import MediaInspector
from ..models.observations import (
    AcousticObservation,
    AudioObservationRequest,
    ObservationBatch,
)
from ..models.provenance import CapabilityFlags, ModelProvenance, Unavailable, config_hash
from . import dsp

ANALYZER_NAME = "perception.template_audio"
ANALYZER_VERSION = "0.1.0"


class TemplateAudioObserver:
    """Deterministic acoustic observer. Never routes to or from real inference.

    ``allow_real_media`` defaults to False: template mode is the fixture/CPU
    path, and real approved media must be enabled explicitly so template and
    real-inference modes are never silently mixed.
    """

    def __init__(
        self,
        inspector: MediaInspector | None = None,
        *,
        allow_real_media: bool = False,
        **dsp_kwargs,
    ):
        self._inspector = inspector or MediaInspector()
        self._allow_real_media = allow_real_media
        self._cfg = dsp.DspConfig(**dsp_kwargs) if dsp_kwargs else dsp.DspConfig()

    @property
    def provenance(self) -> ModelProvenance:
        return ModelProvenance(
            analyzer_name=ANALYZER_NAME,
            analyzer_version=ANALYZER_VERSION,
            mode="template",
            implementation="pure_python_dsp",
            config_hash=config_hash(self._cfg.model_dump()),
        )

    def observe(self, request: AudioObservationRequest) -> ObservationBatch:
        if request.audio_status != "present":
            return self._unavailable(
                request,
                reason="modality_missing",
                detail="No audio stream was ingested for this asset; acoustic claims are ineligible",
            )
        if request.origin == "approved_real" and not self._allow_real_media:
            return self._unavailable(
                request,
                reason="disabled_by_config",
                detail="Template observer refuses approved_real media unless explicitly enabled",
            )
        try:
            inspection = self._inspector.inspect(request.media_path)
        except Exception as exc:  # pragma: no cover - defensive, inspector is typed
            return self._unavailable(request, "media_error", f"Inspection error: {exc!r}")
        if inspection.status != "ok" or inspection.audio is None:
            failure = inspection.failure
            return self._unavailable(
                request,
                "media_error",
                f"Probe failed: {failure.code if failure else 'no audio stream'}",
            )
        try:
            mono = decode_pcm(
                request.media_path, inspection, rate=self._cfg.sample_rate, channels=1
            )
        except DerivativeError as exc:
            return self._unavailable(
                request, "media_error", f"PCM decode failed: {exc.failure.code}"
            )
        samples = dsp.pcm_s16le_to_float(mono.data)
        features = dsp.compute_features(samples, self._cfg)
        candidates, threshold = dsp.localize_changes(features, self._cfg)
        observations: list[AcousticObservation] = [self._summary(features, threshold)]
        for c in candidates:
            observations.append(
                AcousticObservation(
                    kind="dsp_change_candidate",
                    span=Span(start_ms=c.start_ms, end_ms=c.end_ms),
                    statement=(
                        "Acoustic change candidate: spectral flux "
                        f"{c.flux:.4f} exceeded the within-clip threshold {c.threshold:.4f}"
                    ),
                    feature_value=c.flux,
                    threshold=c.threshold,
                    confidence=Confidence(kind="uncalibrated_score", value=c.flux),
                )
            )
        observations.extend(self._reliability_notes(request, inspection))
        return ObservationBatch(
            asset_id=request.asset_id,
            modality="acoustic",
            status="ok",
            observations=observations,
            provenance=self.provenance,
            capabilities=CapabilityFlags(
                video_decoded=None,
                audio_present=True,
                sync_valid=None,
                transcript_available=None,
            ),
        )

    # -- internals ----------------------------------------------------------

    def _summary(
        self,
        features: list[dsp.WindowFeatures],
        threshold: float,
    ) -> AcousticObservation:
        if not features:
            return AcousticObservation(
                kind="dsp_summary",
                statement="Audio too short for any complete analysis window; no DSP features",
                confidence=Confidence(kind="not_applicable"),
            )
        rms = [f.rms for f in features]
        rms_median = dsp._median(rms)
        peak_rms = max(rms)
        return AcousticObservation(
            kind="dsp_summary",
            span=Span(start_ms=features[0].start_ms, end_ms=features[-1].end_ms),
            statement=(
                f"Template DSP over {len(features)} windows "
                f"({self._cfg.window_ms}ms window / {self._cfg.hop_ms}ms hop at "
                f"{self._cfg.sample_rate}Hz): median RMS {rms_median:.5f}, peak RMS "
                f"{peak_rms:.5f}; flux threshold (median+{self._cfg.flux_threshold_k:g}xMAD) "
                f"{threshold:.4f} saved; speech and semantic sound classes NOT assessed"
            ),
            feature_value=rms_median,
            threshold=threshold,
            confidence=Confidence(kind="not_applicable"),
        )

    def _reliability_notes(self, request, inspection) -> list[AcousticObservation]:
        notes: list[AcousticObservation] = [
            AcousticObservation(
                kind="reliability_note",
                statement=(
                    "Template mode performs no speech detection and no sound-class "
                    "scoring; speech-overlap reliability is not assessed here"
                ),
                confidence=Confidence(kind="not_applicable"),
            )
        ]
        channels = inspection.audio.channels if inspection.audio else 1
        if channels > 1:
            try:
                stereo = decode_pcm(
                    request.media_path, inspection, rate=self._cfg.sample_rate, channels=2
                )
            except DerivativeError:
                return notes
            # Interleaved s16 frames: L,R,L,R ... (docs/06: retain channel info).
            ls, rs = _split_stereo(stereo.data)
            lr, rr = _rms(ls), _rms(rs)
            if max(lr, rr) > 1e-4 and min(lr, rr) < 0.001 * max(lr, rr):
                notes.append(
                    AcousticObservation(
                        kind="reliability_note",
                        statement=(
                            "Abnormal per-channel energy loss detected "
                            f"(L RMS {lr:.6f} vs R RMS {rr:.6f}); stereo-to-mono "
                            "cancellation suspected; mono-derived features unreliable"
                        ),
                        confidence=Confidence(kind="not_applicable"),
                    )
                )
        return notes

    def _unavailable(self, request: AudioObservationRequest, reason, detail: str) -> ObservationBatch:
        return ObservationBatch(
            asset_id=request.asset_id,
            modality="acoustic",
            status="unavailable",
            unavailable=Unavailable(reason=reason, detail=detail),
            provenance=self.provenance,
            capabilities=CapabilityFlags(
                audio_present=False,
                transcript_available=False,
                sync_valid=False,
            ),
        )


def _split_stereo(data: bytes) -> tuple[list[float], list[float]]:
    n_frames = len(data) // 4
    left: list[float] = []
    right: list[float] = []
    for i in range(n_frames):
        l = int.from_bytes(data[4 * i:4 * i + 2], "little", signed=True) / 32768.0
        r = int.from_bytes(data[4 * i + 2:4 * i + 4], "little", signed=True) / 32768.0
        left.append(l)
        right.append(r)
    return left, right


def _rms(samples: list[float]) -> float:
    if not samples:
        return 0.0
    return math.sqrt(sum(x * x for x in samples) / len(samples))

files./app-root/packages/perception/media/prob:
"""Content-based media inspection via ffprobe and bounded decode verification.

docs/06: inspect actual content, not filename or browser MIME; reject
archives/executables, malformed containers, excessive decoded dimensions and
>60 fps input; distinguish missing audio from muted/silent audio (the latter
needs decoding, see ``perception.audio`` and ``derivatives.decode_pcm``).
"""
from __future__ import annotations

import subprocess
from pathlib import Path

from ..models.media import (
    AudioStreamInfo,
    MediaFailure,
    MediaInspection,
    VideoStreamInfo,
)
from .limits import MediaToolError, media_job_slot, run_tool, sanitize

#: Container formats we refuse outright (archives/executables/data).
_DENIED_FORMATS = {
    "zip", "gzip", "bzip2", "xz", "lzma", "7zip", "tar", "data", "pdf",
    "png_pipe", "bmp_pipe", "webp_pipe",
}
_MAGIC = (
    (b"PK\x03\x04", "zip_archive"),
    (b"\x1f\x8b", "gzip"),
    (b"7z\xbc\xaf\x27\x1c", "7zip"),
    (b"\xfd7zXZ", "xz"),
    (b"\x7fELF", "elf_executable"),
    (b"MZ", "pe_executable"),
    (b"BZh", "bzip2"),
    (b"%PDF", "pdf"),
)


class MediaInspector:
    def __init__(
        self,
        *,
        ffprobe: str = "ffprobe",
        ffmpeg: str = "ffmpeg",
        probe_timeout_s: float = 30.0,
        verify_timeout_s: float = 90.0,
        verify_max_seconds: float = 45.0,
        max_dimension: int = 3840,
        max_fps: float = 60.0,
    ):
        self._ffprobe = ffprobe
        self._ffmpeg = ffmpeg
        self._probe_timeout_s = probe_timeout_s
        self._verify_timeout_s = verify_timeout_s
        self._verify_max_seconds = verify_max_seconds
        self._max_dimension = max_dimension
        self._max_fps = max_fps

    # -- public API ---------------------------------------------------------

    def inspect(self, path: str | Path) -> MediaInspection:
        """Probe a file and return typed facts or a typed failure."""
        path = Path(path)
        if not path.is_file():
            return MediaInspection(
                status="failed",
                failure=MediaFailure(code="container_unreadable", detail="Media file not found"),
            )
        private = self._private_tokens(path)
        magic_failure = self._magic_check(path)
        if magic_failure is not None:
            return MediaInspection(status="failed", failure=magic_failure)
        try:
            with media_job_slot():
                result = run_tool(
                    [
                        self._ffprobe, "-v", "error",
                        "-print_format", "json",
                        "-show_format", "-show_streams",
                        str(path),
                    ],
                    timeout_s=self._probe_timeout_s,
                )
        except MediaToolError as exc:
            code = "probe_timeout" if exc.code == "tool_timeout" else "container_unreadable"
            return MediaInspection(
                status="failed",
                failure=MediaFailure(code=code, detail=sanitize(exc.detail, private)),
            )
        if result.returncode != 0:
            return MediaInspection(
                status="failed",
                failure=MediaFailure(
                    code="container_unreadable",
                    detail="ffprobe rejected the container",
                    stderr_excerpt=sanitize(result.stderr.decode("utf-8", "replace"), private),
                ),
            )
        return self._parse_probe_json(result.stdout.decode("utf-8", "replace"), private)

    def verify_decode(self, path: str | Path) -> MediaFailure | None:
        """Bounded full decode; None means the media decodes cleanly.

        Truncated files surface as ``truncated_media``, other decode errors as
        ``decode_failed`` — never a silent partial success.
        """
        path = Path(path)
        private = self._private_tokens(path)
        try:
            with media_job_slot():
                result = run_tool(
                    [
                        self._ffmpeg, "-v", "error", "-nostdin",
                        "-t", f"{self._verify_max_seconds:.3f}",
                        "-i", str(path),
                        "-map", "0:a?",
                        "-map", "0:v:0?",
                        "-f", "null", "-",
                    ],
                    timeout_s=self._verify_timeout_s,
                    stdout=subprocess.DEVNULL,
                )
        except MediaToolError as exc:
            return MediaFailure(code="decode_failed", detail=sanitize(exc.detail, private))
        if result.returncode == 0:
            return None
        excerpt = sanitize(result.stderr.decode("utf-8", "replace"), private)
        if "moov atom not found" in excerpt or "truncated" in excerpt.lower():
            code = "truncated_media"
        else:
            code = "decode_failed"
        return MediaFailure(code=code, detail="Decode verification failed", stderr_excerpt=excerpt)

    # -- internals ----------------------------------------------------------

    def _private_tokens(self, path: Path) -> list[str]:
        return [str(path), path.name, str(path.parent)]

    def _magic_check(self, path: Path) -> MediaFailure | None:
        with open(path, "rb") as fh:
            head = fh.read(8)
        for magic, label in _MAGIC:
            if head.startswith(magic):
                return MediaFailure(
                    code="rejected_container_type",
                    detail=f"Refused non-media container: {label}",
                )
        return None

    def _parse_probe_json(self, text: str, private: list[str]) -> MediaInspection:
        import json

        try:
            data = json.loads(text)
        except ValueError:
            return MediaInspection(
                status="failed",
                failure=MediaFailure(code="container_unreadable", detail="ffprobe output was not JSON"),
            )
        fmt = data.get("format") or {}
        streams = data.get("streams") or []
        video = next((s for s in streams if s.get("codec_type") == "video"), None)
        audio = next((s for s in streams if s.get("codec_type") == "audio"), None)
        if video is None and audio is None:
            return MediaInspection(
                status="failed",
                failure=MediaFailure(code="no_streams", detail="No audio or video stream present"),
            )
        format_name = str(fmt.get("format_name", ""))
        if format_name.split(",")[0] in _DENIED_FORMATS:
            return MediaInspection(
                status="failed",
                failure=MediaFailure(
                    code="rejected_container_type",
                    detail=f"Refused container format '{format_name.split(',')[0]}'",
                ),
            )
        video_info = self._video_info(video, private) if video else None
        if isinstance(video_info, MediaFailure):
            return MediaInspection(status="failed", failure=video_info)
        return MediaInspection(
            status="ok",
            format_name=format_name or None,
            size_bytes=_int_or_none(fmt.get("size")),
            duration_ms=_seconds_to_ms(fmt.get("duration")),
            bitrate=_int_or_none(fmt.get("bit_rate")),
            video=video_info,
            audio=self._audio_info(audio) if audio else None,
        )

    def _video_info(self, s: dict, private: list[str]) -> VideoStreamInfo | MediaFailure:
        width, height = int(s.get("width", 0)), int(s.get("height", 0))
        if width <= 0 or height <= 0:
            return MediaFailure(code="container_unreadable", detail="Video stream has no dimensions")
        if max(width, height) > self._max_dimension:
            return MediaFailure(
                code="excessive_dimensions",
                detail=f"Decoded dimensions {width}x{height} exceed the {self._max_dimension}px guard",
            )
        fps = _parse_fps(s)
        if fps is None or fps <= 0:
            return MediaFailure(code="container_unreadable", detail="Video stream has no usable frame rate")
        if fps > self._max_fps + 0.5:
            return MediaFailure(
                code="fps_unsupported",
                detail=f"Frame rate {fps:.3f} fps exceeds the {self._max_fps:g} fps limit",
            )
        return VideoStreamInfo(
            codec=str(s.get("codec_name", "unknown")),
            pix_fmt=s.get("pix_fmt"),
            width=width,
            height=height,
            fps=fps,
            nb_frames=_int_or_none(s.get("nb_frames")),
            time_base=s.get("time_base"),
            start_time_ms=_seconds_to_ms(s.get("start_time"), default=0),
            duration_ms=_seconds_to_ms(s.get("duration")),
            rotation_deg=_rotation_deg(s),
            color_space=s.get("color_space"),
            color_transfer=s.get("color_transfer"),
        )

    def _audio_info(self, s: dict) -> AudioStreamInfo:
        rate = int(s.get("sample_rate", 0))
        return AudioStreamInfo(
            codec=str(s.get("codec_name", "unknown")),
            sample_rate=rate if rate > 0 else 48000,
            channels=int(s.get("channels", 1)) or 1,
            time_base=s.get("time_base"),
            start_time_ms=_seconds_to_ms(s.get("start_time"), default=0),
            duration_ms=_seconds_to_ms(s.get("duration")),
        )


def _rotation_deg(s: dict) -> float:
    for side in s.get("side_data_list") or []:
        if "rotation" in side:
            try:
                return float(side["rotation"])
            except (TypeError, ValueError):
                pass
    tag = (s.get("tags") or {}).get("rotate")
    if tag:
        try:
            return float(tag)
        except ValueError:
            pass
    return 0.0


def _parse_fps(s: dict) -> float | None:
    for key in ("avg_frame_rate", "r_frame_rate"):
        raw = s.get(key)
        if not raw or raw in ("0/0", "N/A"):
            continue
        num, _, den = raw.partition("/")
        try:
            n, d = float(num), float(den or 1)
        except ValueError:
            continue
        if d and n > 0:
            return n / d
    return None


def _seconds_to_ms(raw: object, default: int | None = None) -> int | None:
    try:
        return round(float(raw) * 1000)  # type: ignore[arg-type]
    except (TypeError, ValueError):
        return default


def _int_or_none(raw: object) -> int | None:
    try:
        return int(raw)  # type: ignore[arg-type]
    except (TypeError, ValueError):
        return None

