"""Offline model provisioning preflight; never imports or loads a model.

Readiness establishes a usable approved payload and known runtime prerequisites,
not execution success or model quality. Call receipts remain the evidence for
execution. Paths and the revision marker's unverified license label are kept
out of the public capability response.
"""
from __future__ import annotations

import json
import os
import platform
from dataclasses import asdict, dataclass
from importlib import metadata, util
from pathlib import Path
from typing import Mapping

_MODELS = {
    "qwen": ("qwen2.5-vl-7b-instruct", "536a35794df8831aa814970ee8f89eff577e7718",
             ("torch", "torchvision", "transformers", "accelerate", "PIL")),
    "clap": ("clap-htsat-unfused", "8fa0f1c6d0433df6e97c127f64b2a1d6c0dcda8a",
             ("torch", "transformers", "numpy")),
    "whisper": ("faster-whisper-small", "536b0662742c02347bc0e980a01041f333bce120",
                ("faster_whisper", "ctranslate2")),
}


@dataclass(frozen=True)
class ModelReadiness:
    model: str
    available: bool
    weights_present: bool
    weights_payload_present: bool
    revision: str | None
    approved_revision: str
    reason: str | None
    detail: str
    missing_dependencies: tuple[str, ...] = ()
    quantization: str | None = None
    availability_basis: str = "preflight_only_not_execution_or_quality"

    def as_dict(self) -> dict:
        value = asdict(self)
        value["missing_dependencies"] = list(self.missing_dependencies)
        return value


def weights_directory(model: str, *, env: Mapping[str, str] | None = None) -> Path:
    """Same root precedence and directory labels as the approved adapters."""
    label = _MODELS[model][0]
    environ = os.environ if env is None else env
    root = (environ.get("MV_MODEL_WEIGHTS_DIR") or environ.get("MV_MODEL_CACHE")
            or str(Path.home() / ".local/share/making-visible/model_cache"))
    return Path(root) / label


def _json_file(path: Path) -> dict:
    try:
        # Model configuration and revision records are small, not weights.
        if path.stat().st_size > 1_048_576:
            return {}
        value = json.loads(path.read_text())
        return value if isinstance(value, dict) else {}
    except (OSError, UnicodeError, ValueError):
        return {}


def _nonempty(path: Path) -> bool:
    try:
        return path.is_file() and path.stat().st_size > 0
    except OSError:
        return False


def _weight_payload(model: str, directory: Path) -> bool:
    if model == "whisper":
        return _nonempty(directory / "model.bin")
    index = directory / "model.safetensors.index.json"
    if index.is_file():
        mapping = _json_file(index).get("weight_map")
        if not isinstance(mapping, dict) or not mapping:
            return False
        if not all(isinstance(name, str) for name in mapping.values()):
            return False
        names = set(mapping.values())
        return all(Path(name).name == name
                   and name.endswith(".safetensors") and _nonempty(directory / name)
                   for name in names)
    return any(_nonempty(directory / name)
               for name in ("model.safetensors", "pytorch_model.bin"))


def _dependency_present(name: str) -> bool:
    try:
        return util.find_spec(name) is not None
    except (ImportError, ModuleNotFoundError, ValueError):
        return False


def _version(name: str) -> str | None:
    try:
        return metadata.version(name)
    except metadata.PackageNotFoundError:
        return None


def _awq_mps_verification_error(config: dict, quantization: dict) -> str | None:
    """The owned decoder admits only the measured precision/layout/runtime."""
    if (config.get("torch_dtype") != "bfloat16" or quantization.get("bits") != 4
            or quantization.get("group_size") != 128
            or quantization.get("version") != "gemm"
            or quantization.get("zero_point") is not True):
        return "AWQ/MPS checkpoint configuration differs from the measured BF16 GEMM condition."
    from .visual.awq_mps import runtime_verification_error
    return runtime_verification_error()


def model_readiness(model: str, *, env: Mapping[str, str] | None = None,
                    weights_dir: Path | None = None) -> ModelReadiness:
    """Return the conservative, no-load status of one approved checkpoint.

    An existing directory or a marker alone is not installed weights. Exact
    pins, all indexed shards and configuration are required. The owned Apple
    AWQ decoder additionally verifies measured runtime/source fingerprints.
    Its production standard-resolution synthetic observation completed;
    that execution receipt does not establish semantic reliability. Other
    platforms retain prerequisite-only discovery and their own execution checks.
    """
    if model not in _MODELS:
        raise ValueError("Unknown approved local model")
    _label, approved_revision, dependencies = _MODELS[model]
    directory = Path(weights_dir) if weights_dir is not None else weights_directory(model, env=env)
    marker = _json_file(directory / "revision.json")
    revision = marker.get("revision")
    revision = revision if isinstance(revision, str) else None
    config = _json_file(directory / "config.json")
    payload = _weight_payload(model, directory)
    quant = config.get("quantization_config") or {}
    quantization = quant.get("quant_method") if isinstance(quant, dict) else None
    quantization = quantization if isinstance(quantization, str) else None
    required = list(dependencies)
    unsupported_quantization = False
    if model == "qwen" and quantization:
        if quantization == "awq":
            try:
                major = int((_version("transformers") or "5").split(".")[0])
            except ValueError:
                major = 5
            required.append("gptqmodel" if major >= 5 else "awq")
        else:
            unsupported_quantization = True
    missing = tuple(name for name in required if not _dependency_present(name))
    reason = None
    if not directory.is_dir():
        reason, detail = "weights_absent", "Approved local checkpoint is not provisioned."
    elif not payload or not config:
        reason, detail = "weights_payload_incomplete", "Approved model configuration or weight payload is incomplete."
    elif revision != approved_revision:
        reason, detail = "revision_not_approved", "Checkpoint revision does not match the exact approved pin."
    elif missing:
        reason, detail = "dependency_absent", "Local runtime dependencies are missing: " + ", ".join(missing) + "."
    elif unsupported_quantization:
        reason, detail = "quantization_unsupported", "Checkpoint quantization is unsupported by this adapter."
    elif (model == "qwen" and quantization == "awq"
          and platform.system() == "Darwin" and platform.machine() == "arm64"):
        error = _awq_mps_verification_error(config, quant)
        if error:
            reason, detail = "quantized_runtime_unverified", error
        else:
            detail = "Approved AWQ/MPS payload and measured owned decoder fingerprints pass preflight. Execution is recorded per call; visual reliability and local-guidance quality are not established by this check."
    else:
        detail = "Approved payload and dependencies pass preflight; execution and quality remain unverified by this check."
    return ModelReadiness(
        model=model, available=reason is None, weights_present=payload,
        weights_payload_present=payload, revision=revision, approved_revision=approved_revision,
        reason=reason, detail=detail, missing_dependencies=missing, quantization=quantization,
    )

"""Provider interfaces (docs/03_ARCHITECTURE.md).

"Provider interfaces: VisualObserver.observe(bundle)->ObservationBatch;
