frames)->TrackSet; ... Every provider returns model/config provenance and
capabilities. An unavailable model returns a typed unavailable result, not a
fake success."

Structural typing only: adapters implement these signatures without inheriting
anything, so heavy optional dependencies stay lazy.
"""
from __future__ import annotations

from typing import Protocol, runtime_checkable

from .models.observations import AudioObservationRequest, ObservationBatch, VisualObservationRequest
from .models.tracking import Anchor, GrayscaleFrame, TrackSet


@runtime_checkable
