files./app-root/packages/perception/tracking/c:
"""Optional CoTracker3 comparison tracker (D12) — typed-unavailable adapter.

configs/models.json: tracker_comparison = "facebookresearch/co-tracker:CoTracker3".
The checkpoint install path is lead-owned and opt-in (D29); when the
dependency or the weights are absent this adapter returns a TYPED unavailable
TrackSet. It never fabricates trajectories and never falls back to LK:
substituting implementations silently would corrupt the D12 comparison.

The real inference block is deliberately minimal: the co-tracker pip surface
has changed across releases, so the exact predictor API is resolved and
recorded at approved-install time (Phase 0 rule: do not invent compatibility).
"""
from __future__ import annotations

import json
import os
from pathlib import Path

from ..models.provenance import CapabilityFlags, ModelProvenance, config_hash
from ..models.tracking import Anchor, GrayscaleFrame, TrackSet, TrackingFailure

ANALYZER_NAME = "perception.cotracker3"
ANALYZER_VERSION = "0.1.0"
MODEL_FAMILY = "facebookresearch/co-tracker:CoTracker3"
WEIGHTS_LABEL = "co-tracker CoTracker3 checkpoint"
DEPENDENCY_LABEL = "torch + co-tracker"


def default_weights_dir(env: dict | None = None) -> Path:
    env = env if env is not None else os.environ
    root = env.get("MV_MODEL_CACHE") or os.path.join(
        os.path.expanduser("~"), ".local", "share", "making-visible", "model_cache"
    )
    return Path(root) / "cotracker3"


class CoTrackerTracker:
    """Same anchors + frame budget interface as LkTracker (docs/08 item 5)."""

    def __init__(self, weights_dir: Path | None = None):
        self._weights_dir = weights_dir

    def provenance(self, weights_present: bool, revision: str | None, license_name: str | None) -> ModelProvenance:
        return ModelProvenance(
            analyzer_name=ANALYZER_NAME,
            analyzer_version=ANALYZER_VERSION,
            mode="local_model",
            implementation="cotracker3_online_offline_unresolved",
            model_family=MODEL_FAMILY,
            model_revision=revision,
            revision_status="resolved" if revision else "not_resolved",
            license=license_name,
            weights_present=weights_present,
            config_hash=config_hash({"family": MODEL_FAMILY, "weights_label": WEIGHTS_LABEL}),
        )

    def track(
        self, anchors: list[Anchor], frames: list[GrayscaleFrame], *, asset_id: str = "unknown"
    ) -> TrackSet:
        weights = _resolve_weights(self._weights_dir or default_weights_dir())
        if not weights["present"]:
            return self._unavailable(
                asset_id, "weights_absent",
                f"{WEIGHTS_LABEL} not installed; run the approved install path first",
            )
        try:
            import torch  # noqa: F401  (lazy; typed unavailable when absent)
            import cotracker  # type: ignore[import-not-found]  # noqa: F401
        except ImportError:
            return self._unavailable(
                asset_id, "dependency_absent",
                f"Python dependencies missing: {DEPENDENCY_LABEL}",
            )
        # Reachable only after lead-approved install; the exact predictor call
        # (video tensor layout, grid size, backward=False) is resolved and
        # replayed against the fixed regression scenarios at that time.
        raise NotImplementedError(
            "CoTracker3 inference is not wired until the approved weights install "
            "resolves the predictor API and license record"
        )

    def _unavailable(self, asset_id: str, reason: str, detail: str) -> TrackSet:
        return TrackSet(
            asset_id=asset_id,
            status="unavailable",
            tracks=[],
            failure=TrackingFailure(code=reason, detail=detail),  # type: ignore[arg-type]
            provenance=self.provenance(False, None, None),
            capabilities=CapabilityFlags(tracks_valid=False),
        )


def _resolve_weights(directory: Path) -> dict:
    """Check for an installed checkpoint and its revision record. No network."""
    marker = directory / "revision.json"
    if directory.is_dir() and any(directory.iterdir()):
        revision = license_name = None
        if marker.is_file():
            try:
                data = json.loads(marker.read_text())
                revision = data.get("revision")
                license_name = data.get("license")
            except ValueError:
                pass
        return {"present": True, "revision": revision, "license": license_name}
    return {"present": False, "revision": None, "license": None}

