"""Template (rule-mode) visual observer for the CPU vertical slice.

Deterministic, offline, no weights, labeled mode=template. It restricts
itself to rule-derivable facts about the supplied frames (decoding coverage,
uniform/blank frames, inter-frame change magnitude). It never emits
``component_state`` or ``possible_projected_contact`` observations — those are
neural-only kinds and the ObservationBatch validator rejects them in
template-mode provenance (docs/08: rule-mode output is not labeled as neural).
"""
from __future__ import annotations

from contracts.models import Confidence

from ..models.observations import (
    ObservationBatch,
    VisualObservation,
    VisualObservationRequest,
)
from ..models.provenance import CapabilityFlags, ModelProvenance, Unavailable, config_hash

ANALYZER_NAME = "perception.template_visual"
ANALYZER_VERSION = "0.1.0"


class TemplateVisualObserver:
    """Offline deterministic visual observations from grayscale planes."""

    def __init__(self, *, allow_real_media: bool = False):
        self._allow_real_media = allow_real_media

    @property
    def provenance(self) -> ModelProvenance:
        return ModelProvenance(
            analyzer_name=ANALYZER_NAME,
            analyzer_version=ANALYZER_VERSION,
            mode="template",
            implementation="pure_python_frame_rules",
            config_hash=config_hash({"uniformity_tolerance": 0, "version": ANALYZER_VERSION}),
        )

    def observe(self, request: VisualObservationRequest) -> ObservationBatch:
        if not request.frames and not request.images:
            return self._unavailable(request, "empty_input", "Visual request carried no frames or images")
        if request.origin == "approved_real" and not self._allow_real_media:
            return self._unavailable(
                request,
                "disabled_by_config",
                "Template observer refuses approved_real media unless explicitly enabled",
            )
        observations: list[VisualObservation] = []
        prev_mean: float | None = None
        for frame in request.frames:
            n = len(frame.data)
            mean = sum(frame.data) / n
            lo, hi = min(frame.data), max(frame.data)
            frame_id = frame.frame_id
            if lo == hi:
                observations.append(
                    VisualObservation(
                        kind="missing_view",
                        frame_id=frame_id,
                        statement=(
                            f"Frame {frame_id} decodes but is uniform (constant value {lo}); "
                            "the view may be missing or blocked"
                        ),
                        confidence=Confidence(kind="not_applicable"),
                    )
                )
            else:
                statement = (
                    f"Frame {frame_id} decoded ({frame.width}x{frame.height} at t={frame.t_ms}ms); "
                    f"mean brightness {mean:.1f}/255, pixel range [{lo}, {hi}]"
                )
                if prev_mean is not None:
                    statement += f"; mean change vs previous frame {abs(mean - prev_mean):.2f}"
                observations.append(
                    VisualObservation(
                        kind="frame_note",
                        frame_id=frame_id,
                        statement=statement,
                        confidence=Confidence(kind="not_applicable"),
                    )
                )
            prev_mean = mean
        return ObservationBatch(
            asset_id=request.asset_id,
            modality="visual",
            status="ok",
            observations=observations,
            provenance=self.provenance,
            capabilities=CapabilityFlags(video_decoded=True),
        )

    def _unavailable(self, request: VisualObservationRequest, reason: str, detail: str) -> ObservationBatch:
        return ObservationBatch(
            asset_id=request.asset_id,
            modality="visual",
            status="unavailable",
            unavailable=Unavailable(reason=reason, detail=detail),  # type: ignore[arg-type]
            provenance=self.provenance,
            capabilities=CapabilityFlags(video_decoded=False),
        )

files./app-root/packages/reasoning/graph/nodes:
"""Typed immutable graph records and append-only graph operations (docs/09).

Node payloads are the contract types (or opaque ID references for app-level
entities); this module adds graph identity, edge typing, and supersession
semantics. There is no generic `causes` edge: a verified intervention is an
`inspection` evidence item carrying Verification provenance (contracts), and
`tests` edges connect a hypothesis to such a record.
"""
from __future__ import annotations

from typing import Literal

from pydantic import BaseModel, ConfigDict, Field

from contracts.models import EvidenceItem, StrictModel

NodeType = Literal[
    "design_version",
    "component_version",
    "checkpoint",
    "asset",
    "observation",
    "reported_explanation",
    "hypothesis",
    "capture_request",
    "teacher_decision",
]

EdgeType = Literal[
    "revises",
    "belongs_to",
    "recorded_at",
    "depicts",
    "associated_with",
    "supports",
    "contradicts",
    "compared_with",
    "supersedes",
    "tests",
]


class GraphNode(StrictModel):
    """A graph node wraps either an EvidenceItem payload or an entity reference.

    `record_kind`/`status` for evidence-carrying nodes stay authoritative in the
    EvidenceItem; entity nodes (design_version, checkpoint, ...) carry only IDs
    plus their own project scope, because their full records live in the API.
    """

    id: str = Field(min_length=1)
    project_id: str = Field(min_length=1)
    type: NodeType
    evidence: EvidenceItem | None = None
    ref_id: str | None = None

    def active(self) -> bool:
        if self.evidence is not None:
            return self.evidence.status == "active"
        return True


class GraphEdge(StrictModel):
    id: str = Field(min_length=1)
    project_id: str = Field(min_length=1)
    type: EdgeType
    src: str
    dst: str

    def validates(self, nodes: dict[str, GraphNode]) -> str | None:
        """Return a rejection reason, or None when the edge is well-formed.

        Enforces the docs/09 attribution boundaries at the edge level:
        observations and reported explanations stay distinct; a reported
        explanation can support a hypothesis only with reported framing.
        """
        a, b = nodes.get(self.src), nodes.get(self.dst)
        if a is None or b is None:
            return "edge endpoint missing"
        if self.type in ("supports", "contradicts"):
            src_e, dst_e = a.evidence, b.evidence
            if src_e is None or dst_e is None:
                return f"{self.type} edge must join two evidence nodes"
            if src_e.record_kind == "reported_explanation" and dst_e.record_kind != "hypothesis":
                return "a reported explanation supports only hypotheses (reported framing)"
            if src_e.record_kind == "observation" and dst_e.record_kind == "observation":
                return "observations do not support or contradict observations"
        if self.type == "supersedes" and (a.evidence is None or b.evidence is None):
            return "supersedes must join two evidence nodes"
        if self.type == "tests":
            if a.evidence is None or a.evidence.record_kind != "hypothesis":
                return "tests must originate at a hypothesis"
            if b.evidence is None or b.evidence.record_kind != "inspection":
                return "tests must point at an inspection record"
        return None


class SupersessionError(ValueError):
    """Raised when a supersession would violate immutability rules."""


class EvidenceGraph:
    """Append-only in-memory graph for one project scope.

    The API persists nodes/edges in PostgreSQL; this class is the deterministic
    core used by retrieval and by integration tests. Supersession marks the old
    node inactive by creating a NEW evidence item with status `superseded` —
    original records are never rewritten (docs/04 eligibility rule 5).
    """

    def __init__(self, project_id: str) -> None:
        if not project_id:
            raise ValueError("project scope is required")
        self.project_id = project_id
        self._nodes: dict[str, GraphNode] = {}
        self._edges: dict[str, GraphEdge] = {}

    def add_node(self, node: GraphNode) -> GraphNode:
        if node.project_id != self.project_id:
            raise SupersessionError(f"cross-project node {node.id!r} rejected")
        if node.id in self._nodes:
            raise SupersessionError(f"node {node.id!r} already exists (append-only)")
        if node.evidence is not None and node.evidence.project_id != self.project_id:
            raise SupersessionError(f"evidence {node.id!r} is out of project scope")
        self._nodes[node.id] = node
        return node

    def add_edge(self, edge: GraphEdge) -> GraphEdge:
        if edge.project_id != self.project_id:
            raise SupersessionError(f"cross-project edge {edge.id!r} rejected")
        if edge.id in self._edges:
            raise SupersessionError(f"edge {edge.id!r} already exists (append-only)")
        if (reason := edge.validates(self._nodes)) is not None:
            raise SupersessionError(f"edge {edge.id!r} rejected: {reason}")
        self._edges[edge.id] = edge
        return edge

    def node(self, node_id: str) -> GraphNode | None:
        return self._nodes.get(node_id)

    def edge(self, edge_id: str) -> GraphEdge | None:
        return self._edges.get(edge_id)

    def nodes(self, *, active_only: bool = False) -> list[GraphNode]:
        out = list(self._nodes.values())
        return [n for n in out if n.active()] if active_only else out

    def edges(self) -> list[GraphEdge]:
        return list(self._edges.values())

    def supersede(
        self,
        old_id: str,
        replacement: EvidenceItem,
        *,
        replacement_node_id: str,
        edge_id: str,
    ) -> tuple[GraphNode, GraphEdge]:
        """Create a replacement evidence node and a supersedes edge.

        The OLD node keeps its original payload and remains in the audit trail;
        the `supersedes` edge plus the replacement's own `superseded`-chain is
        what marks it inactive for retrieval (the old evidence status is flipped
        to `superseded` here as an immutable copy; active() reads that status).
        """
        old = self._nodes.get(old_id)
        if old is None:
            raise SupersessionError(f"cannot supersede unknown node {old_id!r}")
        if old.evidence is None:
            raise SupersessionError("only evidence nodes can be superseded")
        if old.evidence.status != "active":
            raise SupersessionError(f"node {old_id!r} is not active")
        if replacement.status != "active":
            raise SupersessionError("a replacement record must itself start active")
        if replacement.project_id != self.project_id:
            raise SupersessionError("replacement is out of project scope")
        new_node = self.add_node(GraphNode(id=replacement_node_id, project_id=self.project_id,
                                           type=old.type, evidence=replacement))
        edge = self.add_edge(GraphEdge(id=edge_id, project_id=self.project_id,
                                       type="supersedes", src=replacement_node_id, dst=old_id))
        # Mark the old record superseded via a new immutable instance: payload
        # and ID are untouched (audit trail), only the status flag advances.
        assert old.evidence is not None
        superseded = old.evidence.model_copy(update={"status": "superseded"})
        self._nodes[old_id] = old.model_copy(update={"evidence": superseded})
        return new_node, edge

    def retract(self, node_id: str) -> GraphNode:
        """Mark an active evidence node retracted (audit trail kept; payload
        and ID untouched). Deletion semantics for staleness: any dependent
        answer's snapshot hash changes (docs/05 correction/deletion)."""
        old = self._nodes.get(node_id)
        if old is None:
            raise SupersessionError(f"cannot retract unknown node {node_id!r}")
        if old.evidence is None:
            raise SupersessionError("only evidence nodes can be retracted")
        if old.evidence.status != "active":
            raise SupersessionError(f"node {node_id!r} is not active")
        retracted = old.evidence.model_copy(update={"status": "retracted"})
        updated = old.model_copy(update={"evidence": retracted})
        self._nodes[node_id] = updated
        return updated

    def superseded_chain(self, node_id: str) -> list[str]:
        """IDs of nodes superseded (directly or transitively) by `node_id`."""
        seen: list[str] = []
        frontier = [node_id]
        while frontier:
            current = frontier.pop()
            for e in self._edges.values():
                if e.type == "supersedes" and e.src == current and e.dst not in seen:
                    seen.append(e.dst)
                    frontier.append(e.dst)
        return seen

    def hypotheses_of(self, node_id: str) -> dict[str, list[str]]:
        """Supporting and contradicting hypothesis IDs for an evidence node."""
        supports: list[str] = []
        contradicts: list[str] = []
        for e in self._edges.values():
            if e.dst != node_id:
                continue
            target = self._nodes.get(e.src)
            if target is None or target.evidence is None or target.evidence.record_kind != "hypothesis":
                continue
            if e.type == "supports":
                supports.append(e.src)
            elif e.type == "contradicts":
                contradicts.append(e.src)
        return {"supports": supports, "contradicts": contradicts}

files./app-root/packages/reasoning/guidance/va:
"""Guidance validation: schema → scope → citations → wording → policy (docs/11).

Validation runs BEFORE rendering reaches the workbench. On failure the caller
repairs once (constrained) and falls back to deterministic templates on a
second failure. Structural validity is necessary, not sufficient, for
semantic support — that stays an evaluated metric.
"""
from __future__ import annotations

from dataclasses import dataclass

from contracts.models import Asset, GuidanceAnswer

_CAUSAL_MARKERS = (
    "caused by",
    "because the",
    "the cause is",
    "which is why",
    "so the mechanism broke",
)
_CONTACT_MARKERS = ("is touching", "physically contacts", "in contact with", "rubbing against")


@dataclass(frozen=True)
class ValidationFailure:
    code: str
    detail: str


def validate_answer(
    answer: GuidanceAnswer,
    *,
    assets: dict[str, Asset],
    evidence_by_id: dict,
    selected_version_id: str,
    project_id: str,
    snapshot_id: str,
    side_view_available: bool,
    ancestry: tuple[str, ...] = (),
) -> ValidationFailure | None:
    """Deterministic post-generation checks; None means the answer may render."""
    if answer.project_id != project_id or answer.snapshot_id != snapshot_id:
        return ValidationFailure("scope", "answer scope or snapshot mismatch")
    if answer.selected_version_id != selected_version_id:
        return ValidationFailure("scope", "selected version mismatch")

    from packages.reasoning.retrieval.eligibility import citation_eligible

    for claim in answer.claims:
        if not claim.citations:
            return ValidationFailure("uncited_claim", f"claim {claim.id} has no citations")
        for c in claim.citations:
            ev = evidence_by_id.get(c.evidence_id)
            if ev is None:
                return ValidationFailure("unresolvable_citation", f"claim {claim.id} cites unknown {c.evidence_id}")
            asset = assets.get(ev.asset_id)
            if asset is None:
                return ValidationFailure("unresolvable_source", f"evidence {ev.id} has no resolvable asset")
            reject = citation_eligible(
                c, ev, asset,
                project_id=project_id,
                selected_version_id=selected_version_id,
                claim_kind=claim.kind,
                ancestry=ancestry,
            )
            if reject is not None:
                return ValidationFailure(reject.code, f"claim {claim.id}: {reject.reason}")

        text = claim.text.lower()
        if claim.kind != "verified_cause" and any(m in text for m in _CAUSAL_MARKERS):
            return ValidationFailure("causal_wording", f"claim {claim.id} asserts cause without verification")
        if claim.kind == "observation" and any(m in text for m in _CONTACT_MARKERS):
            return ValidationFailure("invisible_contact", f"claim {claim.id} asserts physical contact from observation")

    for step in answer.next_steps:
        if "side view" in step.text.lower() and side_view_available:
            return ValidationFailure("duplicate_request", "side view already available in this snapshot")
        if step.teacher_approval_required is not True:  # contract literal, explicit here
            return ValidationFailure("approval", "a next step lacked unconditional teacher approval")

    levels = {"question": 0, "hint": 1, "explanation": 2}
    ceiling = levels[answer.context.disclosure_ceiling]
    if any(levels[s.disclosure] > ceiling for s in answer.next_steps):
        return ValidationFailure("disclosure", "disclosure ceiling exceeded")
    return None

files./app-root/packages/reasoning/retrieval/e:
"""Citation and evidence eligibility (docs/04 rules 1-6, docs/09).

Every rejection is typed and returned before any generation step. Structural
eligibility is necessary but not sufficient for semantic support — that is a
separate evaluated metric, never assumed here.
"""
from __future__ import annotations

from dataclasses import dataclass

from contracts.models import Asset, Citation, EvidenceItem


@dataclass(frozen=True)
class EligibilityReject:
    code: str
    reason: str


def citation_eligible(
    citation: Citation,
    evidence: EvidenceItem,
    asset: Asset,
    *,
    project_id: str,
    selected_version_id: str,
    claim_kind: str,
    ancestry: tuple[str, ...] = (),
) -> EligibilityReject | None:
    """Return a typed reject reason, or None when the citation may stand.

    Checks: scope, active status, temporal role vs version lineage, source
    modality, record-kind attribution, and acoustic availability.
    """
    if evidence.project_id != project_id or asset.project_id != project_id:
        return EligibilityReject("cross_project", "citation crosses the project boundary")
    if evidence.id != citation.evidence_id:
        return EligibilityReject("id_mismatch", "citation does not match the evidence record")
    if evidence.status != "active" or asset.status != "active":
        return EligibilityReject("inactive_source", "superseded/retracted evidence or deleted media cannot support a new answer")
    if evidence.design_version_id != asset.design_version_id:
        return EligibilityReject("version_mismatch", "evidence version differs from its source asset")

    if citation.temporal_role == "current":
        if evidence.design_version_id != selected_version_id:
            return EligibilityReject("stale_as_current", "prior-version evidence passed as current")
    else:  # historical
        if evidence.design_version_id == selected_version_id:
            return EligibilityReject("current_as_historical", "current evidence mislabeled as historical")
        if evidence.design_version_id not in ancestry:
            return EligibilityReject("unrelated_branch", "historical citation is not on the selected version's lineage")

    if evidence.asset_id and evidence.span is not None and asset.duration_ms is not None:
        if evidence.span.end_ms > asset.duration_ms:
            return EligibilityReject("out_of_bounds", "interval outside the source asset")

    if evidence.modality == "acoustic" and asset.audio_status != "present":
        return EligibilityReject("missing_audio", "acoustic claim without present audio")

    if claim_kind == "observation" and evidence.record_kind in ("hypothesis", "reported_explanation"):
        return EligibilityReject("attribution", "a hypothesis/report cannot ground an observation claim")
    if claim_kind == "reported_explanation" and evidence.record_kind != "reported_explanation":
        return EligibilityReject("attribution", "reported-explanation claim needs an attributed report")
    if claim_kind == "verified_cause" and not (
        evidence.record_kind == "inspection" and evidence.verification is not None
    ):
        return EligibilityReject("unverified_cause", "verified cause needs inspection provenance")
    return None

files./app-root/security/privacy_scan.py:
"""Forbidden inference-field scan over contracts and schemas.

Never infer grades, ability, emotion, disability, motivation, or identity from
faces, voices, or missing uploads (repository contract; docs/15). This scanner
enforces the negative space at the data-contract level: no field name in the
generated JSON Schemas or the interchange models may carry student inference
or special-category data.

The allowlist is anchored to reality: every allowlisted name must actually
exist in the current contracts, and each carries its written justification.
Unknown fields fail closed elsewhere, so a new sensitive field cannot enter
without either a denial here or an explicit, reviewed allowlist entry.
"""
from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path
from typing import Iterable

__all__ = ["ALLOWED_FIELDS", "PrivacyFinding", "collect_contract_fields", "scan_fields"]

# Substring tokens that mark student inference or special-category data.
# Matching is on normalized field names; exact allowlist entries win.
FORBIDDEN_TOKENS: tuple[str, ...] = (
    # emotion / affect inference
    "emotion", "sentiment", "mood", "affect_score", "stress", "anxiety", "frustration",
    # identity and special-category data
    "face", "voiceprint", "voice_id", "voice_embedding", "speaker", "biometric",
    "fingerprint", "retina", "gender", "race", "ethnic", "religion", "nationality",
    "first_name", "last_name", "student_name", "birthdate", "date_of_birth",
    # ability / grade inference
    "predicted_grade", "grade_prediction", "ability", "aptitude", "iq_score",
    "skill_level", "achievement_score", "disability", "special_needs", "adhd",
    "autism", "dyslexia", "iep_goal", "motivation", "engagement_score",
    "attention_score", "surveillance",
)

# Exact contract field names that are allowed despite superficial token overlap,
# each with the reason it is not a student-inference field.
ALLOWED_FIELDS: dict[str, str] = {
    # Teacher-supplied pedagogical context (docs/04; D22). Teacher-declared, never
    # inferred from media, and kept separate from diagnosis inputs by contract tests.
    "grade_band": "teacher-declared context field, never inferred; D22 separation tests",
    # A NextStep suggestion the teacher may ask; contains no student data.
    "student_question": "teacher-facing suggested question text, not student data",
}


@dataclass(frozen=True)
class PrivacyFinding:
    field: str
    sources: tuple[str, ...]
    matched_token: str


def collect_schema_fields(schemas_dir: Path) -> dict[str, set[str]]:
    """Collect ``properties`` key names per schema file (generated artifacts)."""
    fields: dict[str, set[str]] = {}
    for path in sorted(schemas_dir.glob("*.json")):
        data = json.loads(path.read_text(encoding="utf-8"))
        found: set[str] = set()

        def walk(node: object) -> None:
            if isinstance(node, dict):
                props = node.get("properties")
                if isinstance(props, dict):
                    found.update(props)
                for value in node.values():
                    walk(value)
            elif isinstance(node, list):
                for item in node:
                    walk(item)

        walk(data)
        fields[path.name] = found
    return fields


def collect_model_fields(module: object) -> dict[str, set[str]]:
    """Collect pydantic model field names from the interchange module."""
    from pydantic import BaseModel  # local import keeps this module import-light

    fields: dict[str, set[str]] = {}
    for name in dir(module):
        obj = getattr(module, name)
        if isinstance(obj, type) and issubclass(obj, BaseModel) and obj is not BaseModel:
            fields[f"{module.__name__}.{name}"] = set(obj.model_fields)
    return fields


def collect_contract_fields(schemas_dir: Path, models_module: object) -> dict[str, set[str]]:
    fields = collect_schema_fields(schemas_dir)
    fields.update(collect_model_fields(models_module))
    return fields


def scan_fields(fields: Iterable[str]) -> list[PrivacyFinding]:
    """Flag any field name matching a forbidden token and not allowlisted."""
    findings: list[PrivacyFinding] = []
    for raw in sorted(set(fields)):
        name = raw.strip().lower()
        if name in ALLOWED_FIELDS:
            continue
        for token in FORBIDDEN_TOKENS:
            if token in name:
                findings.append(
                    PrivacyFinding(field=raw, sources=(), matched_token=token)
                )
                break
    return findings


def scan_contract_sources(
    fields_by_source: dict[str, set[str]],
) -> list[PrivacyFinding]:
    """Like :func:`scan_fields` but records which schema/model declared a hit."""
    merged: dict[str, list[str]] = {}
    for source, fields in fields_by_source.items():
        for field_name in fields:
            merged.setdefault(field_name, []).append(source)
    findings: list[PrivacyFinding] = []
    for raw in sorted(merged):
        name = raw.strip().lower()
        if name in ALLOWED_FIELDS:
            continue
        for token in FORBIDDEN_TOKENS:
            if token in name:
                findings.append(
                    PrivacyFinding(
                        field=raw, sources=tuple(merged[raw]), matched_token=token
                    )
                )
                break
    return findings

