"""Server-side authorization policy (docs/15 "Authorization", D08).

Every object access is scoped by the project ID + classroom ID pair before any
identifier lookup or byte is loaded. Decisions are deny-by-default and typed so
the API can translate them into 404s for inaccessible objects without leaking
existence.

Capture capabilities are random, revocable, short-lived, bound to one project +
checkpoint, and upload-only: they can never read, browse, list, or stream media.

A content hash is content identity, never access authorization: identical bytes
in another project grant nothing and deduplication must not reveal
cross-project existence (docs/04; regression S15).

The API (Phase 12) must call these functions before loading any object;
storage-layer or ORM-level checks alone are not authorization.
"""
from __future__ import annotations

import dataclasses
import hmac
import secrets
from dataclasses import dataclass, field
from datetime import datetime, timedelta, timezone
from typing import Callable, Literal

__all__ = [
    "Decision",
    "CaptureCapability",
    "Principal",
    "UploadLimits",
    "authorize",
    "authorize_asset_by_hash",
    "authorize_capture",
    "issue_capture_capability",
    "revoke_capture_capability",
    "validate_upload_limits",
]

ACTIONS = frozenset(
    {"read", "write", "media_range", "sse_stream", "job_read", "search", "research_export"}
)
_CAPTURE_READ_ACTIONS = frozenset(
    {"read", "browse", "list", "media_range", "sse_stream", "download", "delete"}
)
# Upload-only: the capability scope literal accepted by authorize_capture.
CaptureScope = Literal["upload"]

DEFAULT_CAPTURE_TTL_SECONDS = 30 * 60
MAX_CAPTURE_TTL_SECONDS = 24 * 60 * 60

# Server-side enforcement of docs/06 capture caps; the test suite pins these to
# configs/runtime.json so the two cannot drift apart silently.
CAPTURE_MAX_SECONDS = 30
CAPTURE_MAX_BYTES = 104857600

ALLOWED_UPLOAD_MIME_TYPES = frozenset(
    {
        "video/mp4",
        "video/webm",
        "audio/mp4",
        "audio/wav",
        "audio/x-wav",
        "audio/mpeg",
        "image/jpeg",
        "image/png",
    }
)
ARCHIVE_MIME_TYPES = frozenset(
    {"application/zip", "application/x-tar", "application/gzip", "application/x-7z-compressed",
     "application/x-rar-compressed", "application/java-archive"}
)


@dataclass(frozen=True)
class Decision:
    allowed: bool
    code: str


_OK = Decision(allowed=True, code="ok")


@dataclass(frozen=True)
class Principal:
    """An authenticated actor. ``memberships`` holds exact (project, classroom) pairs."""

    actor_id: str
    roles: frozenset[str] = field(default_factory=frozenset)
    memberships: frozenset[tuple[str, str]] = field(default_factory=frozenset)
    permissions: frozenset[str] = field(default_factory=frozenset)


def authorize(
    principal: Principal,
    *,
    project_id: str,
    classroom_id: str,
    action: str,
) -> Decision:
    """Scope an object action to the project/classroom membership pair."""
    if action not in ACTIONS:
        return Decision(allowed=False, code="unknown_action")
    if (project_id, classroom_id) not in principal.memberships:
        return Decision(allowed=False, code="not_member")
    if action == "research_export":
        if "researcher" not in principal.roles:
            return Decision(allowed=False, code="role_missing")
        if "research_export" not in principal.permissions:
            return Decision(allowed=False, code="research_export_permission_missing")
    return _OK


@dataclass(frozen=True)
class CaptureCapability:
    token: str
    project_id: str
    checkpoint_id: str
    expires_at: datetime
    scope: CaptureScope = "upload"
    revoked: bool = False


def issue_capture_capability(
    project_id: str,
    checkpoint_id: str,
    *,
    now: datetime,
    ttl_seconds: int = DEFAULT_CAPTURE_TTL_SECONDS,
    token_factory: Callable[[], str] = lambda: secrets.token_urlsafe(32),
) -> CaptureCapability:
    """Issue a random, short-lived, project/checkpoint-bound upload capability."""
    if now.tzinfo is None:
        raise ValueError("now must be timezone-aware (UTC)")
    if not 0 < ttl_seconds <= MAX_CAPTURE_TTL_SECONDS:
        raise ValueError("capture TTL must be within the short-lived policy window")
    expires_at = now + timedelta(seconds=ttl_seconds)
    return CaptureCapability(
        token=token_factory(),
        project_id=project_id,
        checkpoint_id=checkpoint_id,
        expires_at=expires_at,
    )


def revoke_capture_capability(capability: CaptureCapability) -> CaptureCapability:
    """Return the capability marked revoked; access checks deny it immediately."""
    return dataclasses.replace(capability, revoked=True)


def authorize_capture(
    capability: CaptureCapability,
    *,
    presented_token: str,
    action: str,
    project_id: str,
    checkpoint_id: str,
    now: datetime,
) -> Decision:
    """Authorize a capture-capability request. Upload-only, bound, live tokens."""
    if action == "upload":
        pass
    elif action in _CAPTURE_READ_ACTIONS:
        return Decision(allowed=False, code="capture_scope_upload_only")
    else:
        return Decision(allowed=False, code="unknown_action")
    if capability.revoked:
        return Decision(allowed=False, code="capture_revoked")
    if not hmac.compare_digest(capability.token, presented_token):
        return Decision(allowed=False, code="capture_token_mismatch")
    if (project_id, checkpoint_id) != (capability.project_id, capability.checkpoint_id):
        return Decision(allowed=False, code="capture_scope_binding")
    if now.tzinfo is None:
        raise ValueError("now must be timezone-aware (UTC)")
    if now >= capability.expires_at:
        return Decision(allowed=False, code="capture_expired")
    return _OK


def authorize_asset_by_hash(principal: Principal, sha256: str) -> Decision:
    """A content hash never authorizes access; cross-project hash lookup is denied.

    Two groups that produced byte-identical recordings still cannot read each
    other's assets, and hash-based deduplication must not reveal existence in
    another project (regressions S11/S15).
    """
    del principal, sha256
    return Decision(allowed=False, code="hash_is_not_authorization")


@dataclass(frozen=True)
class UploadLimits:
    max_bytes: int = CAPTURE_MAX_BYTES
    max_duration_ms: int = CAPTURE_MAX_SECONDS * 1000
    allowed_mime_types: frozenset[str] = ALLOWED_UPLOAD_MIME_TYPES
    archive_mime_types: frozenset[str] = ARCHIVE_MIME_TYPES


def validate_upload_limits(
    *,
    size_bytes: int,
    mime_type: str,
    duration_ms: int | None = None,
    limits: UploadLimits | None = None,
) -> Decision:
    """Server-side capture/upload caps (docs/06): reject limits, not just warn."""
    limits = limits or UploadLimits()
    if size_bytes < 0:
        return Decision(allowed=False, code="invalid_size")
    if size_bytes > limits.max_bytes:
        return Decision(allowed=False, code="payload_too_large")
    if duration_ms is not None:
        if duration_ms <= 0:
            return Decision(allowed=False, code="invalid_duration")
        if duration_ms > limits.max_duration_ms:
            return Decision(allowed=False, code="capture_too_long")
    normalized = mime_type.split(";")[0].strip().lower()
    if normalized in limits.archive_mime_types:
        return Decision(allowed=False, code="archive_refused")
    if normalized not in limits.allowed_mime_types:
        return Decision(allowed=False, code="unsupported_media_type")
    return _OK

