"""Authorization-before-lookup scoped queries (docs/15).

Every accessor joins the requested object to the caller's classroom
membership or project access inside one statement, so an inaccessible object
produces no row and the API answers 404 without confirming existence.
Content hashes never authorize anything (docs/04).
"""
from __future__ import annotations

from sqlalchemy import and_, or_, select
from sqlalchemy.orm import Session

from .errors import ApiError
from .models import (
    AnswerRequest,
    Asset,
    Checkpoint,
    Classroom,
    GuidanceAnswer,
    Membership,
    Observation,
    Project,
    ProjectAccess,
    Upload,
    ProcessingJob,
)
from .security import (
    CAPABILITY_ANALYZE,
    CAPABILITY_EXPORT,
    CAPABILITY_MANAGE,
    CAPABILITY_READ,
    CAPABILITY_UPLOAD,
    Principal,
    ROLE_CAPABILITIES,
)

# Effective project capabilities: explicit ProjectAccess overrides the
# classroom-level Membership role; both are required to be server-side rows.
def development_project_visible(session: Session, principal: Principal, project_id: str) -> bool:
    """A development identity cannot read real-source history in a reused DB."""
    if principal.via != "session_header":
        return True
    return session.scalar(select(Asset.id).where(
        Asset.project_id == project_id, Asset.origin == "approved_real",
    ).limit(1)) is None


_CAPABILITY_FOR_ERROR = {
    CAPABILITY_READ: "read",
    CAPABILITY_UPLOAD: "upload",
    CAPABILITY_ANALYZE: "analyze",
    CAPABILITY_EXPORT: "export",
    CAPABILITY_MANAGE: "manage",
}


def _scoped_project_row(
    session: Session, principal: Principal, project_id: str
):
    """Return ``(project, capabilities)`` or ``None`` when out of scope."""
    if principal.via == "capture_token":
        return None
    membership_role = session.execute(
        select(Membership.role)
        .join(Project, Project.classroom_id == Membership.classroom_id)
        .where(Project.id == project_id, Membership.principal_id == principal.principal_id)
        .limit(1)
    ).scalar_one_or_none()
    access_row = session.execute(
        select(ProjectAccess)
        .where(
            ProjectAccess.project_id == project_id,
            ProjectAccess.principal_id == principal.principal_id,
        )
        .execution_options(populate_existing=True)
        .limit(1)
    ).scalar_one_or_none()

    project = session.execute(
        select(Project).where(Project.id == project_id, Project.status == "active")
        .execution_options(populate_existing=True)
    ).scalar_one_or_none()
    if project is None:
        return None

    if membership_role is None and access_row is None:
        return None
    if not development_project_visible(session, principal, project_id):
        return None

    capabilities: set[str] = set()
    if membership_role is not None:
        capabilities |= ROLE_CAPABILITIES.get(membership_role, frozenset())
    if access_row is not None:
        capabilities |= ROLE_CAPABILITIES.get(access_row.role, frozenset())
        if access_row.can_research_export:
            capabilities.add(CAPABILITY_EXPORT)
    return project, frozenset(capabilities)


def project_with_caps(
    session: Session, principal: Principal, project_id: str
) -> tuple[Project, frozenset[str]]:
    """Scoped project + capability set; raises 404 when out of scope."""
    found = _scoped_project_row(session, principal, project_id)
    if found is None:
        raise ApiError("not_found", "No such project in your scope")
    return found


def scoped_project(
    session: Session, principal: Principal, project_id: str, capability: str
) -> Project:
    """Load a project the principal may use with ``capability``, else 404."""
    found = _scoped_project_row(session, principal, project_id)
    if found is None:
        raise ApiError("not_found", "No such project in your scope")
    project, capabilities = found
    if capability not in capabilities:
        raise ApiError("not_found", "No such project in your scope")
    return project


def scoped_classroom(
    session: Session, principal: Principal, classroom_id: str
) -> Classroom:
    if principal.via == "capture_token":
        raise ApiError("not_found", "No such classroom in your scope")
    membership = session.execute(
        select(Membership).where(
            Membership.classroom_id == classroom_id,
            Membership.principal_id == principal.principal_id,
        )
    ).scalar_one_or_none()
    if membership is None:
        raise ApiError("not_found", "No such classroom in your scope")
    classroom = session.get(Classroom, classroom_id)
    if classroom is None:
        raise ApiError("not_found", "No such classroom in your scope")
    return classroom


def _child_in_scope(
    session: Session,
    principal: Principal,
    project_id_column,
    object_id_column,
    object_id: str,
    model,
    capability: str,
    label: str,
):
    """Load a child object only when it joins to a project the principal may
    use with ``capability``. One statement resolves object, scope, and role,
    so an out-of-scope ID yields no row and no capability."""
    if principal.via == "capture_token":
        raise ApiError("not_found", f"No such {label} in your scope")
    pid = principal.principal_id
    row = session.execute(
        select(model, Membership.role, ProjectAccess.role, ProjectAccess.can_research_export)
        .join(Project, Project.id == project_id_column)
        .outerjoin(
            Membership,
            and_(
                Membership.classroom_id == Project.classroom_id,
                Membership.principal_id == pid,
            ),
        )
        .outerjoin(
            ProjectAccess,
            and_(ProjectAccess.project_id == Project.id, ProjectAccess.principal_id == pid),
        )
        .where(
            object_id_column == object_id,
            Project.status == "active",
            or_(Membership.id.is_not(None), ProjectAccess.id.is_not(None)),
        )
        .limit(1)
    ).first()
    if row is None:
        raise ApiError("not_found", f"No such {label} in your scope")
    obj, membership_role, access_role, can_export = row
    capabilities: set[str] = set()
    if membership_role is not None:
        capabilities |= ROLE_CAPABILITIES.get(membership_role, frozenset())
    if access_role is not None:
        capabilities |= ROLE_CAPABILITIES.get(access_role, frozenset())
    if can_export:
        capabilities.add(CAPABILITY_EXPORT)
    if capability not in capabilities:
        raise ApiError("not_found", f"No such {label} in your scope")
    if not development_project_visible(session, principal, obj.project_id):
        raise ApiError("not_found", f"No such {label} in your scope")
    if capability == CAPABILITY_READ:
        from .services.consent import require_answer_source_use, require_asset_use
        if model is GuidanceAnswer:
            require_answer_source_use(session, obj)
        elif model in (Asset, Observation, ProcessingJob):
            source = obj if model is Asset else session.get(Asset, obj.asset_id) if obj.asset_id else None
            if source is not None and source.status == "active":
                require_asset_use(session, source, "teaching_review")
    return obj


def scoped_checkpoint(
    session: Session, principal: Principal, checkpoint_id: str, capability: str
) -> Checkpoint:
    """Checkpoint access. Capture tokens may only upload to their checkpoint."""
    if principal.via == "capture_token":
        if capability != CAPABILITY_UPLOAD or principal.capture_checkpoint_id != checkpoint_id:
            raise ApiError("not_found", "No such checkpoint in your scope")
        checkpoint = session.get(Checkpoint, checkpoint_id)
        if checkpoint is None:
            raise ApiError("not_found", "No such checkpoint in your scope")
        return checkpoint
    return _child_in_scope(
        session,
        principal,
        Checkpoint.project_id,
        Checkpoint.id,
        checkpoint_id,
        Checkpoint,
        capability,
        "checkpoint",
    )


def scoped_asset(
    session: Session, principal: Principal, asset_id: str, capability: str = CAPABILITY_READ
) -> Asset:
    return _child_in_scope(
        session, principal, Asset.project_id, Asset.id, asset_id, Asset, capability, "asset"
    )


def scoped_observation(
    session: Session, principal: Principal, observation_id: str, capability: str = CAPABILITY_READ
) -> Observation:
    return _child_in_scope(
        session,
        principal,
        Observation.project_id,
        Observation.id,
        observation_id,
        Observation,
        capability,
        "observation",
    )


def scoped_upload(
    session: Session, principal: Principal, upload_id: str, capability: str = CAPABILITY_UPLOAD
) -> Upload:
    if principal.via == "capture_token":
        upload = session.execute(
            select(Upload).where(
                Upload.id == upload_id,
                Upload.checkpoint_id == principal.capture_checkpoint_id,
                Upload.created_by == principal.principal_id,
            )
        ).scalar_one_or_none()
        if upload is None:
            raise ApiError("not_found", "No such upload in your scope")
        return upload
    return _child_in_scope(
        session, principal, Upload.project_id, Upload.id, upload_id, Upload, capability, "upload"
    )


def scoped_job(
    session: Session, principal: Principal, job_id: str
) -> ProcessingJob:
    return _child_in_scope(
        session,
        principal,
        ProcessingJob.project_id,
        ProcessingJob.id,
        job_id,
        ProcessingJob,
        CAPABILITY_READ,
        "job",
    )


def scoped_answer(
    session: Session, principal: Principal, answer_id: str
) -> GuidanceAnswer:
    return _child_in_scope(
        session,
        principal,
        GuidanceAnswer.project_id,
        GuidanceAnswer.id,
        answer_id,
        GuidanceAnswer,
        CAPABILITY_READ,
        "answer",
    )


def scoped_answer_request(
    session: Session, principal: Principal, request_id: str
) -> AnswerRequest:
    return _child_in_scope(
        session,
        principal,
        AnswerRequest.project_id,
        AnswerRequest.id,
        request_id,
        AnswerRequest,
        CAPABILITY_READ,
        "answer request",
    )

