"""Database engine, session, and declarative base (D06).

PostgreSQL 16 is the service target; the same DDL runs on SQLite for the
transactional unit path. JSON columns use JSONB on PostgreSQL and plain JSON
elsewhere; timestamps are timezone-aware UTC (ops/CONVENTIONS.md).
"""
from __future__ import annotations

from collections.abc import Iterator
from datetime import datetime, timezone

from sqlalchemy import JSON, event
from sqlalchemy import create_engine as sa_create_engine
from sqlalchemy.dialects import postgresql
from sqlalchemy.engine import Engine
from sqlalchemy.orm import DeclarativeBase, Session, sessionmaker

from .config import Settings, get_settings


def json_type():
    """JSONB on PostgreSQL, portable JSON elsewhere."""
    return postgresql.JSONB(astext_type=None).with_variant(JSON(), "sqlite")


def utcnow() -> datetime:
    return datetime.now(timezone.utc)


def as_aware(dt: datetime) -> datetime:
    """Normalize a DB-loaded timestamp for comparison.

    SQLite drops tzinfo on the way out; values were written as UTC, so naive
    timestamps are interpreted as UTC. PostgreSQL keeps the offset.
    """
    if dt.tzinfo is None:
        return dt.replace(tzinfo=timezone.utc)
    return dt


class Base(DeclarativeBase):
    pass


def create_engine(settings: Settings | None = None) -> Engine:
    settings = settings or get_settings()
    url = settings.resolved_database_url()
    if url.startswith("sqlite"):
        engine = sa_create_engine(url, connect_args={"check_same_thread": False})
    else:
        engine = sa_create_engine(url, pool_pre_ping=True)
    if url.startswith("sqlite"):
        @event.listens_for(engine, "connect")
        def _fk_on(dbapi_connection, connection_record):  # pragma: no cover - driver hook
            cursor = dbapi_connection.cursor()
            cursor.execute("PRAGMA foreign_keys=ON")
            cursor.close()

    return engine


def make_session_factory(engine: Engine) -> sessionmaker[Session]:
    return sessionmaker(bind=engine, expire_on_commit=False, autoflush=False)


def session_dependency(
    factory: sessionmaker[Session],
) -> Iterator[Session]:
    session = factory()
    try:
        yield session
        session.commit()
    except Exception:
        session.rollback()
        raise
    finally:
        session.close()


def default_session_factory() -> sessionmaker[Session]:
    return make_session_factory(create_engine(get_settings()))

"""FastAPI request dependencies: session, principal, object store."""
from __future__ import annotations

from collections.abc import Iterator

from fastapi import Depends, Request
from sqlalchemy.orm import Session

from .db import create_engine, default_session_factory, make_session_factory
from .objectstore import ObjectStore, store_from_settings
from .security import Principal, resolve_principal


def _session_factory(request: Request):
    factory = request.app.state.session_factory
    if factory is None:
        factory = make_session_factory(create_engine(request.app.state.settings))
        request.app.state.session_factory = factory
    return factory


def get_db(request: Request) -> Iterator[Session]:
    session = _session_factory(request)()
    try:
        yield session
        session.commit()
    except Exception:
        session.rollback()
        raise
    finally:
        session.close()


def get_principal(
    request: Request, db: Session = Depends(get_db)
) -> Principal:
    """Resolve session principal or validate a capture token against the DB."""
    return resolve_principal(request, db, request.app.state.settings)


def get_object_store(request: Request) -> ObjectStore:
    store = request.app.state.object_store
    if store is None:
        store = store_from_settings(request.app.state.settings)
        request.app.state.object_store = store
    return store


def get_correlation_id(request: Request) -> str:
    return getattr(request.state, "correlation_id", "")

