"""Content-addressed object store (D07, local filesystem adapter).

Storage keys are the SHA-256 of the bytes, never user filenames; the root
lives under ``MV_DATA_ROOT`` outside git with owner-only permissions. An
S3-compatible adapter can replace this class later without changing evidence
schemas (docs/03).
"""
from __future__ import annotations

import os
import re
import tempfile
from pathlib import Path
from typing import Protocol

from packages.domain.hashing import sha256_hex

_KEY_RE = re.compile(r"^[0-9a-f]{64}$")


def validate_key(key: str) -> str:
    if not _KEY_RE.match(key):
        raise ValueError("Object keys are lowercase sha256 hex digests")
    return key


class ObjectStore(Protocol):
    def put(self, data: bytes) -> tuple[str, int]:
        """Store bytes; return ``(sha256, size)``."""

    def open(self, key: str) -> bytes:
        """Return stored bytes."""

    def exists(self, key: str) -> bool:
        ...


class FileSystemObjectStore:
    """Private filesystem store: ``<root>/<aa>/<bb>/<sha256>``."""

    def __init__(self, root: Path) -> None:
        self.root = Path(root)
        self.root.mkdir(parents=True, exist_ok=True)
        os.chmod(self.root, 0o700)

    def path_for(self, key: str) -> Path:
        validate_key(key)
        return self.root / key[:2] / key[2:4] / key

    def put(self, data: bytes) -> tuple[str, int]:
        digest = sha256_hex(data)
        final = self.path_for(digest)
        final.parent.mkdir(parents=True, exist_ok=True)
        if not final.exists():
            fd, tmp_name = tempfile.mkstemp(dir=str(final.parent), suffix=".part")
            try:
                with os.fdopen(fd, "wb") as handle:
                    handle.write(data)
                os.chmod(tmp_name, 0o600)
                os.replace(tmp_name, final)
            finally:
                if os.path.exists(tmp_name):
                    os.unlink(tmp_name)
        return digest, len(data)

    def open(self, key: str) -> bytes:
        return self.path_for(key).read_bytes()

    def exists(self, key: str) -> bool:
        try:
            return self.path_for(key).is_file()
        except ValueError:
            return False


def store_from_settings(settings) -> FileSystemObjectStore:
    return FileSystemObjectStore(settings.data_root / "objects")

