from ..security import Principal, CAPABILITY_EXPORT
from ..services import fold_studio as service

router=APIRouter(prefix='/fold-studio')


class Strict(BaseModel):model_config=ConfigDict(extra='forbid',allow_inf_nan=False)
class New(Strict):
    project_id:str=Field(min_length=1,max_length=64)
    seed:int=Field(default=17,ge=0,le=1000000)
