@router.get('/health')
def health(request:Request):
    engine=service.runtime()
    from ..services.fold_observation import configuration
    try:configuration(request.app.state.settings)
    except ApiError:local_observation='unavailable: native Fold observer not approved/configured'
    else:local_observation='configured: opt-in synthetic-source review; execution and quality unverified'
    return {'status':'ok','policy':bool(engine.POLICY),'diagram_encoder':bool(engine.VISION),'outcome_model':bool(engine.OUTCOME),
                     'real_photo_diagnosis':False,'study_validated':False,'local_observation':local_observation}
@router.get('/activity')
