@router.post('/sessions')
def create(req:New,principal:Principal=Depends(get_principal),db:Session=Depends(get_db)):
    return {'session':service.create(db,principal,req.project_id,req.seed,req.mode,req.cap),'key':None}
@router.get('/sessions/{sid}')
def get(sid:str,principal:Principal=Depends(get_principal),db:Session=Depends(get_db),store=Depends(get_object_store)):
