    return service.mutate(db,principal,sid,req,'act',lambda d:service.runtime().execute(d,req.action_id,req.recommendation_id,req.edited_prompt),store=store)
@router.post('/sessions/{sid}/enact')
def enact(sid:str,req:Enact,principal:Principal=Depends(get_principal),db:Session=Depends(get_db),store=Depends(get_object_store)):
    return service.mutate(db,principal,sid,req,'enact',lambda d:service.runtime().enact(d,req.selection_id,req.action_id,req.actual_seconds),store=store)
@router.post('/sessions/{sid}/context')
def context(sid:str,req:Context,principal:Principal=Depends(get_principal),db:Session=Depends(get_db),store=Depends(get_object_store)):
    def change(d):
        d.update(cap=req.cap,remaining=req.remaining)
        if req.request_evidence is not None:d['request_evidence']=req.request_evidence
        service.runtime().refresh(d)
    return service.mutate(db,principal,sid,req,'context',change,store=store)
@router.post('/sessions/{sid}/note')
def note(sid:str,req:Note,principal:Principal=Depends(get_principal),db:Session=Depends(get_db),store=Depends(get_object_store)):
    def change(d):
        if req.evidence_id and req.evidence_id not in {e['id'] for e in d['evidence']}:raise ValueError('Foreign citation')
        engine=service.runtime();source=engine.source_metadata({'id':uuid.uuid4().hex,'origin':'human_report','title':'Teacher observation',
            'text':req.text,'method':'Attributed report; no physical or diagnostic verification','at':engine.stamp(),'cites':req.evidence_id})
        d['evidence'].append(source);engine.link_subsequent_evidence(d,req.selection_id,source['id'])
        service.runtime('actor_receipts').record_source(d,engine.TASK_GRAPH.graph,source,engine.stamp())
        engine.refresh(d)
    return service.mutate(db,principal,sid,req,'note',change,store=store)
@router.post('/sessions/{sid}/checkpoint')
def link(sid:str,req:Link,principal:Principal=Depends(get_principal),db:Session=Depends(get_db),store=Depends(get_object_store)):
