    if not req.rights_confirmed:raise ApiError('unprocessable_entity','Confirm permission to link this source')
    asset,_,size,first_uploaded_at=service.source_bytes(db,principal,row.project_id,req.asset_id,store)
    return service.mutate(db,principal,sid,req,'checkpoint',lambda d:service.attach(d,asset,size,req.note,req.selection_id,first_uploaded_at),store=store)
@router.get('/sessions/{sid}/image/{eid}')
def image(sid:str,eid:str,principal:Principal=Depends(get_principal),db:Session=Depends(get_db),store=Depends(get_object_store)):
    row=service.scoped(db,principal,sid)
    source=next((e for e in row.payload['evidence'] if e['id']==eid),None)
    if not source:raise ApiError('not_found','Fold source unavailable')
    if source.get('native_asset_id'):
        asset,content=service.validated_source(db,principal,row.project_id,source,store)
        return Response(content,media_type=asset.mime_type,headers={'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'})
    if 'view' not in source:raise ApiError('not_found','No image attached')
    diagrams=service.runtime('diagrams')
    return Response(diagrams.png_bytes(diagrams.draw_diagram(source['view'],source['symbol'],source['render_seed'])),media_type='image/png')
@router.post('/sessions/{sid}/observe')
def observe(sid:str,req:Observe,request:Request,principal:Principal=Depends(get_principal),
            db:Session=Depends(get_db),store=Depends(get_object_store)):
    return service.observe(db,principal,sid,req,store,request.app.state.settings,
        reauthorize=lambda:get_principal(request,db))
@router.get('/sessions/{sid}/export')
def export(sid:str,principal:Principal=Depends(get_principal),db:Session=Depends(get_db),store=Depends(get_object_store)):
    row=service.scoped(db,principal,sid,CAPABILITY_EXPORT)
    service.validate_sources(db,principal,row,store)
    graph=service.runtime().TASK_GRAPH.graph
    return {'schema':'mv-fold-native-session/1','data':service.read_public(db,principal,row,store),
            'instruction_graph':graph.model_dump(mode='json'),'graph_hash':graph.digest(),
            'actor_receipts':service.export_actor_receipts(row.payload),
            'limitations':'Synthetic/review adapter; no human Fold protocol approval, photo diagnosis or native mechanism/fold semantic conversion'}


@router.get('/sessions/{sid}/actor-inputs/{recommendation_id}')
def actor_inputs(sid:str,recommendation_id:str,principal:Principal=Depends(get_principal),
                 db:Session=Depends(get_db),store=Depends(get_object_store)):
    # Replay contains export-level teacher/source metadata. Resolve that same
    # grant and all source authority/integrity before looking up the target.
    row=service.scoped(db,principal,sid,CAPABILITY_EXPORT)
    service.validate_sources(db,principal,row,store)
    try:
        return service.actor_decision_summary(row.payload,recommendation_id)
    except service.runtime('actor_receipts').ReceiptUnavailable as exc:
        return {'status':'unavailable','error_code':exc.code,'model_training':'not_admitted'}
@router.delete('/sessions/{sid}')
def remove(sid:str,principal:Principal=Depends(get_principal),db:Session=Depends(get_db)):
    service.remove(db,principal,sid);return {'deleted':True,'native_assets_deleted':False}

