"""Persistent teacher follow-ups and their explicitly linked later records."""
from __future__ import annotations

from fastapi import APIRouter, Depends
from sqlalchemy.orm import Session

from ..authz import _child_in_scope, scoped_project
from ..dependencies import get_correlation_id, get_db, get_principal
from ..dto import (
    FollowUpCreate,
    FollowUpEventCreate,
    FollowUpEventResponse,
    FollowUpListResponse,
    FollowUpResponse,
)
from ..models import TeacherFollowUp
from ..security import CAPABILITY_MANAGE, CAPABILITY_READ, Principal
from ..services import longitudinal

router = APIRouter()


def _scoped_follow_up(
    session: Session, principal: Principal, follow_up_id: str, capability: str
) -> TeacherFollowUp:
    # Resolve the child and its project/classroom capability together, before
    # accessing the source answer or any later event. Capture tokens cannot
    # read this journal or turn upload permission into a teacher decision.
    return _child_in_scope(
        session, principal, TeacherFollowUp.project_id, TeacherFollowUp.id,
        follow_up_id, TeacherFollowUp, capability, "follow-up",
    )


@router.post(
    "/projects/{project_id}/follow-ups", response_model=FollowUpResponse, status_code=201
)
def create_follow_up(
    project_id: str,
    payload: FollowUpCreate,
    principal: Principal = Depends(get_principal),
    session: Session = Depends(get_db),
    correlation_id: str = Depends(get_correlation_id),
) -> FollowUpResponse:
    project = scoped_project(session, principal, project_id, CAPABILITY_MANAGE)
    row = longitudinal.create_follow_up(
        session, project, teacher_decision_id=payload.teacher_decision_id,
        choice=payload.choice, request_text=payload.request_text,
        actor=principal.principal_id, correlation_id=correlation_id,
    )
    return FollowUpResponse(**longitudinal.follow_up_view(session, row))


@router.get("/projects/{project_id}/follow-ups", response_model=FollowUpListResponse)
def list_follow_ups(
    project_id: str,
    snapshot: str | None = None,
    principal: Principal = Depends(get_principal),
    session: Session = Depends(get_db),
) -> FollowUpListResponse:
    project = scoped_project(session, principal, project_id, CAPABILITY_READ)
    return FollowUpListResponse(**longitudinal.list_follow_ups(session, project, snapshot_id=snapshot))


@router.get("/follow-ups/{follow_up_id}", response_model=FollowUpResponse)
def get_follow_up(
    follow_up_id: str,
    snapshot: str | None = None,
    principal: Principal = Depends(get_principal),
    session: Session = Depends(get_db),
) -> FollowUpResponse:
    row = _scoped_follow_up(session, principal, follow_up_id, CAPABILITY_READ)
    cutoff = longitudinal.snapshot_cutoff(session, row.project_id, snapshot)
    return FollowUpResponse(**longitudinal.follow_up_view(session, row, cutoff=cutoff, snapshot_id=snapshot))


@router.post(
    "/follow-ups/{follow_up_id}/events", response_model=FollowUpEventResponse, status_code=201
)
def append_follow_up_event(
    follow_up_id: str,
    payload: FollowUpEventCreate,
    principal: Principal = Depends(get_principal),
    session: Session = Depends(get_db),
    correlation_id: str = Depends(get_correlation_id),
) -> FollowUpEventResponse:
    row = _scoped_follow_up(session, principal, follow_up_id, CAPABILITY_MANAGE)
    project = scoped_project(session, principal, row.project_id, CAPABILITY_MANAGE)
    event = longitudinal.append_event(
        session, project, row, **payload.model_dump(), actor=principal.principal_id,
        correlation_id=correlation_id,
    )
    return FollowUpEventResponse(**longitudinal.event_view(session, event))

