from fastapi import APIRouter, Depends, Request, Response

from ..dependencies import get_principal
from ..errors import ApiError
from ..security import Principal

router = APIRouter()


@router.get("/session-auth")
def session_auth_config(request: Request, response: Response):
    response.headers["Cache-Control"] = "no-store"
    return {"mode": request.app.state.settings.session_auth_mode}


@router.get("/session")
def session_identity(request: Request, response: Response, principal: Principal = Depends(get_principal)):
    if principal.via == "capture_token":
        raise ApiError("unauthorized", "An upload capability cannot identify a session")
    response.headers["Cache-Control"] = "no-store"
    return {"mode": request.app.state.settings.session_auth_mode,
            "principal_id": principal.principal_id,
            "authenticated": principal.via == "session_credential"}

