"""Failure-reading account (docs/23 C1, D33): one checkpoint, read-only.

The account is a **pure composition of persisted records** — observations,
hypotheses, design facts, citations, and verification provenance (docs/09).
No fact is computed, inferred, or reworded at render time:

- ``observed`` restates active Observation rows with resolvable citations;
  a record whose source asset cannot be resolved is never cited (docs/09
  citation validator; S11) unless it is itself an authored design fact,
  which rule 1 allows to carry its source version instead.
- ``data_gaps`` names missing modalities explicitly from persisted
  declarations — missing audio is not silence and missing tracking is not
  immobility (D21, S03/S08).
- ``where_to_look`` anchors are derived only from persisted hypotheses and
  design facts; this module never ranks, scores, or invents anchors.
- ``supported_excluded`` statuses come from the persisted hypothesis
  ``verification_status`` column and are shown only while a persisted
  ``Verification`` record (docs/09) backs them; ``unresolved`` is a normal,
  expected status (symptom is not cause, D21).
- Composition is deterministic: identical persisted rows produce identical
  response bytes. Ordering is always (created_at, id), anchor_id, or
  hypothesis (rank, id) — never provider confidence or wall-clock time.

Teacher context (D22) is an input to guidance elsewhere and never enters
this account; the endpoint is a GET and advances no state (D23).
"""
from __future__ import annotations

from sqlalchemy import select
from sqlalchemy.orm import Session

from contracts.models import Verification as VerificationContract

from ..models import Asset, Checkpoint, DesignVersion, Hypothesis, Observation
from . import snapshots

AUDIO_CAPABLE_KINDS = ("video", "audio")
VISUAL_KINDS = ("video", "image")
DESIGN_FACT_KIND = "design_fact"
TRACKING_GAP_CANDIDATE = "tracking_gap"

# Fixed gap order so identical rows always serialize identically.
_GAP_KIND_ORDER = {"audio_missing": 0, "video_missing": 1, "tracking_gap": 2, "citation_unresolved": 3}

# Persisted verification_status vocabulary that maps to an excluded reading.
_EXCLUDED_STATUSES = frozenset({"excluded", "contradicted", "refuted"})
_SUPPORTED_STATUS = "supported"
_UNRESOLVED_STATUS = "unresolved"


def _observed_entry(row: Observation, asset: Asset | None) -> dict:
    span = None
    if row.span_start_ms is not None and row.span_end_ms is not None:
        span = {"start_ms": row.span_start_ms, "end_ms": row.span_end_ms}
    citations = []
    if asset is not None:
        citations.append(
            {"asset_id": asset.id, "seek_ms": row.span_start_ms if span else None}
        )
    return {
        "evidence_id": row.id,
        "record_kind": row.record_kind,
        "statement": row.statement,
        "modality": row.modality,
        # C1 rule 1, second branch: an authored design fact carries the
        # design version it was authored against; observations carry the
        # version they were recorded against (D09 version scoping).
        "design_version_id": row.design_version_id,
        "component_ids": list(row.component_ids or []),
        "span": span,
        "confidence": dict(row.confidence or {}),
        "citations": citations,
    }


def _verified_record(session: Session, observation_ids: list[str]) -> dict | None:
    """The persisted ``Verification`` record for a hypothesis's evidence.

    Only contract-valid verification provenance is composed; an invalid
    payload is never presented as verification (F04). Deterministic choice:
    lowest observation id carrying verification.
    """
    for observation_id in sorted(observation_ids):
        row = session.get(Observation, observation_id)
        if row is None or row.verification is None:
            continue
        try:
            return VerificationContract.model_validate(row.verification).model_dump(
                mode="json"
            )
        except Exception:
            continue
    return None


def _hypothesis_status(
    session: Session, hypothesis: Hypothesis, evidence_ids: list[str]
) -> str:
    """Persisted status, shown only with persisted verification provenance.

    A supported/excluded reading without a ``Verification`` record stays
    ``unresolved`` here: the account never amplifies an unbacked status and
    never derives one from symptom evidence (D21, docs/09).
    """
    persisted = (hypothesis.verification_status or "").strip()
    if _verified_record(session, evidence_ids) is None:
        return _UNRESOLVED_STATUS
    if persisted == _SUPPORTED_STATUS:
        return _SUPPORTED_STATUS
    if persisted in _EXCLUDED_STATUSES:
        return "excluded"
    return _UNRESOLVED_STATUS


def build_account(session: Session, checkpoint: Checkpoint) -> dict:
    """Compose the account dict for one checkpoint from persisted rows only."""
    design = session.get(DesignVersion, checkpoint.design_version_row_id)
    if design is None or design.project_id != checkpoint.project_id:
        from ..errors import ApiError

        raise ApiError(
            "unprocessable_entity",
            "Checkpoint design version is not resolvable in this project",
        )

    observations = session.execute(
        select(Observation)
        .where(
            Observation.project_id == checkpoint.project_id,
            Observation.checkpoint_id == checkpoint.id,
            Observation.status == "active",
        )
        .order_by(Observation.created_at, Observation.id)
    ).scalars().all()
    superseded = session.execute(
        select(Observation.id)
        .where(
            Observation.project_id == checkpoint.project_id,
            Observation.checkpoint_id == checkpoint.id,
            Observation.status == "superseded",
        )
        .order_by(Observation.created_at, Observation.id)
    ).scalars().all()

    assets_by_id: dict[str, Asset | None] = {}

    def asset_for(asset_id: str) -> Asset | None:
        if asset_id not in assets_by_id:
            row = session.execute(
                select(Asset).where(
                    Asset.project_id == checkpoint.project_id, Asset.id == asset_id
                )
            ).scalar_one_or_none()
            # A deleted (tombstoned) asset is not a resolvable citation.
            assets_by_id[asset_id] = row if row is not None and row.status == "active" else None
        return assets_by_id[asset_id]

    checkpoint_assets = session.execute(
        select(Asset)
        .where(
            Asset.project_id == checkpoint.project_id,
            Asset.checkpoint_id == checkpoint.id,
            Asset.status == "active",
        )
        .order_by(Asset.created_at, Asset.id)
    ).scalars().all()

    # --- observed: cited records, with design facts kept by source version ---
    observed: list[dict] = []
    unresolved: list[str] = []
    for row in observations:
        asset = asset_for(row.asset_id)
        if asset is None:
            # C1 rule 1: no entry without a resolvable citation; the gap is
            # recorded explicitly instead of silently dropping the evidence.
            # An authored design fact is still observed via its source version
            # (docs/23 C1 exception), but the unresolved citation stays flagged.
            unresolved.append(row.id)
            if row.record_kind != DESIGN_FACT_KIND:
                continue
        observed.append(_observed_entry(row, asset))

    # --- data_gaps: explicit missing modalities from persisted declarations --
    gaps: list[dict] = []
    for asset in checkpoint_assets:
        if asset.kind in AUDIO_CAPABLE_KINDS and asset.audio_status == "missing":
            gaps.append(
                {
                    "kind": "audio_missing",
                    "note": (
                        f"Asset {asset.id} declares audio_status=missing;"
                        " missing audio is not silence"
                    ),
                }
            )
    if not any(asset.kind in AUDIO_CAPABLE_KINDS for asset in checkpoint_assets):
        gaps.append(
            {
                "kind": "audio_missing",
                "note": (
                    "No audio-bearing asset is present at this checkpoint;"
                    " missing audio is not silence"
                ),
            }
        )
    if not any(asset.kind in VISUAL_KINDS for asset in checkpoint_assets):
        gaps.append(
            {
                "kind": "video_missing",
                "note": (
                    "No video or image asset is present at this checkpoint;"
                    " missing visual evidence is not immobility"
                ),
            }
        )
    for row in observations:
        measurement = row.measurement if isinstance(row.measurement, dict) else {}
        if row.record_kind == "missing_evidence" and (
            measurement.get("candidate_kind") == TRACKING_GAP_CANDIDATE
        ):
            gaps.append(
                {
                    "kind": "tracking_gap",
                    "note": (
                        f"Record {row.id} marks a tracking gap; missing"
                        " tracking is not immobility"
                    ),
                }
            )
    for evidence_id in unresolved:
        gaps.append(
            {
                "kind": "citation_unresolved",
                "note": (
                    f"Persisted record {evidence_id} has no resolvable source"
                    " asset, so it is not cited here"
                ),
            }
        )
    gaps.sort(key=lambda gap: (_GAP_KIND_ORDER[gap["kind"]], gap["note"]))

    # --- where_to_look: persisted hypotheses and design facts only ----------
    facts = [row for row in observations if row.record_kind == DESIGN_FACT_KIND]
    evidence_by_component: dict[str, set[str]] = {}
    hypothesis_by_component: dict[str, set[str]] = {}
    for row in facts:
        for component_id in row.component_ids or []:
            evidence_by_component.setdefault(component_id, set()).add(row.id)

    hypothesis_rows = session.execute(
        select(Hypothesis).where(Hypothesis.project_id == checkpoint.project_id)
    ).scalars().all()
    observations_by_id = {row.id: row for row in observations}
    in_scope: list[tuple[Hypothesis, list[str]]] = []
    for hypothesis in hypothesis_rows:
        referenced_ids = sorted(
            set(hypothesis.supporting_observation_ids or [])
            | set(hypothesis.contradicting_observation_ids or [])
        )
        # A hypothesis enters this checkpoint's account only through a
        # persisted reference to an observation recorded here.
        resolving = [
            observation_id
            for observation_id in referenced_ids
            if observation_id in observations_by_id
        ]
        if not resolving:
            continue
        in_scope.append((hypothesis, resolving))
        for observation_id in resolving:
            row = observations_by_id[observation_id]
            for component_id in row.component_ids or []:
                evidence_by_component.setdefault(component_id, set()).add(observation_id)
                hypothesis_by_component.setdefault(component_id, set()).add(hypothesis.id)

    anchors: list[dict] = []
    for component_id in sorted(evidence_by_component):
        anchors.append(
            {
                "anchor_kind": "component",
                "anchor_id": component_id,
                "reason_evidence_ids": sorted(evidence_by_component[component_id]),
                "hypothesis_ids": sorted(hypothesis_by_component.get(component_id, set())),
            }
        )
    payload = design.payload if isinstance(design.payload, dict) else {}
    if payload.get("design_kind") == "assembly":
        # Build-step anchors are a structural join against the persisted
        # design payload: only steps placing a referenced component appear,
        # ordered by their persisted step index. No step is invented.
        evidence_ids_by_step: dict[int, set[str]] = {}
        hypotheses_by_step: dict[int, set[str]] = {}
        for step in payload.get("build_steps") or []:
            if not isinstance(step, dict):
                continue
            index = step.get("index")
            placed = step.get("component_ids")
            if not isinstance(index, int) or not isinstance(placed, list):
                continue
            for component_id in placed:
                for evidence_id in evidence_by_component.get(component_id, ()):
                    evidence_ids_by_step.setdefault(index, set()).add(evidence_id)
                for hypothesis_id in hypothesis_by_component.get(component_id, ()):
                    hypotheses_by_step.setdefault(index, set()).add(hypothesis_id)
        for index in sorted(evidence_ids_by_step):
            anchors.append(
                {
                    "anchor_kind": "build_step",
                    "anchor_id": str(index),
                    "reason_evidence_ids": sorted(evidence_ids_by_step[index]),
                    "hypothesis_ids": sorted(hypotheses_by_step.get(index, set())),
                }
            )

    # --- supported_excluded: persisted statuses, persisted verification ------
    supported_excluded: list[dict] = []
    for hypothesis, resolving in sorted(
        in_scope, key=lambda item: (item[0].rank, item[0].id)
    ):
        supported_excluded.append(
            {
                "hypothesis_id": hypothesis.id,
                "status": _hypothesis_status(session, hypothesis, resolving),
                "evidence_ids": list(resolving),
                "verification": _verified_record(session, resolving),
            }
        )

    return {
        "checkpoint_id": checkpoint.id,
        "design_version_id": design.version_id,
        "staleness": {
            # Existing stale-answer semantics (S10): the digest over persisted
            # observation status, the same comparison answers use. The account
            # is composed live, so it is current by construction; corrections
            # remain visible as preserved superseded records (D09).
            "snapshot_hash": snapshots.current_snapshot_hash(
                session, checkpoint.project_id
            ),
            "is_current": True,
            "superseded_observation_ids": list(superseded),
        },
        "observed": observed,
        "data_gaps": gaps,
        "where_to_look": anchors,
        "supported_excluded": supported_excluded,
    }

