"""Operator-provisioned local research authentication, without enrollment.

Login credentials must be random opaque values with at least 256 bits of
entropy. Settings contain their SHA-256 digests; the database contains only
session and CSRF digests. Neither credentials nor cookies enter audit logs.
Project and classroom permissions remain separate server-side records.
"""
from __future__ import annotations

import hashlib
import hmac
import ipaddress
import re
import secrets
from dataclasses import dataclass, field
from datetime import timedelta
from urllib.parse import urlsplit

from fastapi import Request
from sqlalchemy import select
from sqlalchemy.orm import Session

from packages.domain.ids import new_id
from security.deployment_gate import is_loopback_host

from ..config import Settings
from ..db import as_aware, utcnow
from ..errors import ApiError
from ..models import AuthenticationSession

SESSION_COOKIE = "__Host-mv_session"
CSRF_HEADER = "X-MV-CSRF"
SAFE_METHODS = frozenset({"GET", "HEAD", "OPTIONS"})
_HASH = re.compile(r"[0-9a-f]{64}")
_CREDENTIAL = re.compile(r"[A-Za-z0-9_-]{43,256}")
_SESSION = re.compile(r"mvsession_[A-Za-z0-9_-]{43}")
_UNKNOWN_DIGEST = hashlib.sha256(b"mv-unknown-principal-v1").hexdigest()


def _digest(value: str) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def https_origin(value: str) -> str | None:
    """Accept one canonical HTTPS origin, without userinfo, paths or wildcards."""
    try:
        parsed = urlsplit(value)
        host, port = parsed.hostname, parsed.port
    except ValueError:
        return None
    if (
        parsed.scheme != "https"
        or not host
        or parsed.username is not None
        or parsed.password is not None
        or parsed.path
        or parsed.query
        or parsed.fragment
        or not re.fullmatch(r"[a-z0-9.:-]+", host)
    ):
        return None
    authority = f"[{host}]" if ":" in host else host
    if port is not None and port != 443:
        authority += f":{port}"
    canonical = f"https://{authority}"
    return canonical if canonical == value else None


def research_authentication_configured(settings: Settings) -> bool:
    hashes = settings.research_login_hashes
    return bool(
        settings.authentication_mode == "research_session"
        and https_origin(settings.research_origin)
        and hashes
        and all(
            principal and principal.strip() == principal and len(principal) <= 200
            and _HASH.fullmatch(digest) and digest != "0" * 64
            for principal, digest in hashes.items()
        )
    )


def validate_research_settings(settings: Settings) -> None:
    if not research_authentication_configured(settings):
        raise ValueError(
            "Research authentication requires an exact HTTPS origin and "
            "operator-provisioned principal credential digests"
        )


def require_research_transport(
    request: Request, settings: Settings, *, require_origin: bool = False
) -> None:
    """Verify the effective request URL; forwarded headers are not interpreted here.

    A deployment's trusted TLS termination must supply the ASGI HTTPS scheme.
    Merely presenting X-Forwarded-Proto cannot change the decision in this layer.
    Browser mutations additionally need the exact configured Origin.
    """
    if not research_authentication_configured(settings):
        raise ApiError("unavailable", "Research authentication is not configured")
    requested_origin = f"{request.url.scheme}://{request.url.netloc}"
    if requested_origin != settings.research_origin:
        raise ApiError("forbidden_scope", "Research requests require the configured HTTPS origin")
    if is_loopback_host(settings.host):
        try:
            local_peer = bool(request.client and ipaddress.ip_address(request.client.host).is_loopback)
        except ValueError:
            local_peer = False
        if not local_peer:
            raise ApiError("forbidden_scope", "Local research authentication is restricted to loopback")
    supplied_origin = request.headers.get("origin")
    if (
        (require_origin and supplied_origin is None)
        or (supplied_origin is not None and supplied_origin != settings.research_origin)
        or request.headers.get("sec-fetch-site", "").lower() == "cross-site"
    ):
        raise ApiError("forbidden_scope", "Request origin is not allowed")


def csrf_for_session(raw_session: str) -> str:
    """Stable per-session browser CSRF value, recoverable only with the cookie."""
    return hmac.new(
        raw_session.encode("utf-8"), b"mv-research-csrf-v1", hashlib.sha256
    ).hexdigest()


@dataclass(frozen=True)
class AuthenticatedSession:
    row: AuthenticationSession
    raw_session: str = field(repr=False)

    @property
    def csrf_token(self) -> str:
        return csrf_for_session(self.raw_session)


def authenticate_session(
    request: Request, session: Session, settings: Settings
) -> AuthenticatedSession:
    """Resolve an unrevoked, unexpired cookie, then enforce mutation CSRF."""
    mutation = request.method.upper() not in SAFE_METHODS
    require_research_transport(request, settings, require_origin=mutation)
    raw = request.cookies.get(SESSION_COOKIE, "")
    if not _SESSION.fullmatch(raw):
        raise ApiError("unauthorized", "A valid research session is required")
    row = session.execute(
        select(AuthenticationSession).where(
            AuthenticationSession.token_hash == _digest(raw),
            AuthenticationSession.revoked_at.is_(None),
        )
    ).scalar_one_or_none()
    if (
        row is None
        or as_aware(row.expires_at) <= utcnow()
        or row.principal_id not in settings.research_login_hashes
        or not hmac.compare_digest(row.csrf_token_hash, _digest(csrf_for_session(raw)))
    ):
        raise ApiError("unauthorized", "A valid research session is required")
    if mutation:
        supplied = request.headers.get(CSRF_HEADER, "")
        if len(supplied) != 64 or not hmac.compare_digest(
            row.csrf_token_hash, _digest(supplied)
        ):
            raise ApiError("forbidden_scope", "A valid request CSRF value is required")
    return AuthenticatedSession(row, raw)


def log_in(
    session: Session,
    settings: Settings,
    principal_id: str,
    credential: str,
    *,
    prior_cookie: str | None = None,
) -> AuthenticatedSession:
    """Issue a fresh opaque cookie after constant-time credential verification."""
    if not research_authentication_configured(settings):
        raise ApiError("unavailable", "Research authentication is not configured")
    expected = settings.research_login_hashes.get(principal_id, _UNKNOWN_DIGEST)
    matched = hmac.compare_digest(_digest(credential), expected)
    if not (
        matched and principal_id in settings.research_login_hashes
        and _CREDENTIAL.fullmatch(credential)
    ):
        # Unknown principals and incorrect credentials have the same public result.
        raise ApiError("unauthorized", "Research login was not accepted")

    if prior_cookie is not None and _SESSION.fullmatch(prior_cookie):
        prior = session.execute(
            select(AuthenticationSession).where(
                AuthenticationSession.token_hash == _digest(prior_cookie),
                AuthenticationSession.revoked_at.is_(None),
            )
        ).scalar_one_or_none()
        if prior is not None:
            prior.revoked_at = utcnow()
            session.add(prior)

    raw = "mvsession_" + secrets.token_urlsafe(32)
    now = utcnow()
    row = AuthenticationSession(
        id=new_id("authentication_session"),
        principal_id=principal_id,
        token_hash=_digest(raw),
        csrf_token_hash=_digest(csrf_for_session(raw)),
        created_at=now,
        expires_at=now + timedelta(seconds=settings.research_session_ttl_seconds),
    )
    session.add(row)
    session.flush()
    return AuthenticatedSession(row, raw)


def revoke_session(session: Session, authenticated: AuthenticatedSession) -> None:
    authenticated.row.revoked_at = utcnow()
    session.add(authenticated.row)
    session.flush()

