"""Explicit native authorization/state/media adapter for the isolated Fold lab.

It does not convert a fold graph into a native mechanism DesignVersion or a
photo into a diagnostic Observation. Actual Asset ids/digests remain intact.
"""
from __future__ import annotations
import copy
import hashlib
import importlib
import json
import uuid
from datetime import datetime, timedelta, timezone
from io import BytesIO

from PIL import Image, UnidentifiedImageError
from sqlalchemy import delete, select, update, func
from sqlalchemy.orm import Session
from sqlalchemy.exc import IntegrityError

from packages.domain.ids import new_id
from ..authz import scoped_asset, scoped_project, _child_in_scope
from ..errors import ApiError
from ..db import as_aware
from ..fold_models import FoldOperation, FoldSession
from ..models import Asset
from ..security import CAPABILITY_ANALYZE, CAPABILITY_MANAGE, CAPABILITY_READ, Principal

NATIVE_SOURCE_RECEIPTS = '_native_source_receipts'
SYNTHETIC_ORIGINS = frozenset({'synthetic_media', 'synthetic_contract_fixture'})


def runtime(module='engine'):
    # The lab remains its own package, with its own activity/model namespace.
    # Importing this runtime never creates the standalone SQLite Store.
    return importlib.import_module('labs.fold-studio.mvstudio.' + module)


def public(data):
    # Native provenance pins belong to the private transaction payload, as
    # do the copied runtime's actor receipts. Cached responses use this too.
    return {key: value for key, value in runtime().public(data).items()
            if key != NATIVE_SOURCE_RECEIPTS}


def actor_source_reference(evidence):
    if not evidence.get('native_asset_id'):
        return runtime('actor_receipts')._source_reference(evidence)
    if evidence['origin'] not in SYNTHETIC_ORIGINS or evidence['modality'] != 'image':
        raise ValueError('Unsupported native source projection')
    return runtime('contracts').SourceReference(
        source_id=evidence['id'], source_sha256=evidence['source_sha256'],
        origin='synthetic', modality='image', width=evidence['width'], height=evidence['height'],
        original_at=None)


def _native_source_digest(data, source):
    # These fields are absent from the shared SourceReference. Pin the whole
    # original row plus project at receipt; this is consistency, not signing.
    content = json.dumps({'project_id': data['native_project_id'], 'source': source},
                         sort_keys=True, separators=(',', ':'), allow_nan=False).encode()
    return hashlib.sha256(content).hexdigest()


def record_native_source(data, source, receipt_at):
    actor = runtime('actor_receipts')
    if actor.JOURNAL_KEY in data:
        pins = data.get(NATIVE_SOURCE_RECEIPTS)
        if not isinstance(pins, dict) or source['id'] in pins:
            data[actor.ERROR_KEY] = 'receipt_history_invalid_or_exhausted'
            return
        pins[source['id']] = _native_source_digest(data, source)
    actor.record_source(data, runtime().TASK_GRAPH.graph, source, receipt_at,
                        source_mapper=actor_source_reference)


def validate_receipt_sources(data):
    actor = runtime('actor_receipts')
    if actor.JOURNAL_KEY not in data:
        raise actor.ReceiptUnavailable('legacy_receipt_history_unavailable')
    try:
        sources = [source for source in data['evidence'] if source.get('native_asset_id')]
        pins = data.get(NATIVE_SOURCE_RECEIPTS)
        if (not isinstance(pins, dict) or len(sources) != len(pins) or
                set(pins) != {source['id'] for source in sources} or
                any(pins[source['id']] != _native_source_digest(data, source) for source in sources)):
            raise ValueError('Native source receipt disagrees with the original row')
    except (ValueError, KeyError, TypeError) as exc:
        raise actor.ReceiptUnavailable('receipt_history_invalid_or_exhausted') from exc


def export_actor_receipts(data):
    actor = runtime('actor_receipts')
    try:
        validate_receipt_sources(data)
    except actor.ReceiptUnavailable as exc:
        return {'status': 'unavailable', 'error_code': exc.code, 'model_training': 'not_admitted'}
    return actor.export_receipts(data, runtime().TASK_GRAPH.graph, source_mapper=actor_source_reference)


def actor_decision_summary(data, recommendation_id):
    validate_receipt_sources(data)
    return runtime('actor_receipts').decision_summary(
        data, runtime().TASK_GRAPH.graph, recommendation_id, source_mapper=actor_source_reference)


def scoped(db: Session, principal: Principal, sid: str, capability=CAPABILITY_READ):
    return _child_in_scope(db,principal,FoldSession.project_id,FoldSession.id,sid,FoldSession,capability,'Fold session')


def create(db, principal, project_id, seed, mode, cap):
    scoped_project(db, principal, project_id, CAPABILITY_MANAGE)
    if mode not in {'demo','review'}:raise ApiError('unprocessable_entity', 'Unknown Fold session mode')
    data=runtime().new_session(seed,mode,cap)
    sid=new_id('fold')
    data.update(id=sid,revision=0,operations=[],native_project_id=project_id,
                native_adapter='mv-fold-native/1',participant_use='not_approved')
    data[NATIVE_SOURCE_RECEIPTS] = {}
    row=FoldSession(id=sid,project_id=project_id,created_by=principal.principal_id,revision=0,payload=data)
    db.add(row);db.flush()
    return public(data)


def operation_digest(request, route):
    return hashlib.sha256(json.dumps({'route':route,'body':request.model_dump(mode='json')},sort_keys=True,separators=(',',':')).encode()).hexdigest()


def mutate(db,principal,sid,request,route,change,*,store,_observation_token=None):
    row=scoped(db,principal,sid,CAPABILITY_MANAGE)
    digest=operation_digest(request,route)
    old=db.get(FoldOperation,(sid,request.operation_id))
    if old:
        if old.request_sha256!=digest:raise ApiError('conflict','Operation already represents a different request')
        pending=old.response.get('_observation_pending')
        if pending:
            if _observation_token!=pending['token']:raise ApiError('conflict','Fold observation is already in progress',retryable=True)
        else:return read_public(db,principal,row,store,payload=old.response)
    if row.revision!=request.revision:raise ApiError('conflict','Fold session changed; refresh before acting')
    data=copy.deepcopy(row.payload)
    try:change(data)
    except ValueError as exc:raise ApiError('unprocessable_entity','Fold action violates its session contract') from exc
    runtime().event(data,'native_teacher_mutation',actor=principal.principal_id,operation_id=request.operation_id,route=route)
    data['revision']=request.revision+1
    result=db.execute(update(FoldSession).where(FoldSession.id==sid,FoldSession.revision==request.revision)
                      .values(payload=data,revision=request.revision+1).execution_options(synchronize_session=False))
    if result.rowcount!=1:raise ApiError('conflict','Fold session changed; refresh before acting')
    if old:old.response=data
    else:db.add(FoldOperation(session_id=sid,operation_id=request.operation_id,request_sha256=digest,response=data))
    db.flush()
    return read_public(db,principal,row,store,payload=data)


def source_bytes(db,principal,project_id,asset_id,store):
    asset=scoped_asset(db,principal,asset_id)
    if asset.project_id!=project_id or asset.status!='active':raise ApiError('not_found','Fold source unavailable')
    if asset.origin not in SYNTHETIC_ORIGINS:
        # Native real/classroom assets cannot enter a new activity by virtue
        # of an existing asset's approval. No new Fold scope is authorized.
        raise ApiError('unprocessable_entity','Real-source Fold activity scope requires research lead confirmation')
    if asset.kind!='image' or asset.size_bytes>4_000_000:raise ApiError('unprocessable_entity','Fold reference accepts bounded still images only')
    try:content=store.open(asset.stored_key)
    except OSError as exc:raise ApiError('unavailable','Stored source unavailable',retryable=True) from exc
    if hashlib.sha256(content).hexdigest()!=asset.sha256:raise ApiError('unavailable','Stored source integrity failed',retryable=False)
    try:
        with Image.open(BytesIO(content)) as image:
            if image.format not in {'PNG','JPEG','WEBP'} or getattr(image,'n_frames',1)!=1 or image.width*image.height>12_000_000:
                raise ValueError('unsupported still image')
            size=image.size;image.verify()
    except (OSError,ValueError,UnidentifiedImageError,Image.DecompressionBombError) as exc:
        raise ApiError('unprocessable_entity','Invalid Fold image source') from exc
    if (asset.width_px is not None and asset.width_px!=size[0]) or (asset.height_px is not None and asset.height_px!=size[1]):
        raise ApiError('unavailable','Stored source extent failed',retryable=False)
    # Native storage addresses immutable bytes by digest. A new Asset ID for
    # old bytes is an alias, not evidence of a new capture. Keep the earliest
    # upload within this scoped project, including tombstoned aliases.
    earliest=db.scalar(select(func.min(Asset.created_at)).where(Asset.project_id==project_id,Asset.sha256==asset.sha256))
    return asset,content,size,as_aware(earliest)


def validated_source(db, principal, project_id, source, store):
    asset, content, size, first_uploaded_at = source_bytes(
        db, principal, project_id, source['native_asset_id'], store)
    expected = {'source_sha256': asset.sha256, 'sha256': asset.sha256, 'origin': asset.origin,
                'native_checkpoint_id': asset.checkpoint_id,
                'native_design_version_id': asset.design_version_id,
                'native_privacy_class': asset.privacy_class,
                'native_consent_use_flags': list(asset.consent_use_flags or []),
                'native_uploaded_at': as_aware(asset.created_at).isoformat(),
                'native_source_first_uploaded_at': first_uploaded_at.isoformat(),
                'capture_time': 'unknown', 'modality': 'image', 'width': size[0], 'height': size[1]}
    if any(source.get(key) != value for key, value in expected.items()):
        raise ApiError('unavailable', 'Fold source provenance changed', retryable=False)
    return asset, content


def validate_sources(db, principal, row, store):
    if row.payload.get('native_project_id') != row.project_id:
        raise ApiError('unavailable', 'Fold project provenance changed', retryable=False)
    # Even an early replay rechecks every final source under current authority.
    for source in row.payload['evidence']:
        if source.get('native_asset_id'):
            validated_source(db, principal, row.project_id, source, store)


def attach(data,asset,size,note,selection_id,first_uploaded_at):
    engine=runtime()
    uploaded_at=as_aware(asset.created_at)
    if selection_id:
        selected=next((s for s in data.get('selections',[]) if s['id']==selection_id),None)
        if not selected or not selected.get('enacted_at'):
            raise ValueError('Subsequent source requires a reported enactment')
        if first_uploaded_at < datetime.fromisoformat(selected['enacted_at']):
            raise ValueError('Previously uploaded sources cannot represent subsequent evidence')
    source={'id':new_id('fold_evidence'),'title':'Making Visible source','text':note or 'Authorized native synthetic source; review only.',
            'origin':asset.origin,'native_asset_id':asset.id,'native_checkpoint_id':asset.checkpoint_id,
            'native_design_version_id':asset.design_version_id,'native_privacy_class':asset.privacy_class,
            'native_consent_use_flags':list(asset.consent_use_flags or []),'source_sha256':asset.sha256,
            'rights_confirmed':True,
            'native_uploaded_at':uploaded_at.isoformat(),'capture_time':'unknown',
            'native_source_first_uploaded_at':first_uploaded_at.isoformat(),
            'sequence_basis':'upload_after_teacher_enactment_report' if selection_id else 'source_link_only',
            'sha256':asset.sha256,'modality':'image','width':size[0],'height':size[1],
            'method':'Native scoped Asset adapter; no mechanism/fold semantic conversion','analysis':'not_run','at':engine.stamp()}
    data['evidence'].append(source)
    engine.link_subsequent_evidence(data,selection_id,source['id'])
    receipt=engine.event(data,'native_evidence_linked',evidence_id=source['id'],asset_id=asset.id,selection_id=selection_id)
    record_native_source(data,source,receipt['at'])
    engine.refresh(data)


def _observation_source(db,principal,row,evidence,store):
    if not evidence or not evidence.get('native_asset_id'):
        raise ApiError('not_found','Permitted native Fold image source unavailable')
    asset,content,size,_=source_bytes(db,principal,row.project_id,evidence['native_asset_id'],store)
    expected={'source_sha256':asset.sha256,'sha256':asset.sha256,'origin':asset.origin,
        'native_checkpoint_id':asset.checkpoint_id,'native_design_version_id':asset.design_version_id,
        'native_privacy_class':asset.privacy_class,'native_consent_use_flags':list(asset.consent_use_flags or []),
        'width':size[0],'height':size[1]}
    if any(evidence.get(key)!=value for key,value in expected.items()):
        raise ApiError('unavailable','Fold source lineage changed',retryable=False)
    return content,size


def read_public(db,principal,row,store,*,payload=None):
    # Retained model text cannot bypass a source withdrawal or replacement.
    payload=row.payload if payload is None else payload
    for observation in payload.get('observations',[]):
        source=next((e for e in payload['evidence'] if e['id']==observation['source_id']),None)
        _observation_source(db,principal,row,source,store)
        if observation['result']['source_sha256']!=source['source_sha256']:
            raise ApiError('unavailable','Fold observation source lineage changed',retryable=False)
    return public(payload)


def _prepare_observation(db,principal,sid,request,store):
    row=scoped(db,principal,sid,CAPABILITY_MANAGE)
    scoped(db,principal,sid,CAPABILITY_ANALYZE)
    if row.payload['mode']!='review':raise ApiError('unprocessable_entity','Fold local observation requires review mode')
    evidence=next((e for e in row.payload['evidence'] if e['id']==request.evidence_id),None)
    content,size=_observation_source(db,principal,row,evidence,store)
    if request.source_sha256!=evidence['source_sha256']:raise ApiError('conflict','Fold source changed; refresh before analysis')
    if not request.permission_confirmed or not evidence.get('rights_confirmed'):
        raise ApiError('unprocessable_entity','Confirm separate permission for local image analysis')
