@dataclass
class CallAccounting:
    generation_attempts: int = 0
    actual_vlm_calls: int = 0
    on_change: Callable[[dict], None] | None = field(default=None, repr=False)

    def __post_init__(self) -> None:
        self._lock = Lock()

    def attempted(self) -> None:
        with self._lock:
            self.generation_attempts += 1
            if self.on_change is not None:
                self.on_change(self._snapshot())

    def executed(self) -> None:
        with self._lock:
            self.actual_vlm_calls += 1
            if self.on_change is not None:
                self.on_change(self._snapshot())

    def _snapshot(self) -> dict:
        return {
            "generation_attempts": self.generation_attempts,
            "actual_vlm_calls": self.actual_vlm_calls,
            "basis": _COUNTER_BASIS,
            "execution_success_inferred": False,
        }

    def as_dict(self) -> dict:
        with self._lock:
            return self._snapshot()


class _CountedModel:
    """Delegate unchanged calls while recording actual model.generate entry."""
    def __init__(self, model, accounting: CallAccounting):
        self._wrapped = model
        self._accounting = accounting

    def __getattr__(self, name):
        return getattr(self._wrapped, name)

    def generate(self, *args, **kwargs):
        self._accounting.executed()
        return self._wrapped.generate(*args, **kwargs)


def accounted_vlm(weights_dir: Path, accounting: CallAccounting, *, deadline_s: float = 300.0):
    """Build a local adapter owner; loading still happens only on opt-in call."""
    from packages.perception.visual.qwen_vl import LocalVlm

    class CountedLocalVlm(LocalVlm):
        def load(self):
            super().load()
            if self._model is not None and not isinstance(self._model, _CountedModel):
                self._model = _CountedModel(self._model, accounting)

        def generate(self, *args, **kwargs):
            accounting.attempted()
            return super().generate(*args, **kwargs)

    return CountedLocalVlm(weights_dir, inference_timeout_s=deadline_s)


def accounted_renderer(renderer_class, accounting: CallAccounting, *, weights_dir: Path,
                       deadline_s: float = DEFAULT_DEADLINE_S):
    """Keep the renderer's validation/repair policy with counted local calls."""
    class CountedRenderer(renderer_class):
        def _build_engine(self):
            return accounted_vlm(weights_dir, accounting, deadline_s=self._deadline_s)

