def _group_has_residents(pgid: int, *, timeout_s: float = 1.0) -> bool | None:
    """Read only process identity/state; zombies cannot retain a loaded model."""
    try:
        listing = subprocess.run(["ps", "-axo", "pid=,pgid=,stat="], capture_output=True,
                                 text=True, timeout=timeout_s, check=True)
