            return None  # an all-process snapshot must include at least ps
        for line in listing.stdout.splitlines():
            parts = line.split()
            if len(parts) != 3:
                return None
            _pid, group_id = int(parts[0]), int(parts[1])
            if group_id == pgid and not parts[2].startswith("Z"):
                return True
        return False
    except (OSError, ValueError, subprocess.SubprocessError):
        return None


def _stop_owned_group(process: subprocess.Popen, *, receipt: dict | None = None) -> tuple[bool, int | None]:
    """Only this Popen owns this session/PGID; signal BEFORE reaping its leader.

    The leader remains alive awaiting parent acknowledgement after a receipt.
    Even an unexpected exit leaves its PID unreaped, preventing PID reuse while
    its descendants are signalled. No discovered or unrelated PID is killed.
    """
    for sig in (signal.SIGTERM, signal.SIGKILL):
        try:
            os.killpg(process.pid, sig)
        except ProcessLookupError:
            pass
        except PermissionError:
            # Darwin reports EPERM for a group containing only zombies. Do
            # not interpret this as proof of exit: wait and independently
            # verify below. A live or unverifiable group retains the lease.
            pass
        if sig == signal.SIGTERM:
            time.sleep(0.025)
    try:
        exit_code = process.wait(timeout=2.0)
    except subprocess.TimeoutExpired:
        if receipt is not None:
            receipt.update(cleanup_observations=0, cleanup_unreadable_observations=0,
                cleanup_refusal_reason="owned_leader_not_reaped")
