    verification_started = time.monotonic()
    until = verification_started + _CLEANUP_VERIFICATION_S
    observations = unreadable = 0
    residents = None
    while True:
        remaining = until - time.monotonic()
        if remaining <= 0:
            verified = False
            break
        residents = _group_has_residents(process.pid, timeout_s=min(_PS_SNAPSHOT_TIMEOUT_S, remaining))
        observations += 1
        unreadable += residents is None
        if residents is False:
            verified = True
            break
        # Retry only OS proof acquisition within this cleanup window. The
        # identity has been reaped: never signal it again, even if a snapshot
        # is unreadable. No snapshot is not evidence of an empty group.
        time.sleep(min(0.02, max(0, until - time.monotonic())))
    if receipt is not None:
        receipt.update(cleanup_observations=observations, cleanup_unreadable_observations=unreadable,
            cleanup_verification_s=round(time.monotonic() - verification_started, 6),
            cleanup_refusal_reason=None if verified else
                "process_snapshot_unreadable" if residents is None else "group_still_resident")
