                chunk = os.read(process.stdout.fileno(), 65_536)
                if not chunk:
                    error, stage = "child_exited_without_receipt", "model_execution"
                    break
                receipt["response_bytes"] += len(chunk)
                if receipt["response_bytes"] > MAX_RECEIPT_BYTES + MAX_EVENT_BYTES * MAX_EVENTS:
                    error, stage = "response_byte_budget_exceeded", "output_validation"
                    break
                buffer.extend(chunk)
                if b"\n" not in buffer and len(buffer) > MAX_RECEIPT_BYTES:
                    error, stage = "response_byte_budget_exceeded", "output_validation"
                    break
                while b"\n" in buffer and error is None:
                    line, _sep, tail = buffer.partition(b"\n")
                    buffer = bytearray(tail)
                    receipt["ipc_events"] += 1
                    if len(line) > MAX_RECEIPT_BYTES or receipt["ipc_events"] > MAX_EVENTS:
                        error, stage = "ipc_budget_exceeded", "output_validation"
                        break
                    try:
                        message = json.loads(line)
                    except (ValueError, UnicodeError):
                        error, stage = "invalid_child_receipt", "output_validation"
                        break
                    if not isinstance(message, dict):
                        error, stage = "invalid_child_receipt", "output_validation"
                        break
                    event = message.get("event")
                    if event not in ("result", "error") and len(line) > MAX_EVENT_BYTES:
                        error, stage = "ipc_event_byte_budget_exceeded", "output_validation"
                        break
                    if event == "started" and not child_started:
                        child_started = message.get("pid") == process.pid and message.get("pgid") == process.pid
                        if not child_started:
                            error, stage = "child_ownership_invalid", "output_validation"
                    elif event == "counts" and child_started and _valid_counts(message.get("counts"), counts):
                        counts = message["counts"]
                    elif event in ("result", "error") and child_started and _valid_counts(message.get("counts"), counts) and message["counts"] == counts:
                        terminal = True
                        if event == "result" and isinstance(message.get("result"), dict):
                            result = message["result"]
                        elif event == "error" and message.get("code") in (
                            "prerequisites_unavailable", "model_execution_failed", "response_byte_budget_exceeded"):
                            error, error_type = message["code"], message.get("error_type")
                            stage = message.get("failure_stage", "model_execution")
                        else:
                            error, stage = "invalid_child_receipt", "output_validation"
                    else:
                        error, stage = "invalid_child_receipt", "output_validation"
                    if terminal:
                        break
    except (OSError, ValueError, subprocess.SubprocessError) as exc:
        error, error_type, stage = "model_process_unavailable", type(exc).__name__, "model_execution"
    finally:
        selector.close()
        if process is not None:
            # Do not call poll/wait before this group cleanup: even a failed
            # child retains its PID identity until all signals have been sent.
            cleanup_verified, exit_code = _stop_owned_group(process, receipt=receipt)
            receipt.update(cleanup_verified=cleanup_verified, exit_code=exit_code,
                cleanup_method="owned_group_SIGTERM_SIGKILL_then_wait_and_residency_check")
            for pipe in (process.stdin, process.stdout):
                pipe.close()
        else:
            receipt["cleanup_verified"] = True
        # A cooperative adapter can return while its model thread still runs.
        # Read shared counters only after the OS confirms no live group member
        # can add a late entry. IPC alone cannot close that terminal-receipt race.
        if counter_map is not None and cleanup_verified:
            attempts, actual = struct.unpack("!QQ", counter_map[:16])
            if attempts >= counts["generation_attempts"] and actual >= counts["actual_vlm_calls"] and actual <= attempts:
                counts = {**counts, "generation_attempts": attempts, "actual_vlm_calls": actual}
                if attempts > MAX_GENERATION_ATTEMPTS:
                    error, stage, result = "generation_budget_exceeded", "model_execution", None
            else:
                error, stage, result = "invalid_shared_accounting", "output_validation", None
        receipt["counts_finality"] = "verified_after_owned_group_exit" if cleanup_verified else "observed_lower_bound_cleanup_unverified"
        if counter_map is not None:
            counter_map.close()
        if counter_file is not None:
            counter_file.close()
        if cleanup_verified:
            os.close(lease_fd)  # no LOCK_UN: the child shares this description
            receipt["lease_released"] = True
        else:
            _defer_lease_release(process, lease_fd)
            receipt["lease_release"] = "deferred_until_cleanup_verified"
            error, stage, result = "process_cleanup_unverified", "model_execution", None
    return finish()


def _worker_main(lease_fd: int, parent_pid: int, counter_fd: int, test_executor: str | None) -> None:
    # Inheriting the flock description keeps the lease locked if the parent
    # dies before it can clean up this resident child.
    os.fstat(lease_fd)
    counter_map = mmap.mmap(counter_fd, 16)
    own_pgid = os.getpid()
    if os.getpgrp() != own_pgid:
        os._exit(74)
    def watch_parent():
        while True:
            if os.getppid() != parent_pid:
                os.killpg(own_pgid, signal.SIGKILL)
                return
            time.sleep(0.1)
    Thread(target=watch_parent, name="mv-model-parent-liveness", daemon=True).start()
    ipc_fd = os.dup(sys.stdout.fileno())
    with open(os.devnull, "wb") as quiet:
        os.dup2(quiet.fileno(), sys.stdout.fileno())
    output_lock = Lock()
    events = 0
    def send(message: dict):
        nonlocal events
        raw = _json_bytes(message) + b"\n"
        limit = MAX_RECEIPT_BYTES if message.get("event") in ("result", "error") else MAX_EVENT_BYTES
        if len(raw) > limit:
            raise ValueError("response_byte_budget_exceeded")
        with output_lock:
            events += 1
            if events > MAX_EVENTS:
                raise ValueError("ipc_budget_exceeded")
            view = memoryview(raw)
            while view:
                view = view[os.write(ipc_fd, view):]
    send({"event": "started", "pid": os.getpid(), "pgid": os.getpgrp()})
    def record_counts(counts):
        counter_map[:16] = struct.pack("!QQ", counts["generation_attempts"], counts["actual_vlm_calls"])
        send({"event": "counts", "counts": counts})
    accounting = CallAccounting(on_change=record_counts)
    try:
        raw = sys.stdin.buffer.readline(MAX_REQUEST_BYTES + 1)
        if len(raw) > MAX_REQUEST_BYTES or not raw.endswith(b"\n"):
            raise ValueError("request_byte_budget_exceeded")
        request = json.loads(raw)
        if request["kind"] not in _TASKS or not isinstance(request["payload"], dict):
            raise ValueError("invalid_task")
        executor = _run_model_task
        if test_executor is not None:
            module, name = test_executor.split(":", 1)
            executor = getattr(importlib.import_module(module), name)
        result = executor(request["kind"], request["payload"], accounting, request["deadline_s"])
        send({"event": "result", "result": result, "counts": accounting.as_dict()})
    except Exception as exc:
        stage = getattr(exc, "stage", None)
        if stage not in ("preprocessing", "model_execution", "output_validation"):
            stage = "preprocessing" if str(exc).startswith("preprocessing:") else "model_execution"
        code = ("prerequisites_unavailable" if isinstance(exc, (NotImplementedError, _PrerequisitesUnavailable))
                else "response_byte_budget_exceeded" if str(exc) == "response_byte_budget_exceeded"
                else "model_execution_failed")
        send({"event": "error", "code": code, "error_type": type(exc).__name__,
              "failure_stage": stage, "counts": accounting.as_dict()})
    # Keep the leader and its process-group identity alive until parent group
    # cleanup. This also prevents a generated receipt from releasing residency
    # while a cooperative adapter's timed-out thread is still running.
    sys.stdin.buffer.read(1)
    os._exit(0)


if __name__ == "__main__":
    if len(sys.argv) not in (5, 7) or sys.argv[1] != "--worker":
        raise SystemExit(64)
    test_executor = sys.argv[6] if len(sys.argv) == 7 and sys.argv[5] == "--test-executor" else None
    _worker_main(int(sys.argv[2]), int(sys.argv[3]), int(sys.argv[4]), test_executor)

