"""Job dispatch to Redis/RQ with a typed unavailable result.

When Redis is not configured or reachable the job record still exists in
PostgreSQL state (authoritative); dispatch reports ``unavailable`` honestly
instead of pretending the job is running.
"""
from __future__ import annotations

from dataclasses import dataclass

from ..config import Settings, get_settings


@dataclass(frozen=True)
class DispatchResult:
    status: str  # "enqueued" | "unavailable"
    reason: str | None = None
    retryable: bool = False

    def as_dict(self) -> dict[str, object]:
        return {
            "status": self.status,
            "reason": self.reason,
            "retryable": self.retryable,
        }


def enqueue_job(job_ref: str, settings: Settings | None = None) -> DispatchResult:
    """Enqueue analysis work (``<job_id>``) or a purge (``purge:<project_id>``)."""
    settings = settings or get_settings()
    if not settings.redis_url:
        return DispatchResult(
            status="unavailable",
            reason="redis_not_configured",
            retryable=True,
        )
    try:
        from redis import Redis
        from rq import Queue

        connection = Redis.from_url(settings.redis_url, socket_connect_timeout=2)
        connection.ping()
    except Exception as exc:  # redis/ConnectionError and handshake errors
        return DispatchResult(
            status="unavailable",
            reason=f"redis_unreachable:{type(exc).__name__}",
            retryable=True,
        )
    queue = Queue("mv-analysis", connection=connection)
    if job_ref.startswith("purge:"):
        queue.enqueue(
            "services.worker.jobs.purge_project",
            {"project_id": job_ref[len("purge:") :]},
            job_timeout=600,
        )
    else:
        queue.enqueue(
            "services.worker.jobs.execute_processing_job",
            job_ref,
            job_timeout=600,
            result_ttl=86400,
        )
    return DispatchResult(status="enqueued")

