"""Native study provenance and privacy boundaries; no model simulation.

The counterbalance/state machine is separately implemented in study_protocol.
This adapter validates the private registry, actual scoped corpus and native
answer records before a client event can establish a frozen response.
"""
from __future__ import annotations

import copy
import hashlib
import json
import math
import re
from decimal import Decimal
from datetime import datetime

from sqlalchemy import select

from ..authz import scoped_answer, scoped_project
from ..db import as_aware, utcnow
from ..errors import ApiError
from ..models import AnswerRequest, Asset, StudyFrozenAnswer
from ..security import CAPABILITY_READ
from . import snapshots, study_protocol as protocol
from research.study.artifacts import StudyRelease
from research.study.readiness import participant_stimulus, validate_release_manifest

CONFIG_SCHEMA = 'mv.study.server-contract/1'
COMPILED_CONFIG_SCHEMA = 'mv.study.compiled-contract/1'
_HASH = re.compile(r'^[0-9a-f]{64}$')
_EMAIL = re.compile(r'\b[^\s@]+@[^\s@]+\.[^\s@]+\b')
_OPAQUE_ID = re.compile(r'^[A-Za-z0-9_-]{1,120}$')
_FORBIDDEN = ('data:image', 'data:video', 'data:audio', 'base64',
              'raw_viewer', 'flat_assistant', 'making_visible', 'condition_permutation')
_FIELDS = {
    'session_started': {'planned_participants'}, 'case_started': {'scenario_number'},
    'evidence_viewed': {'count', 'source'}, 'evidence_rendered': {'count', 'source'},
    'evidence_opened': {'observation_id', 'asset_id', 'evidence_id'},
    'evidence_cited': {'observation_id', 'asset_id', 'evidence_id', 'claim_id', 'span'},
    'citation_selected': {'observation_id', 'asset_id', 'evidence_id', 'claim_id', 'span'},
    'video_played': {'asset_id', 'at_ms'}, 'video_seeked': {'asset_id', 'at_ms'},
    'guidance_frozen': {'answer_id', 'mode', 'content_hash'},
    'guidance_replayed': {'answer_id'}, 'condition_unavailable': {'reason'},
    'question_edited': {'scenario_number', 'text'}, 'response_describe_evidence': {'text'},
    'intervention_selected': {'intervention'}, 'response_what_would_change': {'text'},
    'confidence_rated': {'confidence'}, 'case_completed': {'scenario_number'},
    'case_paused': {'reason'}, 'case_resumed': {'reason'}, 'intentionally_waited': {'reason'},
    'export_generated': {'format'}, 'withdrawal_requested': {},
}


def canonical(value):
    # Same recursive key sorting / compact UTF-8 serialization used by the
    # TypeScript hashFrozenContent function, for native JSON-safe values.
    def encode(node):
        if node is None:return 'null'
        if node is True:return 'true'
        if node is False:return 'false'
        if isinstance(node,str):return json.dumps(node,ensure_ascii=False)
        if isinstance(node,dict):
            return '{'+','.join(encode(k)+':'+encode(node[k]) for k in sorted(node,key=lambda k:k.encode('utf-16-be')))+'}'
        if isinstance(node,list):return '['+','.join(encode(v) for v in node)+']'
        if type(node) is int and abs(node)<=2**53-1:return str(node)
        if type(node) in {int,float}:
            try:number=float(node)
            except OverflowError as exc:raise ValueError('out-of-range JSON number') from exc
            if not math.isfinite(number):raise ValueError('non-finite JSON number')
            if number==0:return '0'
            raw=repr(number).lower()
            if 1e-6<=abs(number)<1e21:
                fixed=format(Decimal(raw),'f')
                return fixed.rstrip('0').rstrip('.') if '.' in fixed else fixed
            mantissa,exponent=raw.split('e')
            if mantissa.endswith('.0'):mantissa=mantissa[:-2]
            exp=int(exponent)
            return mantissa+'e'+('+' if exp>=0 else '-')+str(abs(exp))
        raise ValueError('unsupported JSON value')
    return encode(value)


def digest(value):
    return hashlib.sha256(canonical(value).encode()).hexdigest()


def private_config(value, *, release_manifest=None, release_artifact_hash=None):
    if (release_manifest is not None or release_artifact_hash is not None) and (not isinstance(value,dict) or value.get('schema')!=COMPILED_CONFIG_SCHEMA):
        raise ApiError('unavailable','Compiled releases require a compiled protocol registry',retryable=False)
    if isinstance(value, dict) and value.get('schema') == COMPILED_CONFIG_SCHEMA:
        result=validate_release_manifest(release_manifest,release_artifact_hash)
        if not result.ready or not release_artifact_hash:
            raise ApiError('unavailable','Compiled study release is not ready for participant admission',retryable=False)
        if set(value)!={'schema','synthetic','condition_permutation','scenarios','participant_use'} or value.get('synthetic') is not False or value.get('participant_use')!='approved_main_study':
            raise ApiError('unavailable','Compiled study activity scope is unavailable',retryable=False)
        try:protocol.server_assignment(1,condition_permutation=value['condition_permutation'])
        except protocol.StudyProtocolError as exc:
            raise ApiError('unavailable','Study condition registry is invalid',retryable=False) from exc
        release=StudyRelease.model_validate(release_manifest['release'])
        expected=[]
        for case in release.cases:
            mv=next(s for s in release.stimuli if s.case_index==case.case_index and s.condition=='making_visible')
            expected.append({'caseIndex':case.case_index,'projectId':case.project_id,
                'snapshotHash':mv.input.value()['snapshot_hash'],
                'assetHashes':{s.asset_id:s.sha256 for s in case.sources if s.asset_id}})
        if not same_json(value['scenarios'],expected):
            raise ApiError('unavailable','Compiled study source registry is inconsistent',retryable=False)
        return copy.deepcopy(value)
    if not isinstance(value, dict) or set(value) != {'schema','synthetic','condition_permutation','scenarios','participant_use'}:
        raise ApiError('unavailable','Study protocol registry requires explicit configuration',retryable=False)
    if value['schema'] != CONFIG_SCHEMA or value['synthetic'] is not True or value['participant_use'] != 'software_rehearsal_only':
        raise ApiError('unavailable','Study activity scope is unavailable',retryable=False)
    try:protocol.server_assignment(1,condition_permutation=value['condition_permutation'])
    except protocol.StudyProtocolError as exc:
        raise ApiError('unavailable','Study condition registry is invalid',retryable=False) from exc
    rows=value['scenarios']
    if not isinstance(rows,list) or len(rows)!=9:raise ApiError('unavailable','Study corpus registry is incomplete',retryable=False)
    seen=set()
    for row in rows:
        if not isinstance(row,dict) or set(row)!={'caseIndex','projectId','snapshotHash','assetHashes'}:
            raise ApiError('unavailable','Study corpus registry is invalid',retryable=False)
        if type(row['caseIndex']) is not int or not 0<=row['caseIndex']<9 or row['caseIndex'] in seen:
            raise ApiError('unavailable','Study corpus registry is invalid',retryable=False)
        seen.add(row['caseIndex'])
        if not isinstance(row['projectId'],str) or not row['projectId'] or not _HASH.fullmatch(str(row['snapshotHash'])):
            raise ApiError('unavailable','Study corpus registry is invalid',retryable=False)
        if not isinstance(row['assetHashes'],dict) or any(not isinstance(k,str) or not _HASH.fullmatch(str(v)) for k,v in row['assetHashes'].items()):
            raise ApiError('unavailable','Study source registry is invalid',retryable=False)
    return copy.deepcopy(value)


def session_config(study_session):
    config = private_config(study_session.protocol_config,
        release_manifest=study_session.release_manifest,
        release_artifact_hash=study_session.release_artifact_hash)
    if compiled(config):
        release=study_session.release_manifest['release']
        if release['label']!=study_session.pack_label or release['protocol_version']!=study_session.protocol_version:
            raise ApiError('unavailable','Stored study release identity requires review',retryable=False)
    return config


def compiled(config):
    return config.get('schema') == COMPILED_CONFIG_SCHEMA


def corpus_case(db, principal, config, case_index):
    item=next(row for row in config['scenarios'] if row['caseIndex']==case_index)
    project=scoped_project(db,principal,item['projectId'],CAPABILITY_READ)
    if compiled(config):
        _compiled_sources(db,project,item)
        return project,item
    if snapshots.current_snapshot_hash(db,project.id)!=item['snapshotHash']:
        raise ApiError('unavailable','Study scenario changed since registration',retryable=False)
    assets=list(db.scalars(select(Asset).where(Asset.project_id==project.id,Asset.status=='active')))
    if {a.id:a.sha256 for a in assets}!=item['assetHashes'] or any(not a.origin.startswith('synthetic_') for a in assets):
        raise ApiError('unavailable','Study sources changed or are outside synthetic scope',retryable=False)
    return project,item


def _compiled_sources(db,project,pin):
    from .consent import require_asset_use
    for asset_id,source_hash in pin['assetHashes'].items():
        asset=db.get(Asset,asset_id)
        if (asset is None or asset.project_id!=project.id or asset.status!='active'
                or asset.sha256!=source_hash or asset.origin!='approved_real'
                or not {'analysis','teaching_review','research_export'} <= set(asset.consent_use_flags)):
            raise ApiError('unavailable','Compiled study source is no longer authorized',retryable=False)
        for use in ('analysis','teaching_review','research_export'):
            require_asset_use(db,asset,use)


def corpus_read_scope(db, principal, config):
    """Reauthorize historical sources without requiring the live snapshot.

    New observations can make an immutable answer stale without changing its
    recorded content. Deleted/revoked projects or retracted pinned assets
    must still stop disclosure of that content.
    """
    for pin in config['scenarios']:
        project=scoped_project(db,principal,pin['projectId'],CAPABILITY_READ)
        if compiled(config):
            _compiled_sources(db,project,pin)
            continue
        for asset_id,source_hash in pin['assetHashes'].items():
            asset=db.get(Asset,asset_id)
            if (asset is None or asset.project_id!=project.id or asset.status!='active' or
                asset.sha256!=source_hash or not asset.origin.startswith('synthetic_')):
                raise ApiError('unavailable','Study source is no longer available',retryable=False)


def public_pack(config,label):
    return {'label':label,'synthetic':config['synthetic'],'scenarios':[
        {'caseIndex':r['caseIndex'],'label':f"Scenario {r['caseIndex']+1}",'projectId':r['projectId']}
            for r in sorted(config['scenarios'],key=lambda r:r['caseIndex'])]}


def compiled_stimulus(db,principal,study_session,case_index):
    config=session_config(study_session)
    if not compiled(config):
        raise ApiError('unavailable','This software rehearsal has no compiled comparative treatment',retryable=False)
    if study_session.status=='withdrawn':
        raise ApiError('not_found','Study content unavailable in your scope')
    if type(case_index) is not int or not 0<=case_index<9:
        raise ApiError('not_found','No study case in your scope')
    corpus_case(db,principal,config,case_index)
    case=next(c for c in study_session.counterbalance_arm['cases'] if c['caseIndex']==case_index)
    condition=next(name for name,label in config['condition_permutation'].items() if label==case['blindedConditionId'])
    stimulus=participant_stimulus(study_session.release_manifest['release'],case_index,condition,case['blindedConditionId'])
    # A compiled flat output is not a native GuidanceAnswer. The stable opaque
    # reference identifies its own immutable artifact, never borrows an MV id.
    content=stimulus['content']
    answer_id=content.get('answer_id') if condition=='making_visible' else 'stim_'+stimulus['stimulus_hash'][:32]
    mode='local_model' if condition=='flat_assistant' else 'template'
    return {**stimulus,'answer_id':answer_id,'mode':mode}


def verify_compiled_freeze(db,principal,study_session,item):
    stimulus=compiled_stimulus(db,principal,study_session,item.caseIndex)
    if stimulus['display_kind']=='sources':
        raise ApiError('unprocessable_entity','Raw evidence does not include generated guidance')
    if not same_json(item.payload,{'answer_id':stimulus['answer_id'],'mode':stimulus['mode'],
                                  'content_hash':stimulus['content_hash']}):
        raise ApiError('unprocessable_entity','Study exposure does not match the locked stimulus')
    if privacy_problem(stimulus['content'],byte_limit=131072):
        raise ApiError('unavailable','Compiled study content requires privacy review',retryable=False)


def compiled_frozen_answers(db,principal,study_session,history,state):
    result={}
    events={event['id']:event for event in history}
    for case in state['cases']:
        frozen=case['frozenGuidance']
        if not frozen:
            continue
        stimulus=compiled_stimulus(db,principal,study_session,case['caseIndex'])
        event=events[frozen['eventId']]
        from types import SimpleNamespace
        verify_compiled_freeze(db,principal,study_session,
            SimpleNamespace(caseIndex=case['caseIndex'],payload=event['payload']))
        result[str(case['caseIndex'])]={'caseIndex':case['caseIndex'],'answerId':stimulus['answer_id'],
            'mode':stimulus['mode'],'question':stimulus['question'],'content':stimulus['content'],
            'contentHash':stimulus['content_hash'],'frozenAtIso':event['atIso']}
    return result


def privacy_problem(value, *, byte_limit=4096):
    def safe(node,depth=0):
        if depth>12:return False
        if isinstance(node,dict):return all(isinstance(k,str) and safe(k,depth+1) and safe(v,depth+1) for k,v in node.items())
        if isinstance(node,list):return all(safe(v,depth+1) for v in node)
        if isinstance(node,str):
            try:node.encode('utf-8')
            except UnicodeEncodeError:return False
            return not _EMAIL.search(node)
        if type(node) in {int,float}:
            try:return math.isfinite(float(node))
            except OverflowError:return False
        return node is None or type(node) is bool
    if not safe(value):return 'unsafe_payload'
    try:raw=canonical(value)
    except (ValueError,TypeError,OverflowError):return 'unsafe_payload'
    if len(raw.encode())>byte_limit:return 'payload_too_large'
    if any(token in raw.lower() for token in _FORBIDDEN):return 'private_or_media_payload'
    return None


def payload_problem(event_type,payload):
    if not isinstance(payload,dict):return 'invalid_event_payload'
    if set(payload)-_FIELDS.get(event_type,set()):return 'unexpected_payload_fields'
    problem=privacy_problem(payload)
    if problem:return problem
    for key,value in payload.items():
        if key in {'count','at_ms','planned_participants','scenario_number','confidence'}:
            if type(value) is not int or not 0<=value<=2**53-1:return 'invalid_payload_value'
            if key=='planned_participants' and value!=18:return 'invalid_payload_value'
            if key=='scenario_number' and not 1<=value<=9:return 'invalid_payload_value'
            if key=='confidence' and not 1<=value<=5:return 'invalid_confidence'
        elif key in {'answer_id','observation_id','asset_id','evidence_id','claim_id'}:
            if not isinstance(value,str) or _OPAQUE_ID.fullmatch(value) is None:return 'invalid_payload_id'
        elif key=='content_hash':
            if not isinstance(value,str) or _HASH.fullmatch(value) is None:return 'invalid_payload_hash'
        elif key!='span' and not isinstance(value,str):return 'invalid_payload_value'
    if 'span' in payload and payload['span'] is not None:
        span=payload['span']
        if not isinstance(span,dict) or set(span)!={'start_ms','end_ms'} or any(type(v) is not int for v in span.values()) or not 0<=span['start_ms']<span['end_ms']<=2**53-1:
            return 'invalid_source_span'
    return None


def event_id_problem(event_id):
    return None if isinstance(event_id,str) and _OPAQUE_ID.fullmatch(event_id) else 'invalid_event_id'


def typed_json(value):
    """Exact retry identity preserves JSON boolean/integer/float distinctions."""
    return json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False)


def same_json(left,right):
    try:return typed_json(left)==typed_json(right)
    except (ValueError,TypeError,OverflowError):return False


def verified_frozen_answers(db,principal,study_session,history,state):
    """Bind each durable freeze event to exactly one native immutable answer."""
    rows=list(db.scalars(select(StudyFrozenAnswer).where(StudyFrozenAnswer.session_id==study_session.id)))
    expected={case['caseIndex']:case['frozenGuidance'] for case in state['cases'] if case['frozenGuidance']}
    if {row.case_index for row in rows}!=set(expected):
        raise ApiError('unavailable','Stored study answer requires integrity review',retryable=False)
    events={event['id']:event for event in history}
    fields={'caseIndex','answerId','mode','question','content','contentHash','frozenAtIso'}
    for row in rows:
        wrapper=row.payload
        pin=next(item for item in study_session.protocol_config['scenarios'] if item['caseIndex']==row.case_index)
        frozen=expected[row.case_index]
        event=events[frozen['eventId']]
        invalid=(not isinstance(wrapper,dict) or set(wrapper)!=fields or
            privacy_problem(wrapper,byte_limit=131072) or
            type(wrapper.get('caseIndex')) is not int or wrapper.get('caseIndex')!=row.case_index or
            wrapper.get('answerId')!=row.answer_id or row.answer_id!=frozen['answerId'] or
            wrapper.get('contentHash')!=row.content_hash or row.content_hash!=frozen['contentHash'] or
            wrapper.get('mode')!=event['payload']['mode'] or
            not isinstance(wrapper.get('content'),dict) or
            set(wrapper.get('content',{}))!={'question','payload','provenance'})
        if not invalid:
            try:
                timestamp=datetime.fromisoformat(wrapper['frozenAtIso'])
                invalid=(timestamp.tzinfo is None or as_aware(timestamp)<as_aware(study_session.started_at) or
                    digest(wrapper['content'])!=row.content_hash or
                    wrapper['question']!=wrapper['content']['question'])
            except (ValueError,TypeError,OverflowError):invalid=True
        if invalid:raise ApiError('unavailable','Stored study answer requires integrity review',retryable=False)
        answer=scoped_answer(db,principal,row.answer_id)
        request=db.get(AnswerRequest,answer.request_id)
        if (request is None or answer.project_id!=pin['projectId'] or request.project_id!=pin['projectId'] or
            answer.snapshot_hash!=pin['snapshotHash'] or request.snapshot_hash!=pin['snapshotHash'] or
            answer.created_by!=study_session.created_by or request.created_by!=study_session.created_by or
            as_aware(answer.created_at)<as_aware(study_session.started_at) or answer.mode!=wrapper['mode'] or
            not same_json(wrapper['content'],{'question':request.question,'payload':answer.payload,'provenance':answer.provenance})):
            raise ApiError('unavailable','Stored study answer requires integrity review',retryable=False)
    return rows


def freeze_native_answer(db,principal,study_session,item):
    project,pin=corpus_case(db,principal,study_session.protocol_config,item.caseIndex)
    answer=scoped_answer(db,principal,item.payload.get('answer_id',''))
    if answer.project_id!=project.id or answer.status not in {'draft','validated'} or answer.snapshot_hash!=pin['snapshotHash']:
        raise ApiError('unprocessable_entity','Frozen study answer does not match the registered scenario')
    if item.conditionBlinded==study_session.protocol_config['condition_permutation']['making_visible'] and answer.provenance.get('pipeline')!='reasoning':
        raise ApiError('unavailable','Study reasoning interface is not available for this answer',retryable=False)
    request=db.get(AnswerRequest,answer.request_id)
    if request is None or request.created_by!=principal.principal_id or answer.created_by!=principal.principal_id:
        raise ApiError('unprocessable_entity','Frozen study answer does not match this session actor')
    if as_aware(answer.created_at)<as_aware(study_session.started_at):
        raise ApiError('unprocessable_entity','Frozen study answer predates this session')
    content={'question':request.question,'payload':answer.payload,'provenance':answer.provenance}
    problem=privacy_problem(content,byte_limit=131072)
    if problem:raise ApiError('unprocessable_entity','Frozen study answer exceeds its privacy contract')
    content_hash=digest(content)
    if item.payload.get('mode')!=answer.mode or item.payload.get('content_hash')!=content_hash:
        raise ApiError('unprocessable_entity','Frozen study answer identity does not match its stored content')
    frozen={'caseIndex':item.caseIndex,'answerId':answer.id,'mode':answer.mode,'question':request.question,
            'content':copy.deepcopy(content),'contentHash':content_hash,'frozenAtIso':utcnow().isoformat()}
    return StudyFrozenAnswer(session_id=study_session.id,case_index=item.caseIndex,answer_id=answer.id,
                             content_hash=content_hash,payload=frozen)

"""Pure assignment and replay for the existing nine-case mechanism study.

This module does not approve packs, store blinding maps, run models, or admit
participants. Callers must supply a privately stored, explicit condition map
and server-sequenced history. Public projections contain only blinded labels
and references; response text and arbitrary event payloads are never copied.

The Latin-square order mirrors the pinned TypeScript/Python source plan.
Completion follows StudyScreen.finish(), including its optional what-would-
change response. No additional questionnaire or rubric measure is required.
"""
from __future__ import annotations

import hashlib
import json
import re
from collections.abc import Iterable, Mapping
from dataclasses import dataclass, field
from typing import Any

ASSIGNMENT_SCHEMA = "mv.study.assignment/1"
RESUME_SCHEMA = "mv.study.resume/1"
PLANNED_PARTICIPANTS = 18
TOTAL_CASES = 9

# Private implementation constants: never included in a returned projection.
_CONDITIONS = ("raw_viewer", "flat_assistant", "making_visible")
_BLINDED_IDS = ("cond-1", "cond-2", "cond-3")
_INTERVENTIONS = frozenset({
    "ask the group a question", "pause the group for discussion",
    "investigate the physical build", "request more evidence",
    "revise the design interpretation", "note it and move on",
})
_EVENT_TYPES = frozenset({
    "session_started", "case_started", "evidence_viewed", "evidence_cited",
    "guidance_frozen", "guidance_replayed", "condition_unavailable",
    "question_edited", "response_describe_evidence", "intervention_selected",
    "response_what_would_change", "confidence_rated", "case_completed",
    "export_generated", "withdrawal_requested", "evidence_rendered",
    "evidence_opened", "citation_selected", "video_played", "video_seeked",
    "case_paused", "case_resumed", "intentionally_waited",
})
_SESSION_EVENTS = frozenset({
    "session_started", "export_generated", "withdrawal_requested",
})
_RESPONSE_EVENTS = frozenset({
    "response_describe_evidence", "intervention_selected",
    "response_what_would_change", "confidence_rated",
})
_REQUIRED_RESPONSES = _RESPONSE_EVENTS - {"response_what_would_change"}
_HASH = re.compile(r"[0-9a-f]{64}\Z")


class StudyProtocolError(ValueError):
    """A fixed, public-safe reason code; no private input values in errors."""

    def __init__(self, reason: str):
        self.reason = reason
        super().__init__(reason)


def _condition_map(value: Mapping[str, str]) -> dict[str, str]:
    if not isinstance(value, Mapping) or set(value) != set(_CONDITIONS):
        raise StudyProtocolError("invalid_private_condition_permutation")
    values = [value[name] for name in _CONDITIONS]
    if (
        any(not isinstance(item, str) or item not in _BLINDED_IDS for item in values)
        or len(set(values)) != 3
    ):
        raise StudyProtocolError("invalid_private_condition_permutation")
    return dict(zip(_CONDITIONS, values))


def server_assignment(
    participant_number: int, *, condition_permutation: Mapping[str, str]
) -> dict[str, Any]:
    """Return the public source-exact plan with explicitly permuted labels.

    The required map is actual source condition name -> blinded cond-N id.
    It is NOT the legacy client-side list of internal condition indexes.
    There is no default blinding map and no acceptance of a client arm.
    """
    private = _condition_map(condition_permutation)
    if type(participant_number) is not int or not 1 <= participant_number <= 18:
        raise StudyProtocolError("invalid_participant_number")
    row = (participant_number - 1) % 3
    cases = []
    for offset in range(3):
        set_id = (offset + row) % 3
        condition = _CONDITIONS[(set_id + row) % 3]
        for within_set in range(3):
            case_index = set_id * 3 + within_set
            cases.append({
                "caseIndex": case_index,
                "label": f"Scenario {case_index + 1}",
                "setId": set_id,
                "blindedConditionId": private[condition],
            })
    return {
        "schema": ASSIGNMENT_SCHEMA,
        "participantNumber": participant_number,
        "caseOrder": [case["caseIndex"] for case in cases],
        "cases": cases,
    }


def _canonical(value: Any) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False)


def _assignment(
    value: Mapping[str, Any], condition_permutation: Mapping[str, str]
) -> dict[str, Any]:
    # Reconstruct, rather than trust, a persisted public assignment. Exact
    # canonical comparison also distinguishes bool/float indexes from ints.
    if (
        not isinstance(value, Mapping)
        or value.get("schema") != ASSIGNMENT_SCHEMA
        or not isinstance(value.get("caseOrder"), list)
        or not isinstance(value.get("cases"), list)
    ):
        raise StudyProtocolError("unsupported_assignment")
    expected = server_assignment(
        value.get("participantNumber"), condition_permutation=condition_permutation
    )
    try:
        matches = _canonical(value) == _canonical(expected)
    except (TypeError, ValueError):
        matches = False
    if not matches:
        raise StudyProtocolError("unsupported_assignment")
    return expected


@dataclass
class _CaseState:
    assignment: dict[str, Any]
    started: bool = False
    completed: bool = False
    paused: bool = False
    unavailable: bool = False
    responses: dict[str, str] = field(default_factory=dict)
    frozen: dict[str, str] | None = None


def _payload_response(event_type: str, payload: Mapping[str, Any]) -> None:
    if event_type in {"response_describe_evidence", "response_what_would_change"}:
        text = payload.get("text")
        if not isinstance(text, str) or not text.strip():
            raise StudyProtocolError("invalid_response_text")
    elif event_type == "intervention_selected":
        choice = payload.get("intervention")
        if not isinstance(choice, str) or choice not in _INTERVENTIONS:
            raise StudyProtocolError("invalid_intervention")
    elif event_type == "confidence_rated":
        confidence = payload.get("confidence")
        if type(confidence) is not int or not 1 <= confidence <= 5:
            raise StudyProtocolError("invalid_confidence")


def replay_state(
    assignment: Mapping[str, Any],
    sequenced_events: Iterable[Mapping[str, Any]],
    *,
    condition_permutation: Mapping[str, str],
    session_status: str = "active",
) -> dict[str, Any]:
    """Validate server history and return a public resumable projection.

    Events use wire keys id, sequence, type, caseIndex, conditionBlinded and
    payload. Sequences must already be server-owned, contiguous, in order.
    Missing/legacy assignment, partial history and invalid transitions fail
    closed. This function never sorts or renumbers client claims.

    Guidance mode checks are structural only. The integrating service must
    authorize the actual answer and verify frozen content/model availability.
    Timestamp, payload privacy/size, RBAC, idempotency and DB concurrency also
    remain service responsibilities. Neither a mode tag nor a replayed state
    is evidence of human approval or a successful real model invocation.
    """
    public_assignment = _assignment(assignment, condition_permutation)
    private = _condition_map(condition_permutation)
    if not isinstance(session_status, str) or session_status not in {"active", "completed", "withdrawn"}:
        raise StudyProtocolError("invalid_session_status")
    states = [_CaseState(case) for case in public_assignment["cases"]]
    cursor, last_sequence = 0, 0
    seen: set[str] = set()
    session_started = False
    withdrawal_requested = False
    for event in sequenced_events:
        if session_status == "withdrawn" or withdrawal_requested:
            raise StudyProtocolError("session_withdrawn")
        if not isinstance(event, Mapping) or not {
            "id", "sequence", "type", "caseIndex", "conditionBlinded", "payload"
        }.issubset(event):
            raise StudyProtocolError("invalid_event_shape")
        event_id = event["id"]
        if not isinstance(event_id, str) or not event_id.strip():
            raise StudyProtocolError("invalid_event_id")
        if event_id in seen:
            raise StudyProtocolError("duplicate_event_id")
        sequence = event["sequence"]
        if type(sequence) is not int or sequence != last_sequence + 1:
            raise StudyProtocolError("invalid_server_sequence")
        event_type, payload = event["type"], event["payload"]
        if not isinstance(event_type, str) or event_type not in _EVENT_TYPES:
            raise StudyProtocolError("unknown_event_type")
        if not isinstance(payload, Mapping):
            raise StudyProtocolError("invalid_event_payload")
        if event_type in _SESSION_EVENTS:
            if event["caseIndex"] is not None or event["conditionBlinded"] is not None:
                raise StudyProtocolError("invalid_session_event_scope")
            if event_type == "session_started":
                if session_started or any(case.started for case in states):
                    raise StudyProtocolError("session_already_started")
                session_started = True
            elif event_type == "withdrawal_requested":
                withdrawal_requested = True
        else:
            if cursor == TOTAL_CASES:
                raise StudyProtocolError("all_cases_completed")
            case = states[cursor]
            if (
                type(event["caseIndex"]) is not int
                or event["caseIndex"] != case.assignment["caseIndex"]
            ):
                raise StudyProtocolError("case_out_of_order")
            if event["conditionBlinded"] != case.assignment["blindedConditionId"]:
                raise StudyProtocolError("case_condition_mismatch")
            if event_type == "case_started":
                if case.started:
                    raise StudyProtocolError("case_already_started")
                case.started = True
            else:
                if not case.started:
                    raise StudyProtocolError("case_not_started")
                if event_type == "case_resumed":
                    if not case.paused:
                        raise StudyProtocolError("case_not_paused")
                    case.paused = False
                elif event_type == "case_paused":
                    if case.paused:
                        raise StudyProtocolError("case_already_paused")
                    case.paused = True
                else:
                    if case.paused:
                        raise StudyProtocolError("case_paused")
                    if event_type == "condition_unavailable":
                        case.unavailable = True
                    elif event_type == "case_completed":
                        if case.unavailable:
                            raise StudyProtocolError("condition_unavailable")
                        if not _REQUIRED_RESPONSES.issubset(case.responses):
                            raise StudyProtocolError("case_responses_incomplete")
                        case.completed = True
                        cursor += 1
                    elif event_type in _RESPONSE_EVENTS:
                        _payload_response(event_type, payload)
                        case.responses[event_type] = event_id
                    elif event_type == "guidance_frozen":
                        if case.unavailable:
                            raise StudyProtocolError("condition_unavailable")
                        blinded = case.assignment["blindedConditionId"]
                        if blinded == private["raw_viewer"]:
                            raise StudyProtocolError("guidance_not_allowed")
                        if case.frozen is not None:
                            raise StudyProtocolError("guidance_already_frozen")
                        answer_id, mode, content_hash = (
                            payload.get("answer_id"), payload.get("mode"),
                            payload.get("content_hash"),
                        )
                        if (
                            not isinstance(answer_id, str) or not answer_id.strip()
                            or not isinstance(mode, str)
                            or mode not in {"template", "local_model", "fixture"}
                            or not isinstance(content_hash, str)
                            or _HASH.fullmatch(content_hash) is None
                        ):
                            raise StudyProtocolError("invalid_frozen_guidance")
                        if blinded == private["flat_assistant"] and mode != "local_model":
                            raise StudyProtocolError("guidance_mode_unavailable")
                        case.frozen = {
                            "eventId": event_id, "answerId": answer_id,
                            "contentHash": content_hash,
                        }
                    elif event_type == "guidance_replayed":
                        if (
                            case.frozen is None
                            or payload.get("answer_id") != case.frozen["answerId"]
                        ):
                            raise StudyProtocolError("frozen_guidance_mismatch")
        seen.add(event_id)
        last_sequence = sequence
    if session_status == "completed" and cursor != TOTAL_CASES:
        raise StudyProtocolError("session_completion_incomplete")
    if session_status == "withdrawn" or withdrawal_requested:
        phase = "withdrawn"
    elif cursor == TOTAL_CASES:
        phase = "complete"
    else:
        current = states[cursor]
        phase = (
            "unavailable" if current.unavailable else "paused" if current.paused
            else "active" if current.started else "ready"
        )
    return {
        "schema": RESUME_SCHEMA,
        "assignmentHash": hashlib.sha256(_canonical(public_assignment).encode()).hexdigest(),
        "participantNumber": public_assignment["participantNumber"],
        "lastSequence": last_sequence,
        "currentCaseIndex": None if phase in {"complete", "withdrawn"} else states[cursor].assignment["caseIndex"],
        "phase": phase,
        "completedCaseIndexes": [case.assignment["caseIndex"] for case in states if case.completed],
        "cases": [
            {
                **case.assignment, "started": case.started,
                "completed": case.completed, "paused": case.paused,
                "unavailable": case.unavailable,
                "responseEventIds": dict(case.responses),
                "frozenGuidance": dict(case.frozen) if case.frozen else None,
            }
            for case in states
        ],
    }


def validate_event(
    assignment: Mapping[str, Any],
    prior_events: Iterable[Mapping[str, Any]],
    candidate: Mapping[str, Any],
    *,
    condition_permutation: Mapping[str, str],
    session_status: str = "active",
) -> str | None:
    """Return a safe rejection reason or None, without mutating inputs.

    Deduplicate retries and reserve the next sequence in the service first.
    Feed the full trusted prior history, not a browser-supplied resume object.
    Accepted earlier events in the same batch must be included in that history.
    """
    try:
        replay_state(
            assignment, (*prior_events, candidate),
            condition_permutation=condition_permutation, session_status=session_status,
        )
    except StudyProtocolError as exc:
        return exc.reason
    return None

