"""Validate and descriptively summarize de-identified study export bundles.

Source of truth for the collection schema is
`apps/web/src/lib/study/session.ts` (exportBundle / CSV_COLUMNS / the
StudyEventType union). This module consumes its pinned projection,
`../schema/events.json`, and refuses anything else:

- bundle fields, event fields, event types, blinded condition ids and CSV
  columns must match the projection exactly (no imagined superset);
- the de-identification scan rejects inline media, internal condition
  names, and the blinding map — mirroring the UI's pre-download guard;
- bundles with zero events are refused (an empty input is not a result);
- output text always states it describes its input, and never claims a
  study, an effect, or a result.

No inferential statistics live here (see package docstring / docs/13).
"""
from __future__ import annotations

import argparse
import csv
import hashlib
import io
import json
import re
import sys
from datetime import datetime
from pathlib import Path
from typing import Any

from ..counterbalance import BLINDED_CONDITION_IDS, load_schema

BUNDLE_SCHEMA = "mv.study.export/1"
SCENARIO_LABEL = re.compile(r"^Scenario [1-9]$")
CONTENT_HASH = re.compile(r"^[0-9a-f]{64}$")

# Tokens that must never appear in a de-identified bundle (docs/15).
_MEDIA_TOKENS = ("data:video", "data:audio", "data:image", "base64")
_INTERNAL_CONDITION_NAMES = ("raw_viewer", "flat_assistant", "making_visible")
_BLINDING_MAP_TOKEN = "condition_permutation"

RESULT_BANNER = (
    "DESCRIPTIVE SUMMARY OF THE INPUT FILE(S) ONLY — not a study result, "
    "not an effect, and not evidence about teaching. No teacher effects are estimated."
)


def _iso(value: Any) -> bool:
    if not isinstance(value, str):
        return False
    try:
        datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return False
    return True


def _exact_keys(obj: Any, expected: list[str], where: str, faults: list[str]) -> None:
    if not isinstance(obj, dict):
        faults.append(f"{where}: expected an object")
        return
    for key in expected:
        if key not in obj:
            faults.append(f"{where}: missing field '{key}'")
    for key in obj:
        if key not in expected:
            faults.append(f"{where}: unexpected field '{key}' (schema is closed)")


def validate_bundle(bundle: Any) -> list[str]:
    """Strict structural + de-identification validation. Empty list = valid."""
    schema = load_schema()
    faults: list[str] = []
    _exact_keys(bundle, schema["export_bundle_fields"], "bundle", faults)
    if not isinstance(bundle, dict):
        return faults
    if bundle.get("schema") != BUNDLE_SCHEMA:
        faults.append(f"bundle.schema must be '{BUNDLE_SCHEMA}', got {bundle.get('schema')!r}")
    if not isinstance(bundle.get("sessionId"), str) or not bundle.get("sessionId"):
        faults.append("bundle.sessionId must be a non-empty string")
    participant = bundle.get("participantNumber")
    if not isinstance(participant, int) or isinstance(participant, bool) or not 1 <= participant <= schema["planned_participants"]:
        faults.append(f"bundle.participantNumber must be 1..{schema['planned_participants']}")
    if not isinstance(bundle.get("pseudonym"), str) or not bundle.get("pseudonym", "").strip():
        faults.append("bundle.pseudonym must be a non-empty string")
    if not isinstance(bundle.get("packLabel"), str) or not bundle.get("packLabel", "").strip():
        faults.append("bundle.packLabel must be a non-empty string")
    if not _iso(bundle.get("startedAtIso")):
        faults.append("bundle.startedAtIso must be an ISO timestamp")

    blinded_ids = set(schema["blinded_condition_ids"])
    allowed_types = set(schema["event_types"])
    total_cases = schema["total_cases"]

    events = bundle.get("events")
    if not isinstance(events, list):
        faults.append("bundle.events must be a list")
        events = []
    for i, event in enumerate(events):
        where = f"events[{i}]"
        _exact_keys(event, ["type", "atIso", "msSinceStart", "caseIndex", "conditionBlinded", "payload"], where, faults)
        if not isinstance(event, dict):
            continue
        if event.get("type") not in allowed_types:
            faults.append(f"{where}.type '{event.get('type')!r}' is not in the pinned event union")
        if not _iso(event.get("atIso")):
            faults.append(f"{where}.atIso must be an ISO timestamp")
        ms = event.get("msSinceStart")
        if type(ms) is not int or ms < 0:
            faults.append(f"{where}.msSinceStart must be a non-negative integer")
        case_index = event.get("caseIndex")
        if case_index is not None and (
            not isinstance(case_index, int) or isinstance(case_index, bool) or not 0 <= case_index < total_cases
        ):
            faults.append(f"{where}.caseIndex must be null or 0..{total_cases - 1}")
        condition = event.get("conditionBlinded")
        if condition is not None and condition not in blinded_ids:
            faults.append(f"{where}.conditionBlinded {condition!r} must be null or one of {sorted(blinded_ids)}")
        if not isinstance(event.get("payload"), dict):
            faults.append(f"{where}.payload must be an object")

    frozen = bundle.get("frozenAnswers")
    if not isinstance(frozen, list):
        faults.append("bundle.frozenAnswers must be a list")
        frozen = []
    for i, answer in enumerate(frozen):
        where = f"frozenAnswers[{i}]"
        # Exported frozen answers carry a "Scenario k" label, not caseIndex
        # (mirrors exportBundle in session.ts).
        _exact_keys(answer, schema["frozen_answer_fields"], where, faults)
        if not isinstance(answer, dict):
            continue
        if not SCENARIO_LABEL.match(str(answer.get("scenario", ""))):
            faults.append(f"{where}.scenario must be a 'Scenario k' label")
        for field in ("answerId", "mode", "question"):
            if not isinstance(answer.get(field), str) or not answer.get(field, "").strip():
                faults.append(f"{where}.{field} must be a non-empty string")
        if not isinstance(answer.get("content"), dict):
            faults.append(f"{where}.content must be an object")
        if not CONTENT_HASH.match(str(answer.get("contentHash", ""))):
            faults.append(f"{where}.contentHash must be a 64-char lowercase hex SHA-256")

    completed = bundle.get("completedScenarios")
    if not isinstance(completed, list) or any(
        not isinstance(s, str) or not SCENARIO_LABEL.match(s) for s in (completed or [])
    ):
        faults.append('bundle.completedScenarios must be a list of "Scenario k" labels')

    # De-identification scan over the serialized bundle — catches string
    # values AND dict keys (e.g., a stray condition_permutation object).
    dumped = json.dumps(bundle).lower()
    for token in (*_MEDIA_TOKENS, *_INTERNAL_CONDITION_NAMES, _BLINDING_MAP_TOKEN):
        if token in dumped:
            faults.append(f"deidentification: forbidden token '{token}' present")
    return faults


def require_valid(bundle: Any) -> None:
    """Raise ValueError with the fault list unless the bundle is valid."""
    faults = validate_bundle(bundle)
    if faults:
        raise ValueError("export bundle failed validation:\n" + "\n".join(f"- {f}" for f in faults))


def bundle_sha256(bundle: dict[str, Any]) -> str:
    """Match the native export receipt, including Python's ASCII escaping.

    This hashes canonical bundle content, not a saved JSON file or a browser
    frozen-answer hash. Reject non-finite numbers rather than hashing invalid
    JSON. The native service admits only finite, privacy-reviewed payloads.
    """
    canonical = json.dumps(bundle, sort_keys=True, separators=(",", ":"), allow_nan=False)
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()


def unwrap_export(document: Any, *, require_receipt: bool = False) -> dict[str, Any]:
    """Read a bare export or the exact native JSON download envelope.

    A matching digest establishes content identity, not permission, current
    withdrawal status, successful blinding or truthful human provenance.
    Rating admission requires an envelope; descriptive legacy inputs may be
    bare bundles. Errors disclose no supplied response content.
    """
    if isinstance(document, dict) and document.get("schema") == BUNDLE_SCHEMA:
        if require_receipt:
            raise ValueError("native_export_receipt_required")
        return document
    if not isinstance(document, dict) or set(document) != {
        "session_id", "created_at", "bundle_sha256", "bundle"
    }:
        raise ValueError("native_export_envelope_invalid")
    bundle = document["bundle"]
    try:
        valid = isinstance(bundle, dict) and not validate_bundle(bundle)
        digest = bundle_sha256(bundle) if valid else None
    except (TypeError, ValueError, UnicodeError):
        valid, digest = False, None
    if not valid:
        raise ValueError("native_export_bundle_invalid")
    if not _iso(document["created_at"]):
        raise ValueError("native_export_receipt_time_invalid")
    if document["session_id"] != bundle["sessionId"]:
        raise ValueError("native_export_session_mismatch")
    if not isinstance(document["bundle_sha256"], str) or not CONTENT_HASH.fullmatch(document["bundle_sha256"]):
        raise ValueError("native_export_digest_invalid")
    if document["bundle_sha256"] != digest:
        raise ValueError("native_export_digest_mismatch")
    return bundle


def _count(events: list[dict[str, Any]], key_fn: Any) -> dict[str, int]:
    counts: dict[str, int] = {}
    for event in events:
        key = key_fn(event)
        counts[key] = counts.get(key, 0) + 1
    return dict(sorted(counts.items()))


def _require_non_empty(bundle: dict[str, Any]) -> None:
    """Fail closed on empty input rather than summarizing zeros."""
    if not bundle.get("events"):
        raise ValueError("refusing empty input: a bundle with zero events is not a summary")


def describe_bundle(bundle: dict[str, Any]) -> dict[str, Any]:
    """Descriptive counts of one validated bundle. No statistics, no claims."""
    require_valid(bundle)
    _require_non_empty(bundle)
    events = bundle["events"]
    by_scenario = _count(
        [e for e in events if e.get("caseIndex") is not None],
        lambda e: f"Scenario {e['caseIndex'] + 1}",
    )
    by_condition = _count(
        [e for e in events if e.get("conditionBlinded") is not None],
        lambda e: str(e["conditionBlinded"]),
    )
    per_type_per_condition = _count(
        [e for e in events if e.get("conditionBlinded") is not None],
        lambda e: f"{e['type']}@{e['conditionBlinded']}",
    )
    return {
        "note": RESULT_BANNER,
        "input": {
            "sessionId": bundle["sessionId"],
            "participantNumber": bundle["participantNumber"],
            "pseudonym": bundle["pseudonym"],
            "packLabel": bundle["packLabel"],
            "event_count": len(events),
            "frozen_answer_count": len(bundle["frozenAnswers"]),
            "completed_scenarios": bundle["completedScenarios"],
        },
        "events_by_type": _count(events, lambda e: str(e["type"])),
        "events_by_scenario_label": by_scenario,
        "events_by_blinded_condition": by_condition,
        "events_by_type_per_blinded_condition": per_type_per_condition,
    }


def to_csv_rows(bundle: dict[str, Any]) -> str:
    """Long-format CSV with exactly the pinned CSV_COLUMNS order."""
    require_valid(bundle)
    _require_non_empty(bundle)
    schema = load_schema()
    out = io.StringIO()
    # The app's exportCsv quotes every cell; mirror that so files compare.
    writer = csv.writer(out, lineterminator="\n", quoting=csv.QUOTE_ALL)
    writer.writerow(schema["csv_columns"])
    for event in bundle["events"]:
        case_index = event.get("caseIndex")
        writer.writerow([
            event["type"],
            event["atIso"],
            event["msSinceStart"],
            f"Scenario {case_index + 1}" if case_index is not None else "",
            event.get("conditionBlinded") or "",
            json.dumps(event.get("payload", {}), sort_keys=True),
        ])
    return out.getvalue()


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        description=(
            "Validate and descriptively summarize de-identified export "
            "bundles (mv.study.export/1). Describes its input; never "
            "produces or implies study results."
        )
    )
    parser.add_argument("bundles", nargs="+", type=Path, help="paths to export .json files")
    parser.add_argument("--csv", action="store_true", help="also print the long-format CSV per bundle")
    args = parser.parse_args(argv)

    any_failure = False
    for path in args.bundles:
        print(f"=== {path.name} ===")
        try:
            document = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc:
            print(f"error: cannot read export bundle: {exc}", file=sys.stderr)
            any_failure = True
            continue
        try:
            bundle = unwrap_export(document)
        except ValueError as exc:
            print(f"FAULT: {exc}")
            any_failure = True
            continue
        faults = validate_bundle(bundle)
        if faults:
            for fault in faults:
                print(f"FAULT: {fault}")
            any_failure = True
            continue
        if not bundle.get("events"):
            # Fail closed on empty input rather than printing a zero summary.
            print("REFUSED: bundle has zero events — empty input is not a summary.")
            any_failure = True
            continue
        print(json.dumps(describe_bundle(bundle), indent=2))
        if args.csv:
            print(to_csv_rows(bundle))
    print(RESULT_BANNER)
    return 1 if any_failure else 0


if __name__ == "__main__":
    raise SystemExit(main())

