"""Content-addressed study artifacts, separate from participant records.

JSON values are stored as canonical strings in frozen records so nested
mutation cannot silently change an artifact. Hashes establish byte identity;
they do not establish permission, semantic support, or human approval.
"""
from __future__ import annotations

import hashlib
import json
import math
from decimal import Decimal
from pathlib import Path
from typing import Any, Literal

from pydantic import BaseModel, ConfigDict, Field, model_validator

from contracts.models import TeacherContext

CONDITIONS = ("raw_viewer", "flat_assistant", "making_visible")
CASE_TYPES = (
    "normal_motion", "operator_pause", "true_output_obstruction",
    "ambiguous_projected_contact", "mismatched_saved_physical_version",
    "loose_coupling", "audio_distractor", "missing_camera_or_audio",
    "recovery_across_revisions",
)
Condition = Literal["raw_viewer", "flat_assistant", "making_visible"]
Hash = str


def canonical_json(value: Any) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"),
                      ensure_ascii=True, allow_nan=False)


def digest(value: Any) -> str:
    return hashlib.sha256(canonical_json(value).encode()).hexdigest()


def browser_json(value: Any) -> str:
    """Canonical JSON.stringify bytes for the pinned study content hash.

    This pure codec is retained from the independently tested native-study
    adapter. Artifact identity uses canonical_json; browser exposure/content
    hashes use this codec, including UTF-16 key order and number formatting.
    """
    def encode(node):
        if node is None:
            return "null"
        if node is True:
            return "true"
        if node is False:
            return "false"
        if isinstance(node, str):
            return json.dumps(node, ensure_ascii=False)
        if isinstance(node, dict):
            return "{" + ",".join(encode(k) + ":" + encode(node[k])
                                   for k in sorted(node, key=lambda k: k.encode("utf-16-be"))) + "}"
        if isinstance(node, list):
            return "[" + ",".join(encode(v) for v in node) + "]"
        if type(node) is int and abs(node) <= 2**53 - 1:
            return str(node)
        if type(node) in {int, float}:
            number = float(node)
            if not math.isfinite(number):
                raise ValueError("non-finite JSON number")
            if number == 0:
                return "0"
            raw = repr(number).lower()
            if 1e-6 <= abs(number) < 1e21:
                fixed = format(Decimal(raw), "f")
                return fixed.rstrip("0").rstrip(".") if "." in fixed else fixed
            mantissa, exponent = raw.split("e")
            if mantissa.endswith(".0"):
                mantissa = mantissa[:-2]
            exp = int(exponent)
            return mantissa + "e" + ("+" if exp >= 0 else "-") + str(abs(exp))
        raise ValueError("unsupported JSON value")
    return encode(value)


def browser_digest(value: Any) -> str:
    return hashlib.sha256(browser_json(value).encode()).hexdigest()


def file_digest(path: Path) -> str:
    hasher = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            hasher.update(chunk)
    return hasher.hexdigest()


class FrozenRecord(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)


class FrozenJSON(FrozenRecord):
    canonical: str
    sha256: str = Field(pattern=r"^[0-9a-f]{64}$")

    @classmethod
    def of(cls, value: Any) -> "FrozenJSON":
        return cls(canonical=canonical_json(value), sha256=digest(value))

    def value(self) -> Any:
        return json.loads(self.canonical)

    @model_validator(mode="after")
    def check(self) -> "FrozenJSON":
        value = self.value()
        if canonical_json(value) != self.canonical or digest(value) != self.sha256:
            raise ValueError("canonical JSON/hash mismatch")
        return self


class SourceSpec(FrozenRecord):
    source_id: str = Field(min_length=1)
    path: str = Field(min_length=1)
    kind: Literal["media", "design", "transcript", "history", "audio_features"]
    origin: Literal["synthetic_media", "approved_real"]
    asset_id: str | None = None


class SourceDigest(SourceSpec):
    sha256: str = Field(pattern=r"^[0-9a-f]{64}$")
    bytes: int = Field(ge=0)
    original_content: FrozenJSON | None = None


class InformationBudget(FrozenRecord):
    max_visual_frames: int = Field(default=16, ge=0, le=16)
    max_input_tokens: int = Field(default=12000, gt=0, le=12000)
    max_output_tokens: Literal[1500] = 1500
    inference_calls: Literal[1] = 1
    decoding: Literal["greedy_temperature_0"] = "greedy_temperature_0"
    seed: Literal[0] = 0


class CaseSpec(FrozenRecord):
    case_index: int = Field(ge=0, le=8, strict=True)
    case_type: str
    project_id: str = Field(min_length=1)
    selected_version_id: str = Field(min_length=1)
    question: str = Field(min_length=1, max_length=2000)
    neutral_brief: str = Field(min_length=1)
    context: TeacherContext
    sources: tuple[SourceSpec, ...] = Field(min_length=1)
    # Reusing a public answer preserves its original snapshot. Otherwise the
    # compiler asks ONCE before participant exposure, never in a study session.
    answer_id: str | None = None

    @model_validator(mode="after")
    def check(self) -> "CaseSpec":
        if self.case_type not in CASE_TYPES:
            raise ValueError("unknown researcher-only case type")
        if len({s.source_id for s in self.sources}) != len(self.sources):
            raise ValueError("duplicate source id")
        return self


class CompilerSpec(FrozenRecord):
    schema_version: Literal["mv.study.compile/1"] = "mv.study.compile/1"
    label: str = Field(min_length=1, max_length=200)
    protocol_version: str = Field(min_length=1, max_length=40)
    purpose: Literal["engineering_preview", "main_study"]
    budget: InformationBudget = Field(default_factory=InformationBudget)
    cases: tuple[CaseSpec, ...] = Field(min_length=9, max_length=9)

    @model_validator(mode="after")
    def check(self) -> "CompilerSpec":
        if {c.case_index for c in self.cases} != set(range(9)):
            raise ValueError("exactly nine distinct case indexes 0..8 required")
        if {c.case_type for c in self.cases} != set(CASE_TYPES):
            raise ValueError("all nine planned case types required, once each")
        return self


class FrozenCase(FrozenRecord):
    case_index: int = Field(ge=0, le=8, strict=True)
    case_type: str
    project_id: str
    selected_version_id: str
    question: str
    neutral_brief: str
    context: FrozenJSON
    sources: tuple[SourceDigest, ...]
    source_hash: str
    case_hash: str

    def identity(self) -> dict:
        return self.model_dump(mode="json", exclude={"case_hash"})

    @model_validator(mode="after")
    def check(self) -> "FrozenCase":
        if self.source_hash != digest([s.model_dump(mode="json") for s in self.sources]):
            raise ValueError("source manifest hash mismatch")
        if self.case_hash != digest(self.identity()):
            raise ValueError("case hash mismatch")
        TeacherContext.model_validate(self.context.value())
        return self


class ExecutionReceipt(FrozenRecord):
    kind: Literal["source_viewer", "production_http", "local_weights",
                  "synthetic_plumbing", "not_run"]
    adapter: str
    inference_calls: int = Field(default=0, ge=0)
    prompt_tokens: int | None = Field(default=None, ge=0)
    generated_tokens: int | None = Field(default=None, ge=0)
    frame_ids: tuple[str, ...] = ()
    packet_hash: str | None = None
    model_revision: str | None = None
    latency_s: float | None = Field(default=None, ge=0)
    failure_stage: str | None = None
    failure_code: str | None = None
    # Rule/retrieval units remain labeled estimates, never tokenizer counts.
    details: FrozenJSON = Field(default_factory=lambda: FrozenJSON.of({}))


class Stimulus(FrozenRecord):
    case_index: int = Field(ge=0, le=8, strict=True)
    condition: Condition
    status: Literal["ready", "blocked", "failed"]
    case_hash: str
    source_hash: str
    context_hash: str
    code_hash: str
    model: FrozenJSON
    input: FrozenJSON
    content: FrozenJSON
    receipt: ExecutionReceipt
    stimulus_hash: str

    def identity(self) -> dict:
        return self.model_dump(mode="json", exclude={"stimulus_hash"})

    @model_validator(mode="after")
    def check(self) -> "Stimulus":
        if digest(self.identity()) != self.stimulus_hash:
            raise ValueError("stimulus hash mismatch")
        return self


class StudyRelease(FrozenRecord):
    schema_version: Literal["mv.study.release/1"] = "mv.study.release/1"
    label: str
    protocol_version: str
    purpose: Literal["engineering_preview", "main_study"]
    code: FrozenJSON
    budget: InformationBudget
    cases: tuple[FrozenCase, ...]
    stimuli: tuple[Stimulus, ...]
    release_hash: str

    def identity(self) -> dict:
        return self.model_dump(mode="json", exclude={"release_hash"})

    @model_validator(mode="after")
    def check(self) -> "StudyRelease":
        if digest(self.identity()) != self.release_hash:
            raise ValueError("release hash mismatch")
        return self


def seal(model: type[FrozenRecord], value: dict, hash_field: str) -> FrozenRecord:
    return model.model_validate({**value, hash_field: digest(value)})

