"""Compile nine cases × three immutable treatments before study exposure.

Run ``python -m research.study.compiler --help``. No participant, approval,
media, model output, or unavailable treatment is fabricated by the compiler.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import os
from pathlib import Path
import subprocess
from typing import Any

from .artifacts import (
    CompilerSpec, ExecutionReceipt, FrozenCase, FrozenJSON, SourceDigest,
    Stimulus, StudyRelease, canonical_json, digest, file_digest, seal,
)
from .backends import BackendBlocked, BackendOutput, LocalFlatBackend, PublicApiBackend


def code_identity(repo_root: Path) -> FrozenJSON:
    def git(*args: str) -> str:
        return subprocess.check_output(["git", *args], cwd=repo_root, text=True).strip()
    paths = set(git("ls-files").splitlines())
    # Include new owned modules during engineering development. Dirty code
    # gets an exact hash but cannot enter a main-study release.
    paths.update(str(p.relative_to(repo_root)) for p in (repo_root / "research/study").glob("*.py"))
    code_paths = sorted(p for p in paths if Path(p).suffix in {".py", ".ts", ".tsx", ".json", ".yaml", ".toml"}
                        and (repo_root / p).is_file())
    return FrozenJSON.of({
        "commit": git("rev-parse", "HEAD"),
        "clean": not bool(git("status", "--porcelain")),
        "files": [{"path": p, "sha256": file_digest(repo_root / p)} for p in code_paths],
    })


def freeze_case(case, source_root: Path) -> FrozenCase:
    sources = []
    for source in case.sources:
        path = (source_root / source.path).resolve()
        if not path.is_relative_to(source_root.resolve()) or not path.is_file():
            raise ValueError(f"case {case.case_index}: source missing/outside source root")
        raw = path.read_bytes()
        original = None
        if source.kind != 'media':
            text = raw.decode('utf-8')
            try:
                original = FrozenJSON.of(json.loads(text))
            except ValueError:
                original = FrozenJSON.of(text)
        sources.append(SourceDigest(**source.model_dump(mode="json"),
                                    sha256=hashlib.sha256(raw).hexdigest(), bytes=len(raw),
                                    original_content=original))
    source_json = [s.model_dump(mode="json") for s in sources]
    identity = {
        "case_index": case.case_index, "case_type": case.case_type,
        "project_id": case.project_id, "selected_version_id": case.selected_version_id,
        "question": case.question, "neutral_brief": case.neutral_brief,
        "context": FrozenJSON.of(case.context.model_dump(mode="json")).model_dump(mode="json"),
        "sources": source_json, "source_hash": digest(source_json),
    }
    return seal(FrozenCase, identity, "case_hash")


def raw_content(case: FrozenCase) -> FrozenJSON:
    """Only original source references + authored neutral brief/context.

    No observation statements, rule symptoms, hypothesis scores, generated
    claims, answer payloads, or diagnostic cards can enter this projection.
    Source-level semantic leakage still requires independent human review.
    """
    return FrozenJSON.of({
        "presentation": "raw_viewer", "neutral_brief": case.neutral_brief,
        "context": case.context.value(), "question": case.question,
        "sources": [{"source_id": s.source_id, "asset_id": s.asset_id,
                     "kind": s.kind, "sha256": s.sha256, "bytes": s.bytes,
                     "original_content": s.original_content.value() if s.original_content else None}
                    for s in case.sources if s.kind in {"media", "design", "transcript", "history"}],
    })


def _stimulus(case: FrozenCase, condition: str, code: FrozenJSON,
              output: BackendOutput, *, status: str = "ready") -> Stimulus:
    identity = {
        "case_index": case.case_index, "condition": condition, "status": status,
        "case_hash": case.case_hash, "source_hash": case.source_hash,
        "context_hash": case.context.sha256, "code_hash": code.sha256,
        "model": output.model.model_dump(mode="json"), "input": output.input.model_dump(mode="json"),
        "content": output.content.model_dump(mode="json"), "receipt": output.receipt.model_dump(mode="json"),
    }
    return seal(Stimulus, identity, "stimulus_hash")


def _failure(case: FrozenCase, condition: str, code: FrozenJSON,
             exc: Exception, *, frozen_input: FrozenJSON | None = None) -> Stimulus:
    blocked = isinstance(exc, BackendBlocked)
    receipt = ExecutionReceipt(
        kind="not_run", adapter=condition,
        failure_stage=getattr(exc, "stage", "model_execution"),
        failure_code=getattr(exc, "code", type(exc).__name__),
        details=FrozenJSON.of({"error_detail": str(exc)[:600]}),
    )
    return _stimulus(case, condition, code, BackendOutput(
        FrozenJSON.of({"presentation": "unavailable", "failure_code": receipt.failure_code}),
        frozen_input or FrozenJSON.of({"case_hash": case.case_hash}),
        FrozenJSON.of({"status": "not_executed"}), receipt,
    ), status="blocked" if blocked else "failed")


def compile_release(spec: CompilerSpec, *, source_root: Path, repo_root: Path,
                    api: PublicApiBackend | None = None,
                    flat: LocalFlatBackend | None = None) -> StudyRelease:
    code = code_identity(repo_root)
    cases = tuple(freeze_case(c, source_root) for c in sorted(spec.cases, key=lambda c: c.case_index))
    stimuli = []
    for case in cases:
        source_input = FrozenJSON.of({"case_hash": case.case_hash, "source_hash": case.source_hash,
                                     "budget": spec.budget.model_dump(mode="json")})
        stimuli.append(_stimulus(case, "raw_viewer", code, BackendOutput(
            raw_content(case), source_input, FrozenJSON.of({"family": "none", "inference": False}),
            ExecutionReceipt(kind="source_viewer", adapter="original_source_projection"),
        )))
        case_spec = next(c for c in spec.cases if c.case_index == case.case_index)
        mv = None
        try:
            if api is None:
                raise BackendBlocked("public_api_not_configured")
            mv = api.freeze(case_spec)
            stimuli.append(_stimulus(case, "making_visible", code, mv))
        except Exception as exc:
            stimuli.append(_failure(case, "making_visible", code, exc))
        try:
            if flat is None:
                raise BackendBlocked("flat_inference_not_configured", "model_execution")
            if mv is None:
                raise BackendBlocked("matching_frozen_packet_unavailable")
            result = flat.generate(mv.input, spec.budget, api)
            stimuli.append(_stimulus(case, "flat_assistant", code, result))
        except Exception as exc:
            stimuli.append(_failure(case, "flat_assistant", code, exc,
                                    frozen_input=mv.input if mv else None))
    identity = {
        "schema_version": "mv.study.release/1", "label": spec.label,
        "protocol_version": spec.protocol_version, "purpose": spec.purpose,
        "code": code.model_dump(mode="json"), "budget": spec.budget.model_dump(mode="json"),
        "cases": [c.model_dump(mode="json") for c in cases],
        "stimuli": [s.model_dump(mode="json") for s in stimuli],
    }
    return seal(StudyRelease, identity, "release_hash")


def write_release(release: StudyRelease, output_root: Path) -> Path:
    """Exclusive, content-addressed write. Existing bytes are never changed."""
    output_root.mkdir(parents=True, exist_ok=True)
    path = output_root / f"{release.release_hash}.json"
    content = canonical_json(release.model_dump(mode="json")) + "\n"
    try:
        descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    except FileExistsError:
        if path.read_text() != content:
            raise ValueError("immutable release path contains different bytes")
        return path
    with os.fdopen(descriptor, "w") as stream:
        stream.write(content)
    return path


def failure_summary(release: StudyRelease) -> dict[str, Any]:
    """Derived from actual receipts; a plumbing pass is never a model pass."""
    return {
        "schema": "mv.study.execution-summary/1", "release_hash": release.release_hash,
        "purpose": release.purpose, "case_count": len(release.cases),
        "condition_counts": {name: {
            status: sum(s.condition == name and s.status == status for s in release.stimuli)
            for status in ("ready", "blocked", "failed")
        } for name in ("raw_viewer", "flat_assistant", "making_visible")},
        "actual_local_generations": sum(s.receipt.kind == "local_weights" and s.status == "ready"
                                        for s in release.stimuli),
        "plumbing_only_outputs": sum(s.receipt.kind == "synthetic_plumbing" for s in release.stimuli),
        "failures": [{"case_index": s.case_index, "condition": s.condition,
                      "status": s.status, "stage": s.receipt.failure_stage,
                      "code": s.receipt.failure_code, "details": s.receipt.details.value()}
                     for s in release.stimuli if s.status != "ready"],
        "human_study_executed": False,
    }


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("spec", type=Path)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--repo-root", type=Path, default=Path(__file__).resolve().parents[2])
    parser.add_argument("--api-url", help="authorized deployment URL including /api/v1")
    parser.add_argument("--token-env", help="environment variable holding an authorized bearer token")
    parser.add_argument("--local-weights", type=Path)
    parser.add_argument("--model-lease", help="lead-issued lease name; required for model execution")
    args = parser.parse_args(argv)
    if args.local_weights and not args.model_lease:
        parser.error("--local-weights execution requires --model-lease")
    spec = CompilerSpec.model_validate_json(args.spec.read_text())
    headers = {}
    if args.token_env:
        headers["Authorization"] = "Bearer " + os.environ[args.token_env]
    api = PublicApiBackend(args.api_url, headers=headers) if args.api_url else None
    flat = LocalFlatBackend(args.local_weights, lease=args.model_lease) if args.local_weights else None
    release = compile_release(spec, source_root=args.spec.parent, repo_root=args.repo_root,
                              api=api, flat=flat)
    path = write_release(release, args.output)
    print(canonical_json({"artifact": str(path), "execution": failure_summary(release)}))
    # Incomplete engineering releases remain inspectable but have a failing
    # command status. They must not look like successful comparative execution.
    return 0 if all(s.status == "ready" for s in release.stimuli) else 1


if __name__ == "__main__":
    raise SystemExit(main())

