"""Summarize existing execution records without rerunning or tuning models.

This reads the preserved synthetic confirmation run. It does not promote its
historical availability labels to claims about today's installed checkpoint.
"""
from __future__ import annotations

import argparse
import json
from pathlib import Path

from .artifacts import canonical_json, digest, file_digest


def summarize_records(run_directory: Path) -> dict:
    filenames = ("frozen_manifest.json", "results.json", "done.json", "predictions_test.json")
    records, hashes, failures = {}, {}, []
    for name in filenames:
        path = run_directory / name
        if not path.is_file():
            failures.append({"record": name, "status": "not_run_or_missing_record"})
            continue
        hashes[name] = file_digest(path)
        try:
            records[name] = json.loads(path.read_text())
        except (OSError, ValueError) as exc:
            failures.append({"record": name, "status": "invalid_record", "error": type(exc).__name__})
    protocol = records.get("frozen_manifest.json", {})
    results = records.get("results.json", {})
    checked = {}
    for name, record, field in (("protocol", protocol, "protocol_digest"),
                                 ("results", results, "results_digest")):
        checked[name] = bool(record) and record.get(field) == digest({k: v for k, v in record.items() if k != field})
        if record and not checked[name]:
            failures.append({"record": name, "status": "content_digest_mismatch"})
    if protocol and results and protocol.get("code_sha") != results.get("code_sha"):
        failures.append({"record": "code_sha", "status": "manifest_results_mismatch"})
    if protocol and results and protocol.get("protocol_digest") != results.get("protocol_digest"):
        failures.append({"record": "protocol_digest", "status": "manifest_results_mismatch"})
    # Copy all declared contrasts, including null/unavailable ones. No
    # recomputation, subset selection, threshold changes, or sign reversal.
    contrasts = results.get("primary_contrasts", {})
    errors = {}
    for name, runs in results.get("conditions", {}).items():
        if isinstance(runs, dict):
            for seed, run in runs.items():
                if isinstance(run, dict) and "fp_by_variant" in run:
                    errors[f"{name}/{seed}"] = {
                        "fp_by_variant": run["fp_by_variant"],
                        "missing_evidence_head": run.get("missing_evidence_head"),
                        "threshold_used": run.get("threshold_used"),
                    }
    return {
        "schema": "mv.research.records-summary/1", "status": "records_verified" if not failures else "blocked",
        "record_sha256": hashes, "digest_checks": checked, "failures": failures,
        "code_sha": results.get("code_sha"), "run_status": results.get("run_status", "not_run"),
        "data_origin": protocol.get("data", {}), "recorded_seeds": results.get("seeds", []),
        "completed_condition_seed_records": records.get("done.json", []),
        "primary_contrasts": contrasts, "condition_summary": results.get("summary", {}),
        "unavailable_conditions": results.get("unavailable_conditions", {}),
        "case_failures_as_recorded": errors, "citation_audit": results.get("citation_audit", {}),
        "runtime_as_recorded": results.get("runtime", {}),
        "new_comparisons_executed": False, "human_study_executed": False,
        "scope": "historical records only; no real-data or teacher-benefit claim",
    }


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("run_directory", type=Path)
    args = parser.parse_args(argv)
    result = summarize_records(args.run_directory)
    print(canonical_json(result))
    return 0 if result["status"] == "records_verified" else 1


if __name__ == "__main__":
    raise SystemExit(main())

