"""In-browser demo runtime over the REAL merged service layer (ADR 006).

This module is a THIN route-contract shim only. It translates HTTP-shaped
requests to calls on the actual ``services.api.app`` router handler
functions — the same functions FastAPI dispatches to in the product API —
running over an in-memory SQLite store built with ``Base.metadata.create_all``.
There is no TypeScript reimplementation of import, analysis, account, or
guidance semantics anywhere in the demo; the Python service layer is the only
semantics.

Deliberate demo deltas (each recorded here, none silent):
- No Alembic: the in-memory store is created fresh in this tab with
  ``create_all`` from the same SQLAlchemy models, so migration history does
  not apply. Nothing persists beyond the tab.
- The byte store is an in-memory dict implementing the same ``ObjectStore``
  protocol as the filesystem store (put/open/exists, sha256 keys).
- No Redis: ``POST .../analyze`` creates and dispatches jobs through the real
  handler (whose dispatch report honestly says the queue is unavailable) and
  then executes the created jobs INLINE through the real
  ``execute_processing_job`` path — the demo's worker is this tab. The
  response reports the post-execution job states.
- Guidance runs the deterministic template fallback only: no model weights
  ship with the demo, so ``local_model`` stays typed-unavailable (D39) and
  answers carry ``mode=template`` labeling.
- The dev-stub identity is resolved directly (``X-MV-Principal`` ->
  ``Principal(..., via="session_header")``), the same identity the real API
  resolves for a development-header session; capture-token identities are not
  part of the demo flow.
- The browser bootstrap registers a raising stub for the stdlib ``resource``
  module before importing the service tree: ``packages/perception/__init__``
  pulls in ``media.limits`` (rlimit setup for media tool subprocesses), and
  wasm has no rlimit API. Every stub call raises ``NotImplementedError``; the
  demo never invokes it because no media tool subprocess runs in-browser.

Errors use the same typed envelope via ``safe_error`` and the same
``STATUS_BY_CODE`` mapping as the product API (docs/03).
"""
from __future__ import annotations

import asyncio
import json
import re
import uuid
from dataclasses import dataclass, field
from pathlib import Path
from types import SimpleNamespace
from typing import Any

import sqlalchemy
from sqlalchemy import event
from sqlalchemy.orm import sessionmaker
from sqlalchemy.pool import StaticPool
from starlette.responses import Response as StarletteResponse

from security.error_contract import safe_error
from services.api.app.config import Settings, capabilities_for_settings
from services.api.app.db import Base
from services.api.app.dto import (
    AnalyzeRequest,
    AssociationCreate,
    CalibrationCreate,
    CaptureRequestCreate,
    CheckpointCreate,
    ClassroomCreate,
    CorrectionCreate,
    DecisionCreate,
    DesignImport,
    ProjectCreate,
    QuestionCreate,
    ResearchExportCreate,
    UploadCreate,
)
from services.api.app.errors import ApiError
from services.api.app.objectstore import ObjectStore, validate_key
from services.api.app.routers import (
    checkpoints as checkpoint_routes,
    guidance as guidance_routes,
    longitudinal as longitudinal_routes,
    media as media_routes,
    projects as project_routes,
    session as session_routes,
)
from services.api.app.security import Principal
from services.api.app.services.jobexec import execute_processing_job
from services.api.app.serializers import job_dto

# --- demo-owned infrastructure (store + request stand-in) -------------------


class MemoryObjectStore:
    """Same ``ObjectStore`` protocol as ``FileSystemObjectStore``, in-memory.

    Upload bytes live only in this tab's memory; the sha256-keyed content
    contract is identical, so ``complete_upload`` integrity checks and
    ``GET /assets/{id}/content`` read the same shapes.
    """

    def __init__(self) -> None:
        self._objects: dict[str, bytes] = {}

    def put(self, data: bytes) -> tuple[str, int]:
        from packages.domain.hashing import sha256_hex

        digest = sha256_hex(bytes(data))
        self._objects[digest] = bytes(data)
        return digest, len(data)

    def open(self, key: str) -> bytes:
        validate_key(key)
        return self._objects[key]

    def exists(self, key: str) -> bool:
        try:
            return validate_key(key) in self._objects
        except ValueError:
            return False


@dataclass
class DemoState:
    """Everything one demo tab owns: settings, store, session factory."""

    settings: Settings
    capabilities: Any
    session_factory: sessionmaker
    object_store: MemoryObjectStore = field(default_factory=MemoryObjectStore)


class _DemoRequest:
    """Minimal ``Request`` stand-in for handlers that read app state/body."""

    def __init__(self, state: DemoState, headers: dict[str, str], body: bytes, correlation_id: str) -> None:
        self.headers = headers
        self._body = body
        self.state = SimpleNamespace(correlation_id=correlation_id)
        self.app = SimpleNamespace(
            state=SimpleNamespace(
                settings=state.settings,
                capabilities=state.capabilities,
                object_store=state.object_store,
            )
        )

    async def body(self) -> bytes:
        return self._body


@dataclass
class RouteResult:
    status: int
    payload: Any = None
    body: bytes | None = None
    content_type: str = "application/json"


# --- demo identity (dev-stub session header, resolved like the real API) ----


def _principal_from_headers(headers: dict[str, str]) -> Principal:
    # HTTP header names are case-insensitive (starlette lowercases on the
    # product path); the browser's Headers instance normalizes to lowercase.
    lower = {str(name).lower(): value for name, value in headers.items()}
    principal_id = (lower.get("x-mv-principal") or "").strip()
    if not principal_id:
        raise ApiError("unauthorized", "A principal header or capture token is required")
    if principal_id.startswith(("mvcap_", "mvsess_")):
        raise ApiError("unauthorized", "Credentials cannot be used as a principal header")
    return Principal(principal_id, "principal", frozenset(), "session_header")


# --- dispatch table ----------------------------------------------------------
# Each entry adapts ONE route to the REAL handler with explicit arguments.
# Status codes mirror the route decorators. Nothing else is reimplemented.

ROUTES: list[tuple[str, re.Pattern[str], Any]] = []


def _route(method: str, pattern: str):
    def register(fn):
        ROUTES.append((method, re.compile(pattern), fn))
        return fn

    return register


def _int_query(query: dict[str, str], name: str, default: int, low: int, high: int) -> int:
    raw = query.get(name)
    if raw is None:
        return default
    try:
        value = int(raw)
    except ValueError as exc:
        raise ApiError("unprocessable_entity", f"Query parameter {name} must be an integer") from exc
    if value < low or value > high:
        raise ApiError("unprocessable_entity", f"Query parameter {name} is out of range")
    return value


def _json(payload: Any) -> Any:
    """Mirror FastAPI's response_model serialization for the shapes the demo
    handlers return: single models and bare lists (e.g. list_classroom_projects
    declares response_model=list[ProjectResponse])."""
    if isinstance(payload, list):
        return [item.model_dump(mode="json") for item in payload]
    return payload.model_dump(mode="json")


