@_route("POST", r"^/api/v1/checkpoints/([^/]+)/analyze$")
async def _analyze(state, ctx, session, principal):
    """Real handler, then the demo's in-tab worker executes the created jobs.

    The dispatch entries in the response still report what the real queue
    dispatch returned (typed unavailable without Redis). Job states in the
    response are re-read AFTER inline execution through
    ``execute_processing_job`` — the same executor the product worker runs.
    """
    response = checkpoint_routes.analyze_checkpoint(
        checkpoint_id=ctx.match.group(1), payload=AnalyzeRequest.model_validate(ctx.json_body()),
        request=ctx.request, principal=principal, session=session, correlation_id=ctx.correlation_id,
    )
    from services.api.app.models import ProcessingJob

    executed: list[str] = []
    for job in response.jobs:
        if job.state == "queued":
            execute_processing_job(session, job.id, settings=state.settings)
            executed.append(job.id)
    session.flush()
    fresh = [job_dto(session.get(ProcessingJob, job.id)) for job in response.jobs]
    payload = response.model_copy(update={"jobs": fresh})
    return RouteResult(202, _json(payload))


