# --- dispatcher --------------------------------------------------------------


class _Context:
    """Per-request adapter passed to every route wrapper."""

    def __init__(self, state: DemoState, headers: dict[str, str], body: bytes, query: dict[str, str]) -> None:
        self.correlation_id = uuid.uuid4().hex
        self.headers = headers
        self.body_bytes = body
        self.query = query
        self.request = _DemoRequest(state, headers, body, self.correlation_id)

    def json_body(self) -> dict[str, Any]:
        if not self.body_bytes:
            return {}
        try:
            parsed = json.loads(self.body_bytes.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise ApiError("unprocessable_entity", "Request body is not valid JSON") from exc
        if parsed is None:
            return {}
        if not isinstance(parsed, dict):
            raise ApiError("unprocessable_entity", "Request body must be a JSON object")
        return parsed


def _error_envelope(code: str, message: str | None, correlation_id: str, retryable: bool, status: int,
                    details: list | None = None) -> RouteResult:
    body = safe_error(code=code, correlation_id=correlation_id, retryable=retryable, message=message)
    if details:
        body["details"] = details
    return RouteResult(status, body)


async def handle(
    state: DemoState,
    method: str,
    path: str,
    *,
    body: bytes | str | dict | None = None,
    headers: dict[str, str] | None = None,
    query: dict[str, str] | None = None,
) -> RouteResult:
    """Translate one HTTP-shaped call to the real service layer.

    Session lifecycle mirrors ``get_db``: the handler's session commits on
    success and rolls back on any failure.
    """
    headers = {k: v for k, v in (headers or {}).items()}
    query = {k: v for k, v in (query or {}).items()}
    if isinstance(body, str):
        body_bytes = body.encode("utf-8")
    elif isinstance(body, dict):
        body_bytes = json.dumps(body).encode("utf-8")
    else:
        body_bytes = bytes(body or b"")
    ctx = _Context(state, headers, body_bytes, query)

    normalized = method.upper()
    for route_method, pattern, fn in ROUTES:
        if route_method != normalized:
            continue
        match = pattern.match(path)
        if match is None:
            continue
        ctx.match = match
        session = state.session_factory()
        try:
            # Bootstrap reads are public in the product API (no principal
            # dependency on the FastAPI routes); the browser fetches them
            # before any identity exists.
            principal = None if fn in PUBLIC_HANDLERS else _principal_from_headers(headers)
            result = fn(state, ctx, session, principal)
            if asyncio.iscoroutine(result):
                result = await result
            session.commit()
            return result
        except ApiError as exc:
            session.rollback()
            return _error_envelope(exc.code, exc.message, ctx.correlation_id, exc.retryable, exc.status, exc.details)
        except Exception as exc:  # pydantic.ValidationError lands here too
            session.rollback()
            from pydantic import ValidationError

            if isinstance(exc, ValidationError):
                details = [
                    {"loc": [str(part) for part in error.get("loc", [])], "msg": str(error.get("msg", ""))}
                    for error in exc.errors()
                ]
                return _error_envelope("unprocessable_entity", "Request failed schema validation",
                                       ctx.correlation_id, False, 422, details)
            # Honest 500: same withheld-details envelope as the product API.
            print(f"[demo] unhandled error type={type(exc).__name__}: {exc}")
            return _error_envelope("internal_error", None, ctx.correlation_id, False, 500)
        finally:
            session.close()
    return _error_envelope("not_found", None, ctx.correlation_id, False, 404)


def _run_coro(coro: Any) -> Any:
    """Drive a handler coroutine to completion without an event loop.

    ``handle`` never awaits a pending future (``_DemoRequest.body`` returns
    immediately), so one ``send`` runs the whole chain. ``asyncio.run`` cannot
    be used in the browser: Pyodide's webloop raises ``TypeError`` on foreign
    awaitables.
    """
    try:
        coro.send(None)
    except StopIteration as stop:
        return stop.value
    raise RuntimeError("demo coroutine suspended unexpectedly")


def handle_sync(state: DemoState, method: str, path: str, **kwargs: Any) -> RouteResult:
    """Blocking convenience wrapper (CPython tests; Pyodide JS uses ``handle``)."""
    return _run_coro(handle(state, method, path, **kwargs))


# --- store construction --------------------------------------------------------


def make_demo_state(*, config_path: Path, data_root: Path) -> DemoState:
    """In-memory store from the SAME models; no Alembic in the demo.

    ``config_path`` points at the vendored ``configs/runtime.json`` (build
    side copies it into the demo assets) so capabilities come from the same
    fixture-mode configuration the product uses.
    """
    data_root = Path(data_root)
    data_root.mkdir(parents=True, exist_ok=True)
    settings = Settings(
        database_url="sqlite://",
        data_root=data_root,
        config_path=Path(config_path),
        fixture_mode=True,
        host="127.0.0.1",
        capture_token_ttl_seconds=900,
        default_upload_max_bytes=1024 * 1024,
        sse_poll_seconds=0.01,
        sse_max_seconds=2.0,
    )
    # Same SQLite constraints as services.api.app.db.create_engine (FKs on),
    # with StaticPool so the single in-memory database is shared per tab.
    engine = sqlalchemy.create_engine("sqlite://", poolclass=StaticPool, connect_args={"check_same_thread": False})

    @event.listens_for(engine, "connect")
    def _fk_on(dbapi_connection, connection_record):  # pragma: no cover - driver hook
        cursor = dbapi_connection.cursor()
        cursor.execute("PRAGMA foreign_keys=ON")
        cursor.close()

    Base.metadata.create_all(bind=engine)
    return DemoState(
        settings=settings,
        capabilities=capabilities_for_settings(settings),
        session_factory=sessionmaker(bind=engine, expire_on_commit=False, autoflush=False),
    )


