DEMO_CAPTURE_BYTES = b"mv-demo-synthetic-capture-bytes-not-real-media"
DEMO_CAPTURE_NAME = "synthetic-demo-clip.mp4"


def seed_demo_project(
    state: DemoState,
    *,
    ldraw_text: str,
    sidecar: dict,
    verified_by: str = "mv-e7-demo-bootstrap",
    verified_on: str = "2026-11-02",
    principal: str = DEMO_PRINCIPAL,
) -> dict[str, Any]:
    """Scaffold the demo project through the SAME route handlers the UI calls.

    Order mirrors tests/api/test_lego_vertical_slice.py: classroom -> project
    -> real-8285 design import (``import_ldraw_document`` output verbatim)
    -> checkpoint -> labeled synthetic capture upload. The demo starts with
    NO checkpoint media; capture and analysis are user-driven through the UI
    or the demo panel.
    """
    from packages.mechanisms.ldraw import import_ldraw_document

    headers = {"X-MV-Principal": principal}

    def call(method: str, path: str, **kwargs: Any) -> dict[str, Any]:
        result = _run_coro(handle(state, method, path, headers=headers, **kwargs))
        if result.status >= 400:
            raise RuntimeError(f"demo seed failed at {method} {path}: {result.status} {result.payload}")
        return result.payload

    classroom = call("POST", "/api/v1/classrooms", body={"name": DEMO_CLASSROOM})
    project = call("POST", "/api/v1/projects", body={
        "classroom_id": classroom["id"], "name": DEMO_PROJECT,
    })
    payload = import_ldraw_document(
        ldraw_text,
        source_name="8285-1.mpd",
        project_id=project["id"],
        version_id=DEMO_VERSION_ID,
        verified_by=verified_by,
        verified_on=verified_on,
        source_url=sidecar.get("source_url"),
    )
    imported = call("POST", f"/api/v1/projects/{project['id']}/designs/import", body={"payload": payload})
    checkpoint = call("POST", f"/api/v1/projects/{project['id']}/checkpoints", body={
        "design_version_id": imported["version_id"],
        "phase": "test",
        "group_pseudonym": "demo-group-1",
        "build_version_confidence": "explicit",
    })
    return {
        "classroom_id": classroom["id"],
        "project_id": project["id"],
        "design_version_id": imported["version_id"],
        "checkpoint_id": checkpoint["id"],
    }


def capture_demo_clip(state: DemoState, checkpoint_id: str, *, principal: str = DEMO_PRINCIPAL) -> dict[str, Any]:
    """The labeled synthetic capture: the same three-call upload contract the
    UI performs (stage -> content -> complete), with the motion-sample
    manifest the fixture stall rule reads. No decoded media exists."""
    headers = {"X-MV-Principal": principal}
    content_type = "video/mp4"

    async def _capture() -> dict[str, Any]:
        created = await handle(state, "POST", f"/api/v1/checkpoints/{checkpoint_id}/uploads", headers=headers, body={
            "kind": "video",
            "content_type": content_type,
            "size_bytes": len(DEMO_CAPTURE_BYTES),
            "duration_ms": 1000,
            "audio_status": "missing",
            "origin": "synthetic_media",
            "privacy_class": "synthetic_public",
            "consent_use_flags": ["analysis", "teaching_review"],
            "original_name": DEMO_CAPTURE_NAME,
            "synthetic_manifest": {
                "note": "synthetic demo data, clearly labeled; no real media",
                "motion_samples": DEMO_MOTION_SAMPLES,
            },
        })
        if created.status >= 400:
            raise RuntimeError(f"demo capture failed at create: {created.status} {created.payload}")
        stored = await handle(state, "PUT", f"/api/v1/uploads/{created.payload['id']}/content",
                              headers={**headers, "Content-Type": content_type}, body=DEMO_CAPTURE_BYTES)
        if stored.status >= 400:
            raise RuntimeError(f"demo capture failed at content: {stored.status} {stored.payload}")
        completed = await handle(state, "POST", f"/api/v1/uploads/{created.payload['id']}/complete", headers=headers, body={})
        if completed.status >= 400:
            raise RuntimeError(f"demo capture failed at complete: {completed.status} {completed.payload}")
        return completed.payload

    return _run_coro(_capture())

